INSERT INTO "BASETENANT".certificate_type (id, code, name, description, sector, instrument_type, allowed_issue_type, validity_mode, validity_period_days, max_validity_period_days, grace_period_days, is_active, submission_verification_mode, id_format_config, eligibility_criteria, category_config, boundary_config, config_version, is_latest, version, created_by, created_time, last_modified_by, last_modified_time, is_template, is_renewable, auto_approve, template_code) VALUES ('7773e2ed-3f90-4b97-b3c4-3bcc79e05ecf', 'BUSINESS_LICENSE', 'Business License', 'License to operate a business within the municipal jurisdiction.', 'TRADE', 'LICENSE', 'BOTH', 'FIXED', 365, NULL, 30, false, 'OTP', '{"applicationIdTemplate": "BUSINESS_LICENSE-APP-{SEQ}", "certificateIdTemplate": "BUSINESS_LICENSE-CERT-{SEQ}", "applicationIdTemplateCode": "BUSINESS_LICENSE-app-business-license", "certificateIdTemplateCode": "BUSINESS_LICENSE-cert-business-license", "sameCertificateNoAsApplicationNo": false}', '["Applicant must be at least 18 years old.", "The business premises must fall within the tenant''s municipal boundary.", "The applicant must have no unresolved business-licence violations."]', '{"enabled": false, "levelNames": ["Sector", "Category", "Sub-Category"], "noOfLevels": 3, "mandatoryUpToLevel": 3, "workflowCategoryLevel": null, "workflowDependsOnCategory": null}', '{"enabled": true, "hierarchyType": "ESMAGICO-PC-Hierarchy-V3", "lowestBoundaryType": "PARLIAMENTARY_CONSTITUENCY"}', 1, false, 1, 'e2df874c-b93e-42d3-82cf-d5452f4af31a', '2026-08-31 05:56:14.491227+00', 'e2df874c-b93e-42d3-82cf-d5452f4af31a', '2026-09-03 12:45:28.878585+00', false, true, false, NULL);
INSERT INTO "BASETENANT".certificate_type (id, code, name, description, sector, instrument_type, allowed_issue_type, validity_mode, validity_period_days, max_validity_period_days, grace_period_days, is_active, submission_verification_mode, id_format_config, eligibility_criteria, category_config, boundary_config, config_version, is_latest, version, created_by, created_time, last_modified_by, last_modified_time, is_template, is_renewable, auto_approve, template_code) VALUES ('5de67650-85e0-4a19-a0db-62a1c76d6483', 'LEARNER_LICENSE', 'Learner''s License (LL)', 'This is your first step to becoming a licensed driver — it lets you practice driving on public roads with a licensed driver alongside you. Once you''ve passed a simple test on traffic rules and signs, you''re good to start practicing before applying for your full license.', 'TRANSPORT', 'LICENSE', 'INDIVIDUAL', 'FIXED', 365, NULL, 30, true, 'OTP', '{"applicationIdTemplate": null, "certificateIdTemplate": null, "applicationIdTemplateCode": "LEARNER_LICENSE-app-basetenant", "certificateIdTemplateCode": "LEARNER_LICENSE-cert-basetenant", "sameCertificateNoAsApplicationNo": false}', '["The applicant must be at least 16 years old, with the written consent of a parent or guardian, for a motorcycle without gear not exceeding 50cc.", "The applicant must be at least 18 years old for a Light Motor Vehicle or geared motorcycle learner''s licence.", "The applicant must be at least 20 years old for any Transport class learner''s licence.", "The applicant must pass the prescribed eyesight test and the theory test on traffic signs, signals and road rules.", "The applicant must not be disqualified from holding a licence by any court or licensing authority.", "A learner''s licence is valid for six months and is not renewable. It must be held for at least 30 days before a permanent licence may be applied for, and the permanent application must be filed before it lapses."]', '{"enabled": true, "levelNames": ["Vehicle Class Group", "Vehicle Class"], "noOfLevels": 2, "mandatoryUpToLevel": 2}', '{"enabled": false, "hierarchyType": null, "lowestBoundaryType": null}', 1, true, 3, 'e2df874c-b93e-42d3-82cf-d5452f4af31a', '2026-09-01 05:37:31.79207+00', 'e2df874c-b93e-42d3-82cf-d5452f4af31a', '2026-09-03 12:47:42.209465+00', true, true, false, NULL);
INSERT INTO "BASETENANT".certificate_type (id, code, name, description, sector, instrument_type, allowed_issue_type, validity_mode, validity_period_days, max_validity_period_days, grace_period_days, is_active, submission_verification_mode, id_format_config, eligibility_criteria, category_config, boundary_config, config_version, is_latest, version, created_by, created_time, last_modified_by, last_modified_time, is_template, is_renewable, auto_approve, template_code) VALUES ('9e8dc49e-69b8-4d94-960d-1e0763efb79b', 'FIRE_NOC', 'FIRE_NOC', 'Certificate type FIRE_NOC.', 'OTHER', 'NOC', 'BOTH', 'FIXED', 365, NULL, 30, false, 'OTP', '{"applicationIdTemplate": "FIRE_NOC-APP-{SEQ}", "certificateIdTemplate": "FIRE_NOC-CERT-{SEQ}", "applicationIdTemplateCode": "FIRE_NOC-app-fire-noc", "certificateIdTemplateCode": "FIRE_NOC-cert-fire-noc", "sameCertificateNoAsApplicationNo": false}', '["The property must fall within the tenant''s municipal boundary.", "The building''s fire-fighting and fire-detection systems must be installed prior to inspection.", "The applicant must have no unresolved fire safety violations on record."]', '{"enabled": false, "levelNames": ["Usage Group", "Sub-type"], "noOfLevels": 2, "mandatoryUpToLevel": 2, "workflowCategoryLevel": null, "workflowDependsOnCategory": null}', '{"enabled": true, "hierarchyType": "ESMAGICO-PC-Hierarchy-V3", "lowestBoundaryType": "PARLIAMENTARY_CONSTITUENCY"}', 1, false, 1, 'e2df874c-b93e-42d3-82cf-d5452f4af31a', '2026-08-31 05:56:12.497864+00', 'e2df874c-b93e-42d3-82cf-d5452f4af31a', '2026-09-03 12:38:23.913268+00', false, true, false, NULL);
INSERT INTO "BASETENANT".certificate_type (id, code, name, description, sector, instrument_type, allowed_issue_type, validity_mode, validity_period_days, max_validity_period_days, grace_period_days, is_active, submission_verification_mode, id_format_config, eligibility_criteria, category_config, boundary_config, config_version, is_latest, version, created_by, created_time, last_modified_by, last_modified_time, is_template, is_renewable, auto_approve, template_code) VALUES ('717af216-40f7-487b-a154-ff202d36b1d7', 'DRIVING_LICENSE', 'Driving License (DL)', 'This is your official permit to drive on public roads on your own — no supervision needed. You get it after practicing with your Learner''s License and passing a driving test that checks your road skills and knowledge of traffic rules. It''s valid for several years before you''ll need to renew it.', 'TRANSPORT', 'LICENSE', 'INDIVIDUAL', 'FIXED', 365, NULL, 30, true, 'OTP', '{"applicationIdTemplate": null, "certificateIdTemplate": null, "applicationIdTemplateCode": "DRIVING_LICENSE-app-basetenant", "certificateIdTemplateCode": "DRIVING_LICENSE-cert-basetenant", "sameCertificateNoAsApplicationNo": false}', '["The applicant must be at least 18 years old for a Light Motor Vehicle or geared motorcycle licence, and at least 16 for a motorcycle without gear with guardian consent.", "The applicant must be at least 20 years old and hold a valid Light Motor Vehicle licence for at least one year before applying for any Transport class.", "A valid learner''s licence held for at least 30 days is required before applying for a permanent licence.", "The applicant must pass the prescribed eyesight, theory and practical driving tests.", "The applicant must not be disqualified from holding a licence by any court or licensing authority."]', '{"enabled": true, "levelNames": ["Vehicle Class Group", "Vehicle Class"], "noOfLevels": 2, "mandatoryUpToLevel": 2}', '{"enabled": false, "hierarchyType": null, "lowestBoundaryType": null}', 1, true, 2, 'e2df874c-b93e-42d3-82cf-d5452f4af31a', '2026-09-01 15:48:47.289751+00', 'e2df874c-b93e-42d3-82cf-d5452f4af31a', '2026-09-03 12:48:46.119103+00', true, true, false, NULL);
INSERT INTO "BASETENANT".certificate_type (id, code, name, description, sector, instrument_type, allowed_issue_type, validity_mode, validity_period_days, max_validity_period_days, grace_period_days, is_active, submission_verification_mode, id_format_config, eligibility_criteria, category_config, boundary_config, config_version, is_latest, version, created_by, created_time, last_modified_by, last_modified_time, is_template, is_renewable, auto_approve, template_code) VALUES ('6d355d27-184d-439d-a1ba-46accb54f976', 'BUSINESS_LICENSE', 'Business License (Trade License)', 'This license gives you official permission from your local municipal body to run your business at a chosen location. It''s your way of showing you''re operating legally and meeting basic safety and hygiene standards — and you''ll need to renew it from time to time.', 'TRADE', 'LICENSE', 'BOTH', 'FIXED', 365, NULL, 30, true, 'OTP', '{"applicationIdTemplate": null, "certificateIdTemplate": null, "applicationIdTemplateCode": "BUSINESS_LICENSE-app-basetenant", "certificateIdTemplateCode": "BUSINESS_LICENSE-cert-basetenant", "sameCertificateNoAsApplicationNo": false}', '["Applicant must be at least 18 years old.", "The business premises must fall within the tenant''s municipal boundary.", "The applicant must have no unresolved business-licence violations."]', '{"enabled": true, "levelNames": ["Sector", "Category", "Sub-Category"], "noOfLevels": 3, "mandatoryUpToLevel": 3}', '{"enabled": false, "hierarchyType": null, "lowestBoundaryType": null}', 2, true, 0, NULL, '2026-09-03 12:45:28.880866+00', NULL, '2026-09-03 12:45:28.880866+00', true, true, false, NULL);
INSERT INTO "BASETENANT".certificate_type (id, code, name, description, sector, instrument_type, allowed_issue_type, validity_mode, validity_period_days, max_validity_period_days, grace_period_days, is_active, submission_verification_mode, id_format_config, eligibility_criteria, category_config, boundary_config, config_version, is_latest, version, created_by, created_time, last_modified_by, last_modified_time, is_template, is_renewable, auto_approve, template_code) VALUES ('da917584-60b5-44b6-aa28-411d19b32426', 'FIRE_NOC', 'Fire NOC (No Objection Certificate)', 'This certificate confirms your building has the fire safety equipment and setup needed to keep people safe — things like extinguishers, alarms, and clear exit routes. You''ll need it to get your business up and running (or renew your license) if you run a shop, office, school, or similar space.', 'OTHER', 'NOC', 'BOTH', 'FIXED', 365, NULL, 30, true, 'OTP', '{"applicationIdTemplate": null, "certificateIdTemplate": null, "applicationIdTemplateCode": "FIRE_NOC-app-basetenant", "certificateIdTemplateCode": "FIRE_NOC-cert-basetenant", "sameCertificateNoAsApplicationNo": false}', '["The property must fall within the tenant''s municipal boundary.", "The building''s fire-fighting and fire-detection systems must be installed prior to inspection.", "The applicant must have no unresolved fire safety violations on record."]', '{"enabled": true, "levelNames": ["Usage Group", "Sub-type"], "noOfLevels": 2, "mandatoryUpToLevel": 2}', '{"enabled": false, "hierarchyType": null, "lowestBoundaryType": null}', 2, true, 1, NULL, '2026-09-03 12:38:23.944686+00', NULL, '2026-09-03 12:46:19.826515+00', true, true, false, NULL);
INSERT INTO "BASETENANT".certificate_type (id, code, name, description, sector, instrument_type, allowed_issue_type, validity_mode, validity_period_days, max_validity_period_days, grace_period_days, is_active, submission_verification_mode, id_format_config, eligibility_criteria, category_config, boundary_config, config_version, is_latest, version, created_by, created_time, last_modified_by, last_modified_time, is_template, is_renewable, auto_approve, template_code) VALUES ('b3c3959c-76d9-43ec-a74b-55ac53b29864', 'FOOD_LICENSE', 'Food License', 'This license shows that your food business — whether it''s a restaurant, food stall, or manufacturing unit — meets basic hygiene and safety standards for the food you sell or serve. It''s required before you start operating and needs to be renewed periodically to keep serving customers with confidence.', 'FOOD_SAFETY', 'LICENSE', 'BOTH', 'FIXED', 365, NULL, 30, true, 'OTP', '{"applicationIdTemplate": null, "certificateIdTemplate": null, "applicationIdTemplateCode": "FOOD_LICENSE-app-basetenant", "certificateIdTemplateCode": "FOOD_LICENSE-cert-basetenant", "sameCertificateNoAsApplicationNo": false}', '["The premises must comply with the hygiene and sanitation requirements applicable to the declared activity.", "An operator handling product of animal origin requires the APPROVAL class; the application schema enforces this.", "An operator whose turnover exceeds the notify-only ceiling cannot hold the REGISTRATION class; the application schema enforces this.", "A HACCP or equivalent food safety management plan is required for the APPROVAL class.", "Food handlers must hold current medical fitness records where the applicable regime requires them."]', '{"enabled": true, "levelNames": ["Activity Group", "Activity"], "noOfLevels": 2, "mandatoryUpToLevel": 1}', '{"enabled": false, "hierarchyType": null, "lowestBoundaryType": null}', 1, true, 2, 'e2df874c-b93e-42d3-82cf-d5452f4af31a', '2026-09-01 15:49:04.786836+00', 'e2df874c-b93e-42d3-82cf-d5452f4af31a', '2026-09-03 12:50:34.717597+00', true, true, false, NULL);
