INSERT INTO "BASETENANT".pdf_v3_templates (id, module_code, entity_code, version, status, template_json, created_by, created_at, updated_by, updated_at, is_deleted) VALUES ('ea55ba60-3117-499c-baa9-ff82d6791dea', 'FIRE_NOC', 'LICENSE', 6, 'ACTIVE', '{"pages": [{"width": 794, "height": 1123, "objects": [{"id": "el-header-band", "top": 0, "fill": "#E8E8E8", "left": 0, "type": "rect", "width": 794, "height": 124, "stroke": null, "evented": true, "selectable": true, "strokeWidth": 0}, {"id": "el-logo-circle", "rx": 26, "ry": 26, "top": 36, "fill": "#ffffff", "left": 48, "type": "rect", "width": 52, "height": 52, "stroke": "#CCCCCC", "strokeWidth": 1}, {"id": "el-logo-label", "top": 55, "fill": "#888888", "left": 48, "text": "Logo", "type": "i-text", "width": 52, "height": 16, "fontSize": 10, "textAlign": "center", "fontFamily": "Helvetica", "fontWeight": "normal"}, {"id": "el-cert-id-label", "top": 158, "fill": "#555555", "left": 48, "text": "Certificate ID", "type": "i-text", "width": 300, "height": 18, "fontSize": 13, "textAlign": "left", "fontFamily": "Helvetica", "fontWeight": "bold"}, {"id": "el-cert-id-value", "top": 180, "fill": "#888888", "left": 48, "text": "{{certificateNumber}}", "type": "i-text", "width": 340, "height": 20, "fontSize": 13, "textAlign": "left", "fontFamily": "Helvetica", "fontWeight": "normal"}, {"id": "el-title", "top": 252, "fill": "#1a1a1a", "left": 48, "text": "FIRE NO OBJECTION CERTIFICATE", "type": "i-text", "width": 698, "fontSize": 26, "fontStyle": "italic", "textAlign": "center", "fontFamily": "Times New Roman", "fontWeight": "bold"}, {"id": "el-intro", "top": 340, "fill": "#1a1a1a", "left": 48, "text": "This is to certify that the fire safety measures installed at the premises described below have been inspected and that No Objection is raised for the use/occupation of the said premises, subject to compliance with prescribed fire safety norms.", "type": "textbox", "width": 698, "fontSize": 13, "fontFamily": "Helvetica", "lineHeight": 1.4}, {"id": "el-holder-name", "top": 428, "fill": "#1a1a1a", "left": 48, "text": "Holder Name: {{[holder.name]}}", "type": "i-text", "width": 698, "fontSize": 13, "fontFamily": "Helvetica", "fontWeight": "normal"}, {"id": "el-application-no", "top": 452, "fill": "#1a1a1a", "left": 48, "text": "Application No: {{applicationNumber}}", "type": "i-text", "width": 698, "fontSize": 13, "fontFamily": "Helvetica", "fontWeight": "normal"}, {"id": "el-address", "top": 476, "fill": "#1a1a1a", "left": 48, "text": "Address: {{address}}", "type": "textbox", "width": 698, "fontSize": 13, "fontFamily": "Helvetica", "fontWeight": "normal", "lineHeight": 1.4}, {"id": "el-valid-from-label", "top": 500, "fill": "#1a1a1a", "left": 48, "text": "Valid From:", "type": "i-text", "width": 100, "fontSize": 13, "fontFamily": "Helvetica", "fontWeight": "normal"}, {"id": "el-valid-from-value", "top": 500, "fill": "#1a1a1a", "left": 148, "text": "{{validFrom}}", "type": "i-text", "width": 240, "fontSize": 13, "fontFamily": "Helvetica", "fontWeight": "normal"}, {"id": "el-valid-to-label", "top": 524, "fill": "#1a1a1a", "left": 48, "text": "Valid To:", "type": "i-text", "width": 100, "fontSize": 13, "fontFamily": "Helvetica", "fontWeight": "normal"}, {"id": "el-valid-to-value", "top": 524, "fill": "#1a1a1a", "left": 148, "text": "{{validUntil}}", "type": "i-text", "width": 240, "fontSize": 13, "fontFamily": "Helvetica", "fontWeight": "normal"}, {"id": "el-closing", "top": 568, "fill": "#1a1a1a", "left": 48, "text": "This certificate is valid for the period stated above and is liable to be revoked in case of any violation of fire safety norms, unauthorized structural change, or change in occupancy.", "type": "textbox", "width": 698, "fontSize": 13, "fontFamily": "Helvetica", "lineHeight": 1.4}, {"id": "el-footer-band", "top": 838, "fill": "#E8E8E8", "left": 0, "type": "rect", "width": 794, "height": 203, "stroke": null, "evented": true, "selectable": true, "strokeWidth": 0}, {"id": "el-signature-label", "top": 975, "fill": "#444444", "left": 48, "text": "Signature", "type": "i-text", "width": 140, "height": 20, "fontSize": 12, "textAlign": "left", "fontFamily": "Helvetica", "fontWeight": "bold"}, {"id": "b3f0a4a1-2f5e-4c1a-9a3b-6f7e2d4c8a90", "rx": 4, "ry": 4, "top": 872, "fill": "#F8FAFC", "left": 590, "type": "rect", "angle": 0, "flipX": false, "flipY": false, "skewX": 0, "skewY": 0, "width": 128, "height": 128, "scaleX": 1, "scaleY": 1, "shadow": null, "stroke": "#CBD5E1", "opacity": 1, "originX": "left", "originY": "top", "version": "5.5.2", "visible": true, "fillRule": "nonzero", "paintFirst": "fill", "strokeWidth": 1, "isPlaceholder": true, "strokeLineCap": "butt", "strokeUniform": false, "strokeLineJoin": "miter", "backgroundColor": "", "placeholderType": "QR_CODE", "strokeDashArray": [5, 5], "strokeDashOffset": 0, "strokeMiterLimit": 4, "globalCompositeOperation": "source-over"}, {"id": "el-disclaimer", "top": 1064, "fill": "#666666", "left": 97, "text": "This is a computer generated document, Hence requires no signature.", "type": "i-text", "width": 600, "height": 16, "fontSize": 10, "textAlign": "center", "fontFamily": "Helvetica", "fontWeight": "normal"}], "version": "5.3.0", "background": "#ffffff"}]}', 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1790330159206, 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1790330159206, false);
INSERT INTO "BASETENANT".schema_definition (id, module_code, entity_code, tag, version, is_active, notes, schema_body, created_by, created_time, modified_by, modified_time) VALUES ('9bf98f55-ae3f-4174-b5cf-89b1cf904d3d', 'certificate', 'FIRE_NOC.form.001f7632-d809-4b15-99ec-b40234320c27', NULL, 1, true, NULL, '{"type": "object", "$schema": "https://json-schema.org/draft/2020-12/schema", "$comment": "Fire NOC (Provisional) — Section 2 ''Property Details'' ONLY. Sections 1 (Applicant Details), 3 (Documents) and 4 (Declaration) are hardcoded on the frontend, not schema-driven, so they are deliberately absent here — see Template_Details_FireNOC''s Section 2 table. The ''Boundary Hierarchy Fields'' row in that same table is also absent on purpose: boundary selection is driven by certificate_type.boundaryConfig and submitted as CertificateApplyRequest.boundaryDetail, a top-level field outside certificateDetail, not a schema property.", "required": ["numberOfBuildings", "numberOfFloors", "plotSizeSqFt", "groundFloorBuiltUpAreaSqm", "heightOfBuildingMeters"], "properties": {"houseNo": {"type": "string"}, "propertyId": {"type": "string"}, "streetName": {"type": "string"}, "plotSizeSqFt": {"type": "number", "minimum": 1}, "numberOfFloors": {"type": "integer", "minimum": 1}, "numberOfBasements": {"type": "integer", "minimum": 0}, "numberOfBuildings": {"enum": ["SINGLE", "MULTIPLE"], "type": "string"}, "applicableFireStation": {"type": "string"}, "heightOfBuildingMeters": {"type": "number", "minimum": 1}, "groundFloorBuiltUpAreaSqm": {"type": "number", "minimum": 1}}}', 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788153865221, 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788153865221);
INSERT INTO "BASETENANT".schema_definition (id, module_code, entity_code, tag, version, is_active, notes, schema_body, created_by, created_time, modified_by, modified_time) VALUES ('2d30d864-ac55-4da2-a126-aa4a0efe73c0', 'certificate', 'FIRE_NOC.checklist.e076c464-ef1b-4ff0-929e-ae5570bdce88', 'PENDING_INSPECTION.COMPLETE_INSPECTION', 1, true, NULL, '{"type": "object", "title": "Fire NOC Inspection Checklist", "$schema": "https://json-schema.org/draft/2020-12/schema", "required": ["siteVisited", "buildingExists", "fireSafetyEquipmentInstalled", "fireEscapeRoutesAccessible", "fireFightingSystemsFunctional", "buildingPlanMatchesSite", "sitePhotos"], "properties": {"sitePhotos": {"type": "array", "items": {"type": "string", "format": "uri"}, "title": "Site photos", "minItems": 1}, "siteVisited": {"type": "boolean", "title": "Site visited"}, "buildingExists": {"enum": ["YES", "NO"], "type": "string", "title": "Building exists at location"}, "inspectionRemarks": {"type": "string", "title": "Inspection remarks"}, "buildingPlanMatchesSite": {"enum": ["YES", "NO"], "type": "string", "title": "Building plan matches site"}, "fireEscapeRoutesAccessible": {"enum": ["YES", "NO", "PARTIAL"], "type": "string", "title": "Fire escape routes accessible"}, "fireSafetyEquipmentInstalled": {"enum": ["YES", "NO", "PARTIAL"], "type": "string", "title": "Fire safety equipment installed"}, "fireFightingSystemsFunctional": {"enum": ["YES", "NO", "PARTIAL"], "type": "string", "title": "Fire-fighting systems functional"}}}', 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788153866720, 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788153867023);
INSERT INTO "BASETENANT".schema_definition (id, module_code, entity_code, tag, version, is_active, notes, schema_body, created_by, created_time, modified_by, modified_time) VALUES ('b2613fb2-da10-4250-9ea5-cc621597e45b', 'certificate', 'BUSINESS_LICENSE.form.6816e8d7-afca-42cb-985a-fe81af720ba4', NULL, 1, true, NULL, '{"type": "object", "$schema": "https://json-schema.org/draft/2020-12/schema", "required": ["businessName", "ownershipType", "businessRegistrationDate", "annualTurnover", "numberOfEmployees"], "properties": {"businessName": {"type": "string", "minLength": 3}, "ownershipType": {"enum": ["SOLE_PROPRIETOR", "PARTNERSHIP", "PRIVATE_LIMITED", "PUBLIC_LIMITED", "LLP", "OTHER"], "type": "string"}, "annualTurnover": {"type": "number", "minimum": 0}, "numberOfEmployees": {"type": "integer", "minimum": 0}, "businessRegistrationDate": {"type": "string", "format": "date"}}}', 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788153957716, 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788153957716);
INSERT INTO "BASETENANT".schema_definition (id, module_code, entity_code, tag, version, is_active, notes, schema_body, created_by, created_time, modified_by, modified_time) VALUES ('6820c8d1-a695-4ba8-94bd-2a446bb615da', 'certificate', 'BUSINESS_LICENSE.checklist.8073cfc7-1849-4bf8-b115-f3035351fb59', 'PENDING_INSPECTION.COMPLETE_INSPECTION', 1, true, NULL, '{"type": "object", "title": "Business License Field Inspection Checklist", "$schema": "https://json-schema.org/draft/2020-12/schema", "required": ["businessExists", "businessNameMatches", "natureOfBusinessMatches", "businessOperational", "businessPhoto"], "properties": {"businessPhoto": {"type": "array", "items": {"type": "string", "format": "uri"}, "title": "Upload Business Photo", "minItems": 1}, "businessExists": {"type": "boolean", "title": "Business exists at the mentioned address"}, "businessNameMatches": {"type": "boolean", "title": "Business name displayed on premises matches application"}, "businessOperational": {"type": "boolean", "title": "Business is currently operational"}, "natureOfBusinessMatches": {"type": "boolean", "title": "Nature of business matches application"}}}', 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788153958111, 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788153958211);
INSERT INTO "BASETENANT".schema_definition (id, module_code, entity_code, tag, version, is_active, notes, schema_body, created_by, created_time, modified_by, modified_time) VALUES ('44454846-f714-4c3b-92ba-9fdedd9638b6', 'certificate', 'LEARNER_LICENSE.form.b5a00577-ea80-491f-9666-b2f5e45f5d87', NULL, 1, false, NULL, '{"type": "object", "allOf": [{"if": {"required": ["applicationType"], "properties": {"applicationType": {"const": "FRESH"}}}, "else": {"$comment": "ADDITIONAL_CLASS and DUPLICATE are both filed against a learner''s licence the applicant already holds, so the number is the field the officer looks the record up by and cannot be optional. Reached for every non-FRESH value, including any value added to the applicationType enum later — which is the point of expressing it as `else` rather than naming the two values.", "required": ["existingLearnerLicenceNumber"]}, "then": {"$comment": "A first-time licence is the only application that establishes the licence face, so the two statutory identification marks are collected here and nowhere else. ADDITIONAL_CLASS and DUPLICATE reprint what the existing record already holds.", "required": ["identificationMarks"]}, "$comment": "Conditional requiredness — the if/then/else form. The root `required` array can only ever be unconditional, so ''mandatory for this applicationType only'' has to live here, and ajv (Draft 2020-12) is what actually enforces it."}, {"if": {"required": ["guardianConsentProvided"], "properties": {"guardianConsentProvided": {"const": true}}}, "then": {"required": ["guardianName"]}, "$comment": "The dependent-field pair in its simplest form: a boolean gate and the field it unlocks. guardianConsentProvided is asserted by a 16- or 17-year-old applicant''s guardian, and a consent with no consenting party named is unusable on the licence face, so the name follows the assertion. Note what this still cannot express: the age gate itself. ''dateOfBirth is less than 18 years before today'' is not statable in JSON Schema, so consent stays a self-assertion the document_verifier reconciles against dateOfBirth and the GUARDIAN_CONSENT_FORM document by eye at PENDING_DOCUMENT_VERIFICATION."}], "$schema": "https://json-schema.org/draft/2020-12/schema", "$comment": "Learner''s Licence — the licence-specific section of the application ONLY. Applicant identity, addresses, uploaded documents and the declaration are hardcoded on the frontend and submitted to different services entirely (holder/partyDetails, the documents list, the declaration block on CertificateApplyRequest); none of that reaches certificateDetail, so nothing here duplicates them. Boundary (the applicant''s RTO jurisdiction) is driven by certificate_type.boundaryConfig and submitted as CertificateApplyRequest.boundaryDetail, a top-level field outside certificateDetail, so it is deliberately absent here too. Every field a jsonPath elsewhere in this bundle resolves against — calculation-rules/LEARNER_LICENSE.json and vc/LEARNER_LICENSE.json — is a property of this file.", "required": ["applicationType", "vehicleClass", "dateOfBirth", "bloodGroup"], "properties": {"bloodGroup": {"enum": ["A+", "A-", "B+", "B-", "AB+", "AB-", "O+", "O-"], "type": "string"}, "dateOfBirth": {"type": "string", "format": "date", "$comment": "Load-bearing for this type: the statutory minimum age (16 with guardian consent for a gearless motorcycle, 18 otherwise, 20 for Transport) is gated at the learner''s licence, and this is the applicant''s first licence, so there is no prior record to infer age from. The gate is still NOT enforced by the service — no config anywhere can express ''at least 18 years before today'' — so this is collected for the licence face and for the document_verifier''s own check at PENDING_DOCUMENT_VERIFICATION."}, "guardianName": {"type": "string", "$comment": "Name of the consenting parent or guardian. Printed on the learner''s licence for an under-18 holder.", "maxLength": 128}, "vehicleClass": {"type": "object", "$comment": "group is the categoryTree''s own top-level path segment (''nontransport'' / ''transport'') — NOT the display name. licenceClass is the full dotted leaf path. MUST stay value-for-value identical to a DRIVING_LICENSE certificate type''s own tree, because a learner''s licence converts to a permanent licence of the same class and nothing in the platform links the two records. Nested, and therefore NOT searchable — an officer cannot search learner applications by class.", "required": ["group", "licenceClass"], "properties": {"group": {"enum": ["nontransport", "transport"], "type": "string"}, "licenceClass": {"type": "string"}}}, "applicationType": {"enum": ["FRESH", "ADDITIONAL_CLASS", "DUPLICATE"], "type": "string", "$comment": "Drives BASE_FEE and TEST_FEE in the bootstrap version of calculation-rules/LEARNER_LICENSE.json (the reference version in master-bootstrap-data flattens both to unconditional fees, so this field is not consumed there). There is deliberately NO RENEWAL value: a learner''s licence lapses at 180 days and is replaced by a fresh application, never renewed, which is also why gracePeriodDays is 0 and no penalty component exists. Top-level and flat, so it is searchable (CertificateSpecification matches single top-level keys only)."}, "identificationMarks": {"type": "string", "$comment": "Printed on the licence face; two marks is the statutory norm, entered as one free-text line. A string, NOT an array, and that is forced by the PDF: CertificatePdfService.flattenJson skips arrays and nested objects outright rather than half-rendering them, so an array here would be silently absent from every licence document.", "maxLength": 240}, "emergencyContactName": {"type": "string", "maxLength": 128}, "emergencyContactNumber": {"type": "string", "maxLength": 16}, "guardianConsentProvided": {"type": "boolean", "default": false, "$comment": "Set by a 16- or 17-year-old applicant for a gearless motorcycle, whose guardian''s signed consent is statutorily required. A boolean the applicant asserts, backed by the GUARDIAN_CONSENT_FORM document — the service validates neither the assertion nor the document against dateOfBirth, so the document_verifier reconciles the three by eye. Flat, so it is searchable, which is the point: an auditor reviewing minor applicants searches on this."}, "medicalCertificateNumber": {"type": "string", "$comment": "Form 1A medical certificate reference. Statutorily required for every Transport class and for any applicant over 40; the document itself is uploaded against the MEDICAL_CERTIFICATE_FORM_1A category.", "maxLength": 64}, "existingLearnerLicenceNumber": {"type": "string", "$comment": "The learner''s licence being duplicated, or the one an additional class is being added to. Flat, so it is searchable — this is the field an officer looks an applicant up by. Empty for a FRESH application.", "maxLength": 32}}}', 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788241050605, 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788241050605);
INSERT INTO "BASETENANT".schema_definition (id, module_code, entity_code, tag, version, is_active, notes, schema_body, created_by, created_time, modified_by, modified_time) VALUES ('577de130-d990-4909-ada7-9a08686d58f4', 'certificate', 'LEARNER_LICENSE.form.b5a00577-ea80-491f-9666-b2f5e45f5d87', NULL, 4, false, NULL, '{"type": "object", "allOf": [{"if": {"required": ["applicationType"], "properties": {"applicationType": {"const": "FRESH"}}}, "else": {"$comment": "ADDITIONAL_CLASS and DUPLICATE are both filed against a learner''s licence the applicant already holds, so the number is the field the officer looks the record up by and cannot be optional. Reached for every non-FRESH value, including any value added to the applicationType enum later — which is the point of expressing it as `else` rather than naming the two values.", "required": ["existingLearnerLicenceNumber"]}, "then": {"$comment": "A first-time licence is the only application that establishes the licence face, so the two statutory identification marks are collected here and nowhere else. ADDITIONAL_CLASS and DUPLICATE reprint what the existing record already holds.", "required": ["identificationMarks"]}, "$comment": "Conditional requiredness — the if/then/else form. The root `required` array can only ever be unconditional, so ''mandatory for this applicationType only'' has to live here, and ajv (Draft 2020-12, the formAjv singleton in renderers/shared.ts) is what actually enforces it. Three constraints on how these blocks are written, none of them JSON Schema rules — all of them frontend behaviour: (1) the `if` matches on `const`, never `enum`. isFieldCurrentlyRequired (packages/shared/src/utils/jsonforms-rule.ts) only reads `const` out of if.properties and treats an `enum` there as trivially satisfied, so an enum-keyed `if` paints the required asterisk on its `then` fields permanently, from the first render, even though ajv keeps validating correctly. (2) the `if` carries its own `required` naming the field it tests, so the branch cannot fire before the applicant has answered: `properties` alone passes vacuously for absent data, which would apply `then` immediately. (3) a field made required here MUST be visible in exactly the cases it is required. useApplyWizard''s sub-screen Next gating collects every Control in the sub-screen via collectControls WITHOUT filtering on rule visibility, so a required error on a rule-hidden control blocks Next with nothing on screen to fix. identificationMarks is unconditionally visible; existingLearnerLicenceNumber is hidden for exactly FRESH by its uischema rule, which is the precise complement of this `else`. One asymmetry to know when reading the form: isFieldCurrentlyRequired evaluates allOf[].then only and ignores `else` outright, so the `else` branch is enforced by ajv but never draws an asterisk — it surfaces as an inline error once showErrors flips. Splitting it into two `if`/`then` blocks (one per non-FRESH value) would buy the asterisk at the cost of two rules to keep in step; kept as one `else` deliberately."}, {"if": {"required": ["guardianConsentProvided"], "properties": {"guardianConsentProvided": {"const": true}}}, "then": {"required": ["guardianName"]}, "$comment": "The dependent-field pair in its simplest form: a boolean gate and the field it unlocks. guardianConsentProvided is asserted by a 16- or 17-year-old applicant''s guardian, and a consent with no consenting party named is unusable on the licence face, so the name follows the assertion. Visibility and requiredness are driven from the same `const: true` — the uischema SHOW rule on guardianName and this `if` — which is what keeps the field on screen at exactly the moment it becomes mandatory. Note what this still cannot express: the age gate itself. ''dateOfBirth is less than 18 years before today'' is not statable in JSON Schema (nor in a jsonforms rule condition), so consent stays a self-assertion the document_verifier reconciles against dateOfBirth and the GUARDIAN_CONSENT_FORM document by eye at PENDING_DOCUMENT_VERIFICATION."}], "$schema": "https://json-schema.org/draft/2020-12/schema", "$comment": "Learner''s Licence — the licence-specific section of the application ONLY. Applicant identity, addresses, uploaded documents and the declaration are hardcoded on the frontend and submitted to different services entirely (holder/partyDetails, the documents list, the declaration block on CertificateApplyRequest); none of that reaches certificateDetail, so nothing here duplicates them. Boundary (the applicant''s RTO jurisdiction) is driven by certificate_type.boundaryConfig and submitted as CertificateApplyRequest.boundaryDetail, a top-level field outside certificateDetail, so it is deliberately absent here too. Every field a jsonPath elsewhere in this bundle resolves against — calculator/calculation-rules.json and vc/vc-credential-type.json — is a property of this file.", "required": ["applicationType", "vehicleClass", "dateOfBirth", "bloodGroup"], "properties": {"bloodGroup": {"enum": ["A+", "A-", "B+", "B-", "AB+", "AB-", "O+", "O-"], "type": "string", "title": "Blood Group"}, "dateOfBirth": {"type": "string", "title": "Date of Birth", "format": "date", "$comment": "Load-bearing for this type in a way it is not for DRIVING_LICENSE: the statutory minimum age (16 with guardian consent for a gearless motorcycle, 18 otherwise, 20 for Transport) is gated at the learner''s licence, and this is the applicant''s first licence, so there is no prior record to infer age from. The gate is still NOT enforced by the service — no config anywhere can express ''at least 18 years before today'' — so this is collected for the licence face and for the document_verifier''s own check at PENDING_DOCUMENT_VERIFICATION."}, "guardianName": {"type": "string", "title": "Name of Parent or Guardian", "$comment": "Name of the consenting parent or guardian. Printed on the learner''s licence for an under-18 holder.", "maxLength": 128}, "vehicleClass": {"type": "object", "title": "Class of Vehicle", "$comment": "group is the categoryTree''s own top-level path segment (''nontransport'' / ''transport'') — NOT the display name. licenceClass is the full dotted leaf path. MUST stay value-for-value identical to DRIVING_LICENSE''s, because a learner''s licence converts to a permanent licence of the same class and nothing in the platform links the two records. Nested, and therefore NOT searchable — an officer cannot search learner applications by class.", "required": ["group", "licenceClass"], "properties": {"group": {"enum": ["nontransport", "transport"], "type": "string", "title": "Vehicle Class Group"}, "licenceClass": {"type": "string", "title": "Vehicle Class"}}}, "applicationType": {"enum": ["FRESH", "ADDITIONAL_CLASS", "DUPLICATE"], "type": "string", "title": "Application Type", "$comment": "Drives BASE_FEE and TEST_FEE in calculation-rules.json. Both are RATE_MATRIX components, so every value in this enum MUST have a matching rule or RateMatrixEvaluator throws Rule.NoMatch — adding a value here without adding two rules there breaks fee calculation for that value only, at /estimate time. There is deliberately NO RENEWAL value: a learner''s licence lapses at 180 days and is replaced by a fresh application, never renewed, which is also why gracePeriodDays is 0 and no penalty component exists. Top-level and flat, so it is searchable (CertificateSpecification matches single top-level keys only)."}, "identificationMarks": {"type": "string", "title": "Identification Marks", "$comment": "Printed on the licence face; two marks is the statutory norm, entered as one free-text line. A string, NOT an array, and that is forced by the PDF: CertificatePdfService.flattenJson skips arrays and nested objects outright rather than half-rendering them, so an array here would be silently absent from every licence document.", "maxLength": 240}, "emergencyContactName": {"type": "string", "title": "Emergency Contact Name", "maxLength": 128}, "emergencyContactNumber": {"type": "string", "title": "Emergency Contact Number", "maxLength": 16}, "guardianConsentProvided": {"type": "boolean", "title": "A parent or guardian has consented to this application", "default": false, "$comment": "Set by a 16- or 17-year-old applicant for a gearless motorcycle, whose guardian''s signed consent is statutorily required. A boolean the applicant asserts, backed by the GUARDIAN_CONSENT_FORM document — the service validates neither the assertion nor the document against dateOfBirth, so the document_verifier reconciles the three by eye. Flat, so it is searchable, which is the point: an auditor reviewing minor applicants searches on this."}, "medicalCertificateNumber": {"type": "string", "title": "Medical Certificate Number (Form 1A)", "$comment": "Form 1A medical certificate reference. Statutorily required for every Transport class and for any applicant over 40; the document itself is uploaded against the MEDICAL_CERTIFICATE_FORM_1A category.", "maxLength": 64}, "existingLearnerLicenceNumber": {"type": "string", "title": "Existing Learner''s Licence Number", "$comment": "The learner''s licence being duplicated, or the one an additional class is being added to. Flat, so it is searchable — this is the field an officer looks an applicant up by. Empty for a FRESH application.", "maxLength": 32}}}', 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788439661765, 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788439661765);
INSERT INTO "BASETENANT".schema_definition (id, module_code, entity_code, tag, version, is_active, notes, schema_body, created_by, created_time, modified_by, modified_time) VALUES ('cc26918b-f6cd-4780-bbf7-e43f54d11283', 'certificate', 'LEARNER_LICENSE.form.b5a00577-ea80-491f-9666-b2f5e45f5d87', NULL, 5, true, NULL, '{"type": "object", "allOf": [{"if": {"required": ["applicationType"], "properties": {"applicationType": {"const": "FRESH"}}}, "then": {"$comment": "A first-time licence is the only application that establishes the licence face, so the two statutory identification marks are collected here and nowhere else. ADDITIONAL_CLASS and DUPLICATE reprint what the existing record already holds.", "required": ["identificationMarks"]}, "$comment": "Conditional requiredness â€” the if/then/else form. The root `required` array can only ever be unconditional, so ''mandatory for this applicationType only'' has to live here, and ajv (Draft 2020-12, the formAjv singleton in renderers/shared.ts) is what actually enforces it. Three constraints on how these blocks are written, none of them JSON Schema rules â€” all of them frontend behaviour: (1) the `if` matches on `const`, never `enum`. isFieldCurrentlyRequired (packages/shared/src/utils/jsonforms-rule.ts) only reads `const` out of if.properties and treats an `enum` there as trivially satisfied, so an enum-keyed `if` paints the required asterisk on its `then` fields permanently, from the first render, even though ajv keeps validating correctly. (2) the `if` carries its own `required` naming the field it tests, so the branch cannot fire before the applicant has answered: `properties` alone passes vacuously for absent data, which would apply `then` immediately. (3) a field made required here MUST be visible in exactly the cases it is required. useApplyWizard''s sub-screen Next gating collects every Control in the sub-screen via collectControls WITHOUT filtering on rule visibility, so a required error on a rule-hidden control blocks Next with nothing on screen to fix. identificationMarks is unconditionally visible; existingLearnerLicenceNumber is hidden for exactly FRESH by its uischema rule, which is the precise complement of this `else`. One asymmetry to know when reading the form: isFieldCurrentlyRequired evaluates allOf[].then only and ignores `else` outright, so the `else` branch is enforced by ajv but never draws an asterisk â€” it surfaces as an inline error once showErrors flips. Splitting it into two `if`/`then` blocks (one per non-FRESH value) would buy the asterisk at the cost of two rules to keep in step; kept as one `else` deliberately. (The ''else'' branch this block used to carry is now allOf[1], an if/then on not/const - see its own comment for why.)"}, {"if": {"required": ["applicationType"], "properties": {"applicationType": {"not": {"const": "FRESH"}}}}, "then": {"required": ["existingLearnerLicenceNumber"]}, "$comment": "Split out of the first block''s ''else'' branch. Same meaning - ADDITIONAL_CLASS and DUPLICATE are both filed against a learner''s licence the applicant already holds, so the number is the field the officer looks the record up by and cannot be optional - expressed as not/const so it still covers any value added to the applicationType enum later, without naming the two values. Written as its own if/then rather than an else because the admin forms builder reads allOf[].then.required and ignores else.required (formsBuilderSchema.ts requiredFieldIds), so an else branch is silently dropped the first time an admin saves this form from the builder. Side benefit: isFieldCurrentlyRequired also only looks at then.required, so this field now draws its required asterisk, which it never did as an else."}, {"if": {"required": ["guardianConsentProvided"], "properties": {"guardianConsentProvided": {"const": true}}}, "then": {"required": ["guardianName"]}, "$comment": "The dependent-field pair in its simplest form: a boolean gate and the field it unlocks. guardianConsentProvided is asserted by a 16- or 17-year-old applicant''s guardian, and a consent with no consenting party named is unusable on the licence face, so the name follows the assertion. Visibility and requiredness are driven from the same `const: true` â€” the uischema SHOW rule on guardianName and this `if` â€” which is what keeps the field on screen at exactly the moment it becomes mandatory. Note what this still cannot express: the age gate itself. ''dateOfBirth is less than 18 years before today'' is not statable in JSON Schema (nor in a jsonforms rule condition), so consent stays a self-assertion the document_verifier reconciles against dateOfBirth and the GUARDIAN_CONSENT_FORM document by eye at PENDING_DOCUMENT_VERIFICATION."}], "$schema": "https://json-schema.org/draft/2020-12/schema", "$comment": "Learner''s Licence â€” the licence-specific section of the application ONLY. Applicant identity, addresses, uploaded documents and the declaration are hardcoded on the frontend and submitted to different services entirely (holder/partyDetails, the documents list, the declaration block on CertificateApplyRequest); none of that reaches certificateDetail, so nothing here duplicates them. Boundary (the applicant''s RTO jurisdiction) is driven by certificate_type.boundaryConfig and submitted as CertificateApplyRequest.boundaryDetail, a top-level field outside certificateDetail, so it is deliberately absent here too. Every field a jsonPath elsewhere in this bundle resolves against â€” calculator/calculation-rules.json and vc/vc-credential-type.json â€” is a property of this file.", "required": ["applicationType", "vehicleClass", "dateOfBirth", "bloodGroup"], "properties": {"bloodGroup": {"enum": ["A+", "A-", "B+", "B-", "AB+", "AB-", "O+", "O-"], "type": "string", "title": "Blood Group"}, "dateOfBirth": {"type": "string", "title": "Date of Birth", "format": "date", "$comment": "Load-bearing for this type in a way it is not for DRIVING_LICENSE: the statutory minimum age (16 with guardian consent for a gearless motorcycle, 18 otherwise, 20 for Transport) is gated at the learner''s licence, and this is the applicant''s first licence, so there is no prior record to infer age from. The gate is still NOT enforced by the service â€” no config anywhere can express ''at least 18 years before today'' â€” so this is collected for the licence face and for the document_verifier''s own check at PENDING_DOCUMENT_VERIFICATION."}, "guardianName": {"type": "string", "title": "Name of Parent or Guardian", "$comment": "Name of the consenting parent or guardian. Printed on the learner''s licence for an under-18 holder.", "maxLength": 128}, "vehicleClass": {"type": "object", "title": "Class of Vehicle", "$comment": "group is the categoryTree''s own top-level path segment (''nontransport'' / ''transport'') â€” NOT the display name. licenceClass is the full dotted leaf path. MUST stay value-for-value identical to DRIVING_LICENSE''s, because a learner''s licence converts to a permanent licence of the same class and nothing in the platform links the two records. Nested, and therefore NOT searchable â€” an officer cannot search learner applications by class.", "required": ["group", "licenceClass"], "properties": {"group": {"enum": ["nontransport", "transport"], "type": "string", "title": "Vehicle Class Group"}, "licenceClass": {"type": "string", "title": "Vehicle Class"}}}, "applicationType": {"enum": ["FRESH", "ADDITIONAL_CLASS", "DUPLICATE"], "type": "string", "title": "Application Type", "$comment": "Drives BASE_FEE and TEST_FEE in calculation-rules.json. Both are RATE_MATRIX components, so every value in this enum MUST have a matching rule or RateMatrixEvaluator throws Rule.NoMatch â€” adding a value here without adding two rules there breaks fee calculation for that value only, at /estimate time. There is deliberately NO RENEWAL value: a learner''s licence lapses at 180 days and is replaced by a fresh application, never renewed, which is also why gracePeriodDays is 0 and no penalty component exists. Top-level and flat, so it is searchable (CertificateSpecification matches single top-level keys only)."}, "identificationMarks": {"type": "string", "title": "Identification Marks", "$comment": "Printed on the licence face; two marks is the statutory norm, entered as one free-text line. A string, NOT an array, and that is forced by the PDF: CertificatePdfService.flattenJson skips arrays and nested objects outright rather than half-rendering them, so an array here would be silently absent from every licence document.", "maxLength": 240}, "emergencyContactName": {"type": "string", "title": "Emergency Contact Name", "maxLength": 128}, "emergencyContactNumber": {"type": "string", "title": "Emergency Contact Number", "maxLength": 16}, "guardianConsentProvided": {"type": "boolean", "title": "A parent or guardian has consented to this application", "default": false, "$comment": "Set by a 16- or 17-year-old applicant for a gearless motorcycle, whose guardian''s signed consent is statutorily required. A boolean the applicant asserts, backed by the GUARDIAN_CONSENT_FORM document â€” the service validates neither the assertion nor the document against dateOfBirth, so the document_verifier reconciles the three by eye. Flat, so it is searchable, which is the point: an auditor reviewing minor applicants searches on this."}, "medicalCertificateNumber": {"type": "string", "title": "Medical Certificate Number (Form 1A)", "$comment": "Form 1A medical certificate reference. Statutorily required for every Transport class and for any applicant over 40; the document itself is uploaded against the MEDICAL_CERTIFICATE_FORM_1A category.", "maxLength": 64}, "existingLearnerLicenceNumber": {"type": "string", "title": "Existing Learner''s Licence Number", "$comment": "The learner''s licence being duplicated, or the one an additional class is being added to. Flat, so it is searchable â€” this is the field an officer looks an applicant up by. Empty for a FRESH application.", "maxLength": 32}}}', 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1790240655988, 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1790240655988);
INSERT INTO "BASETENANT".schema_definition (id, module_code, entity_code, tag, version, is_active, notes, schema_body, created_by, created_time, modified_by, modified_time) VALUES ('4a887c79-8a42-4d11-a0c9-f8b03f0f8c7e', 'certificate', 'LEARNER_LICENSE.form.b5a00577-ea80-491f-9666-b2f5e45f5d87', NULL, 2, false, NULL, '{"id": "b9f599f6-d37d-446f-b75a-7b360270f8c5", "type": "object", "allOf": [{"if": {"required": ["applicationType"], "properties": {"applicationType": {"const": "FRESH"}}}, "else": {"$comment": "ADDITIONAL_CLASS and DUPLICATE are both filed against a learner''s licence the applicant already holds, so the number is the field the officer looks the record up by and cannot be optional. Reached for every non-FRESH value, including any value added to the applicationType enum later — which is the point of expressing it as `else` rather than naming the two values.", "required": ["existingLearnerLicenceNumber"]}, "then": {"$comment": "A first-time licence is the only application that establishes the licence face, so the two statutory identification marks are collected here and nowhere else. ADDITIONAL_CLASS and DUPLICATE reprint what the existing record already holds.", "required": ["identificationMarks"]}, "$comment": "Conditional requiredness — the if/then/else form. The root `required` array can only ever be unconditional, so ''mandatory for this applicationType only'' has to live here, and ajv (Draft 2020-12) is what actually enforces it."}, {"if": {"required": ["guardianConsentProvided"], "properties": {"guardianConsentProvided": {"const": true}}}, "then": {"required": ["guardianName"]}, "$comment": "The dependent-field pair in its simplest form: a boolean gate and the field it unlocks. guardianConsentProvided is asserted by a 16- or 17-year-old applicant''s guardian, and a consent with no consenting party named is unusable on the licence face, so the name follows the assertion. Note what this still cannot express: the age gate itself. ''dateOfBirth is less than 18 years before today'' is not statable in JSON Schema, so consent stays a self-assertion the document_verifier reconciles against dateOfBirth and the GUARDIAN_CONSENT_FORM document by eye at PENDING_DOCUMENT_VERIFICATION."}], "$schema": "https://json-schema.org/draft/2020-12/schema", "$comment": "Learner''s Licence — the licence-specific section of the application ONLY. Applicant identity, addresses, uploaded documents and the declaration are hardcoded on the frontend and submitted to different services entirely (holder/partyDetails, the documents list, the declaration block on CertificateApplyRequest); none of that reaches certificateDetail, so nothing here duplicates them. Boundary (the applicant''s RTO jurisdiction) is driven by certificate_type.boundaryConfig and submitted as CertificateApplyRequest.boundaryDetail, a top-level field outside certificateDetail, so it is deliberately absent here too. Every field a jsonPath elsewhere in this bundle resolves against — calculation-rules/LEARNER_LICENSE.json and vc/LEARNER_LICENSE.json — is a property of this file.", "required": ["applicationType", "vehicleClass", "dateOfBirth", "bloodGroup"], "properties": {"bloodGroup": {"enum": ["A+", "A-", "B+", "B-", "AB+", "AB-", "O+", "O-"], "type": "string"}, "dateOfBirth": {"type": "string", "format": "date", "$comment": "Load-bearing for this type: the statutory minimum age (16 with guardian consent for a gearless motorcycle, 18 otherwise, 20 for Transport) is gated at the learner''s licence, and this is the applicant''s first licence, so there is no prior record to infer age from. The gate is still NOT enforced by the service — no config anywhere can express ''at least 18 years before today'' — so this is collected for the licence face and for the document_verifier''s own check at PENDING_DOCUMENT_VERIFICATION."}, "guardianName": {"type": "string", "$comment": "Name of the consenting parent or guardian. Printed on the learner''s licence for an under-18 holder.", "maxLength": 128}, "vehicleClass": {"type": "object", "$comment": "group is the categoryTree''s own top-level path segment (''nontransport'' / ''transport'') — NOT the display name. licenceClass is the full dotted leaf path. MUST stay value-for-value identical to a DRIVING_LICENSE certificate type''s own tree, because a learner''s licence converts to a permanent licence of the same class and nothing in the platform links the two records. Nested, and therefore NOT searchable — an officer cannot search learner applications by class.", "required": ["group", "licenceClass"], "properties": {"group": {"enum": ["nontransport", "transport"], "type": "string"}, "licenceClass": {"type": "string"}}}, "applicationType": {"enum": ["FRESH", "ADDITIONAL_CLASS", "DUPLICATE"], "type": "string", "$comment": "Drives BASE_FEE and TEST_FEE in the bootstrap version of calculation-rules/LEARNER_LICENSE.json (the reference version in master-bootstrap-data flattens both to unconditional fees, so this field is not consumed there). There is deliberately NO RENEWAL value: a learner''s licence lapses at 180 days and is replaced by a fresh application, never renewed, which is also why gracePeriodDays is 0 and no penalty component exists. Top-level and flat, so it is searchable (CertificateSpecification matches single top-level keys only)."}, "identificationMarks": {"type": "string", "$comment": "Printed on the licence face; two marks is the statutory norm, entered as one free-text line. A string, NOT an array, and that is forced by the PDF: CertificatePdfService.flattenJson skips arrays and nested objects outright rather than half-rendering them, so an array here would be silently absent from every licence document.", "maxLength": 240}, "emergencyContactName": {"type": "string", "maxLength": 128}, "emergencyContactNumber": {"type": "string", "maxLength": 16}, "guardianConsentProvided": {"type": "boolean", "default": false, "$comment": "Set by a 16- or 17-year-old applicant for a gearless motorcycle, whose guardian''s signed consent is statutorily required. A boolean the applicant asserts, backed by the GUARDIAN_CONSENT_FORM document — the service validates neither the assertion nor the document against dateOfBirth, so the document_verifier reconciles the three by eye. Flat, so it is searchable, which is the point: an auditor reviewing minor applicants searches on this."}, "medicalCertificateNumber": {"type": "string", "$comment": "Form 1A medical certificate reference. Statutorily required for every Transport class and for any applicant over 40; the document itself is uploaded against the MEDICAL_CERTIFICATE_FORM_1A category.", "maxLength": 64}, "existingLearnerLicenceNumber": {"type": "string", "$comment": "The learner''s licence being duplicated, or the one an additional class is being added to. Flat, so it is searchable — this is the field an officer looks an applicant up by. Empty for a FRESH application.", "maxLength": 32}}}', 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788269938523, 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788269938523);
INSERT INTO "BASETENANT".schema_definition (id, module_code, entity_code, tag, version, is_active, notes, schema_body, created_by, created_time, modified_by, modified_time) VALUES ('d33af063-1945-49ef-92b9-851d28e85df8', 'certificate', 'FOOD_LICENSE.form.3136481e-e525-47e3-862e-f12b9b8967c0', NULL, 1, false, NULL, '{"if": {"required": ["Application Type"], "properties": {"applicationType": {"const": "NEW"}}}, "else": {"required": ["Previous Licence Number"]}, "then": {"not": {"required": ["Previous Licence Number"]}}, "type": "object", "allOf": [{"if": {"required": ["Handles Product of Animal Origin"], "properties": {"handlesAnimalOrigin": {"const": true}}}, "then": {"properties": {"licenceClass": {"const": "APPROVAL"}}}, "$comment": "Product of animal origin forces the APPROVAL class. A genuine cross-field constraint between two independent applicant-declared fields — the thing the earlier draft of this bundle wrongly recorded as impossible."}, {"if": {"required": ["Authorisation Class"], "properties": {"licenceClass": {"const": "APPROVAL"}}}, "then": {"required": ["HACCP Plan Reference"]}, "$comment": "The APPROVAL class requires a HACCP plan reference."}, {"if": {"required": ["Annual Turnover"], "properties": {"annualTurnover": {"minimum": 5000001}}}, "then": {"properties": {"licenceClass": {"not": {"const": "REGISTRATION"}}}}, "$comment": "Turnover above the notify-only ceiling rules OUT the REGISTRATION class. Uses `not` rather than an enum of the remaining values so that adding a fourth licenceClass does not silently exclude it. Enforced in this direction only: a declared turnover BELOW the ceiling does not force REGISTRATION, because turnover at application time is routinely approximate or projected and a hard floor would bounce an applicant who rounded conservatively."}, {"if": {"required": ["Application Type"], "properties": {"applicationType": {"const": "RENEWAL"}}}, "then": {"required": ["Days Since Expiry"]}, "$comment": "A RENEWAL must state how overdue it is, so the penalty and interest rules have a value to band on. Zero is a valid answer and the expected one for a renewal filed in time."}, {"if": {"required": ["Activity Group"], "properties": {"activityGroup": {"const": "logistics"}}}, "then": {"required": ["Outlets"]}, "$comment": "Storage and transport operators declare their premises. The five blocks that follow enforce activityPath against activityGroup — JSON Schema cannot compare two properties directly, so consistency is expressed as one if/then per group value. (\\\\.|$) admits a group-only path, since the category tree''s second level is optional."}, {"if": {"required": ["Activity Group"], "properties": {"activityGroup": {"const": "manufacturing"}}}, "then": {"properties": {"activityPath": {"pattern": "^manufacturing(\\.|$)"}}}}, {"if": {"required": ["Activity Group"], "properties": {"activityGroup": {"const": "retail"}}}, "then": {"properties": {"activityPath": {"pattern": "^retail(\\.|$)"}}}}, {"if": {"required": ["Activity Group"], "properties": {"activityGroup": {"const": "foodservice"}}}, "then": {"properties": {"activityPath": {"pattern": "^foodservice(\\.|$)"}}}}, {"if": {"required": ["Activity Group"], "properties": {"activityGroup": {"const": "logistics"}}}, "then": {"properties": {"activityPath": {"pattern": "^logistics(\\.|$)"}}}}, {"if": {"required": ["Activity Group"], "properties": {"activityGroup": {"const": "trade"}}}, "then": {"properties": {"activityPath": {"pattern": "^trade(\\.|$)"}}}}], "$schema": "https://json-schema.org/draft/2020-12/schema", "$comment": "Food Licence — worldwide-generic, deliberately SMALL (13 properties) and deliberately BROAD in the JSON Schema features it exercises. This file is the capability reference for the catalogue: every construct below is enforced server-side by CertificateDetailValidator, which runs networknt on SpecVersion.V202012, so if/then/else, allOf, not, dependentRequired and dependentSchemas are all real validation and not documentation. Modelled on the common shape of food-business authorisation across regimes — FSSAI registration/licence tiers (India), Regulation 852/2004 registration-vs-approval (EU), FDA facility registration plus state retail permits (US), SFA licensing (Singapore) — which all reduce to: a class of authorisation, an activity type, a measure of scale, whether animal-origin product is handled, and a HACCP/FSMS plan. NOT MODELLED HERE: applicant identity, addresses, uploaded documents and the declaration, all of which ride the fixed envelope and never reach certificateDetail; and the jurisdiction, which is CertificateApplyRequest.boundaryDetail. Every jsonPath in calculator/calculation-rules.json and vc/vc-credential-type.json resolves against a property of this file.", "required": ["Application Type", "Authorisation Class", "Activity Group", "Activity", "Annual Turnover", "Premises Area (sq m)", "Handles Product of Animal Origin", "Licence Term (Years)", "Product Categories"], "properties": {"outlets": {"type": "array", "items": {"type": "object", "required": ["outletCode", "staffCount", "highRisk"], "properties": {"highRisk": {"type": "boolean"}, "openedOn": {"type": "string", "format": "date"}, "outletCode": {"type": "string", "pattern": "^[A-Z0-9-]{3,12}$"}, "staffCount": {"type": "integer", "maximum": 5000, "minimum": 1}}}, "$comment": "Premises operated under this licence. THE HIGHEST-VALUE FIELD IN THE BUNDLE: one property unlocks three calculator capabilities nothing else reaches — Scope.SUBENTITY (OUTLET_FEE prices each element separately), ruleType AGGREGATION (TOTAL_OUTLET_STAFF sums staffCount across elements), and AttributeCondition.derivedFrom (STAFF_LEVY bands on that derived total rather than on a payload field). DELIBERATELY OPTIONAL: JsonPathResolver.readArray returns List.of() on PathNotFound rather than throwing, so a single-premises applicant who omits it produces no OUTLET_FEE line items and a derived staff total of 0 — both paths are exercisable, which is the point of a test bundle. Inside a SUBENTITY rule, condition and appliesOn jsonPaths are RELATIVE to one element (''highRisk'', ''staffCount''), not rooted at $.certificateDetail.", "maxItems": 50, "minItems": 1}, "activityPath": {"type": "string", "pattern": "^(manufacturing|retail|foodservice|logistics|trade)(\\.[a-z0-9]+)?$", "$comment": "The full dotted path from categoryTree, e.g. ''manufacturing.dairy''. A flat string, so it prints on the licence and is prefix-searchable (''activityPath=manufacturing.*''). The pattern enforces the grammar; the allOf blocks below additionally enforce that it agrees with activityGroup, which pattern alone cannot express.", "maxLength": 64}, "haccpPlanRef": {"type": "string", "pattern": "^HACCP-[A-Z0-9]{4,12}$", "$comment": "Reference of the HACCP / food safety management plan. Conditionally required for the APPROVAL class (allOf below). Its mere PRESENCE earns HACCP_REBATE — the catalogue''s only presence-only condition, the third condition form AttributeCondition supports alongside equals and from/to, written as a condition object carrying a jsonPath and neither equals nor from.", "maxLength": 18, "minLength": 10}, "licenceClass": {"enum": ["REGISTRATION", "STANDARD", "APPROVAL"], "type": "string", "$comment": "The authorisation tier, worldwide-neutral. REGISTRATION is the notify-only tier (EU Art. 6(2) registration, FSSAI basic registration, FDA facility registration); STANDARD is an ordinary licence; APPROVAL is the establishment-approval tier that handling product of animal origin triggers (EU Art. 4(2)). Drives LICENCE_FEE as a RATE_MATRIX equals condition, so every value here needs a covering rule or RateMatrixEvaluator throws Rule.NoMatch."}, "activityGroup": {"enum": ["manufacturing", "retail", "foodservice", "logistics", "trade"], "type": "string", "$comment": "The categoryTree''s own top-level path segment — NOT the display name. THIS IS THE FIELD THAT LETS A FEE RULE CONDITION ON THE CATEGORY: ACTIVITY_FEE matches it with equals, and AttributeCondition has no prefix match, so the group cannot be read off activityPath''s dotted string by any rule. Carried separately for exactly that reason and no other; certificate search can prefix-match activityPath with a trailing ''*'', so search does not need it."}, "annualTurnover": {"type": "integer", "minimum": 0, "$comment": "Whole currency units, INTEGER not number. The integrality is load-bearing: AttributeConditionMatcher.inRange is inclusive at BOTH ends, so bands sharing a boundary tie at equal specificity and are resolved by a log warning and a deterministic pick rather than an error. Integer units let LICENCE_FEE''s bands be integer-adjacent with no epsilon. Also the subject of the turnover-versus-class cross-field rule below."}, "applicationType": {"enum": ["NEW", "RENEWAL", "VARIATION", "DUPLICATE"], "type": "string", "$comment": "Gates the conditional requirement of previousLicenceNumber via the top-level if/then/ELSE below — the one place in the catalogue that uses `else`, and it earns it: a NEW application must NOT cite a previous licence, every other type must. Flat, so it is searchable."}, "daysSinceExpiry": {"type": "integer", "maximum": 3650, "minimum": 0, "$comment": "Drives both LATE_RENEWAL_PENALTY (PENALTY, per-day) and LATE_PAYMENT_INTEREST (INTEREST, percentage) through from/to range conditions on the same field — two different rule types banding the same value. Frontend-computed, because the engine resolves jsonPaths against the payload and cannot do date arithmetic; this is the platform gap the spec''s HookConfig section is aimed at."}, "premisesAreaSqm": {"type": "number", "maximum": 100000, "$comment": "Drives PREMISES_INSPECTION_FEE, which is the catalogue''s one CORRECT use of calculationType SLAB: inspection effort genuinely scales with area at a decreasing marginal rate, so each tier''s rate applies only to the portion of the area inside it. That is what computeSlab does. It is the opposite of a banded flat fee, which is RATE_MATRIX + from/to — see LICENCE_FEE.", "exclusiveMinimum": 0}, "licenceTermYears": {"type": "integer", "maximum": 5, "minimum": 1, "$comment": "The term being bought. LICENCE_FEE is PER_UNIT with appliesOn.jsonPath pointing here, so the matched annual rate is multiplied by this. REQUIRED, and that is load-bearing: computePerUnit resolves this path AFTER the rule has matched and throws attributePathNotResolved if absent, which fails /estimate outright rather than degrading. NOTE THE DUPLICATION: the term that actually stamps validFrom/validUntil is CertificateApplyRequest.requestedValidityDays, an envelope field the calculator cannot see. See the bundle README''s gap 1."}, "productCategories": {"type": "array", "items": {"enum": ["DAIRY", "MEAT", "FISH", "PRODUCE", "BAKERY", "BEVERAGES", "PACKAGED", "OTHER"], "type": "string"}, "$comment": "The product scope endorsed on the licence. An ARRAY with uniqueItems and bounded length — exercising array-shaped validation, which nothing else in the catalogue does. It is deliberately NOT rendered on the PDF: flattenJson skips arrays outright, so any array is invisible to the document. Where a list MUST print, it has to be a flat string instead; DRIVING_LICENSE.identificationMarks is that trade-off, and this field is the counter-example where structure wins because the licence prints activityPath instead.", "maxItems": 8, "minItems": 1, "uniqueItems": true}, "handlesAnimalOrigin": {"type": "boolean", "$comment": "Whether product of animal origin is handled. A BOOLEAN condition target — ANIMAL_ORIGIN_SURCHARGE matches it with equals:true, which exercises AttributeConditionMatcher.valuesEqual''s String.valueOf comparison against a JSON boolean rather than a string enum. Also forces licenceClass to APPROVAL through the cross-field allOf block below, which is Regulation 852/2004 Article 4(2) expressed as config rather than as prose in eligibilityCriteria."}, "previousLicenceNumber": {"type": "string", "$comment": "Required for RENEWAL/VARIATION/DUPLICATE and forbidden for NEW — see the top-level if/then/else. dependentRequired below additionally ties daysSinceExpiry to it, so a late-renewal penalty can never be charged against an application that names no prior licence.", "maxLength": 32}}, "dependentSchemas": {"outlets": {"properties": {"licenceClass": {"not": {"const": "REGISTRATION"}}}}}, "dependentRequired": {"daysSinceExpiry": ["Previous Licence Number"]}, "$comment_conditionals": "Everything below is ENFORCED, not advisory. CertificateDetailValidator runs networknt V202012 and CertificateSchemaService.validateChecklist calls the same validator, so the same vocabulary is available to checklists."}', 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788277744038, 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788277744038);
INSERT INTO "BASETENANT".schema_definition (id, module_code, entity_code, tag, version, is_active, notes, schema_body, created_by, created_time, modified_by, modified_time) VALUES ('faad78fc-4006-49e3-9fca-bb295b340b13', 'certificate', 'FOOD_LICENSE.checklist.e504a163-a165-4ab6-a479-60a5913be4cc', 'PENDING_INSPECTION.COMPLETE_INSPECTION', 1, false, NULL, '{"if": {"required": ["Risk Rating"], "properties": {"riskRating": {"const": "HIGH"}}}, "then": {"required": ["Corrective Action Due By", "Inspector''s Notes"]}, "type": "object", "title": "Food Safety Inspection Report", "$schema": "https://json-schema.org/draft/2020-12/schema", "$comment": "The food safety inspection report, submitted by the inspector alongside the PENDING_INSPECTION.COMPLETE_INSPECTION transition — the single tag CertificateSchemaService.CHECKLIST_TAG is hardcoded to. Eight fields, and each one is a DIFFERENT data type on purpose: this is the catalogue''s reference for what a checklist can carry. boolean, date, free text, integer, single-choice enum, multi-choice enum array, file array, and one conditionally-required date. CertificateSchemaService.validateChecklist calls the SAME CertificateDetailValidator the application form goes through, so everything here is enforced server-side — including the if/then block at the bottom, which nothing else in the catalogue demonstrates on a checklist.", "required": ["Inspection Passed", "Date of Inspection", "Hygiene Score (0-100)", "Risk Rating", "Evidence Photographs"], "properties": {"riskRating": {"enum": ["LOW", "MEDIUM", "HIGH"], "type": "string", "title": "Risk Rating", "$comment": "SINGLE-CHOICE ENUM — renders as radio buttons. Drives the conditional requirement at the bottom of this file."}, "hygieneScore": {"type": "integer", "title": "Hygiene Score (0-100)", "maximum": 100, "minimum": 0, "$comment": "INTEGER with bounds — renders as a number input. Scored out of 100 and constrained to multiples of 5, which exercises multipleOf.", "multipleOf": 5}, "evidencePhotos": {"type": "array", "items": {"type": "string", "format": "uri"}, "title": "Evidence Photographs", "$comment": "FILE ARRAY — items are format: uri, renders as a multi-file upload. At least one is required, so an inspection cannot be closed on assertion alone.", "minItems": 1}, "inspectionDate": {"type": "string", "title": "Date of Inspection", "format": "date", "$comment": "DATE — format: date, renders as a date picker. The officer''s own date of attendance, which can differ from the transition timestamp."}, "inspectorNotes": {"type": "string", "title": "Inspector''s Notes", "$comment": "FREE TEXT — renders as a textarea. Bounded so a pasted report cannot bloat the JSONB row.", "maxLength": 2000}, "nonConformities": {"type": "array", "items": {"enum": ["HYGIENE", "PEST_CONTROL", "TEMPERATURE_CONTROL", "LABELLING", "WATER_QUALITY", "STAFF_TRAINING", "RECORD_KEEPING"], "type": "string"}, "title": "Non-Conformities Found", "$comment": "MULTI-CHOICE ENUM ARRAY with uniqueItems — renders as a multiselect. An array, so it can never appear on a rendered document; that is fine, a checklist is not printed.", "maxItems": 7, "uniqueItems": true}, "inspectionPassed": {"type": "boolean", "title": "Inspection Passed", "$comment": "BOOLEAN — renders as a checkbox."}, "correctiveActionDueBy": {"type": "string", "title": "Corrective Action Due By", "format": "date", "$comment": "CONDITIONALLY-REQUIRED DATE — required only when riskRating is HIGH, via the if/then below. Proof that the same conditional vocabulary the application form uses is available on a checklist, because both go through CertificateDetailValidator."}}}', 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788277744451, 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788277744633);
INSERT INTO "BASETENANT".schema_definition (id, module_code, entity_code, tag, version, is_active, notes, schema_body, created_by, created_time, modified_by, modified_time) VALUES ('e6c1d451-2ceb-49c6-8e7d-97bfc887a54c', 'certificate', 'DRIVING_LICENSE.checklist.fef7a534-4fd7-49de-b882-615a34612a44', 'PENDING_INSPECTION.COMPLETE_INSPECTION', 1, false, NULL, '{"type": "object", "title": "Driving Test Result", "$schema": "https://json-schema.org/draft/2020-12/schema", "$comment": "The PRACTICAL driving-test result form, submitted by the examiner alongside the PENDING_INSPECTION.COMPLETE_INSPECTION transition. ''Inspection'' is the platform''s word, not the domain''s — CertificateSchemaService.CHECKLIST_TAG is hardcoded to that exact state.action pair, so this checklist binds to the driving test only because the workflow state is named PENDING_INSPECTION. The label renders as ''Driving Test'' (see workflow.labels.json); the codes cannot change. THE THEORY TEST IS NOT HERE: exactly one checklist binds per certificate type (one type, one hardcoded tag), so the learner''s theory test lives in the LEARNER_LICENSE bundle''s own checklist. That constraint is why the two are separate certificate types at all — practicalTestResult is required below, and a learner applicant could never satisfy it.", "required": ["Test was conducted", "Identity verified at the test centre", "Eyesight Test Result", "Practical Test Result", "Test Photographs"], "properties": {"testPhotos": {"type": "array", "items": {"type": "string", "format": "uri"}, "title": "Test Photographs", "minItems": 1}, "testConducted": {"type": "boolean", "title": "Test was conducted"}, "testTrackCode": {"type": "string", "title": "Test Track Code"}, "examinerRemarks": {"type": "string", "title": "Examiner''s Remarks"}, "eyesightTestResult": {"enum": ["PASS", "FAIL", "PASS_WITH_CORRECTIVE_LENSES"], "type": "string", "title": "Eyesight Test Result"}, "vehicleUsedForTest": {"type": "string", "title": "Vehicle Used for the Test"}, "practicalTestResult": {"enum": ["PASS", "FAIL", "ABSENT"], "type": "string", "title": "Practical Test Result"}, "identityVerifiedAtCentre": {"enum": ["YES", "NO"], "type": "string", "title": "Identity verified at the test centre"}}}', 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788277727037, 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788277727133);
INSERT INTO "BASETENANT".schema_definition (id, module_code, entity_code, tag, version, is_active, notes, schema_body, created_by, created_time, modified_by, modified_time) VALUES ('ee628e3c-05fc-431d-9c78-c2087c4765a8', 'certificate', 'LEARNER_LICENSE.form.b5a00577-ea80-491f-9666-b2f5e45f5d87', NULL, 3, false, NULL, '{"type": "object", "allOf": [{"if": {"required": ["applicationType"], "properties": {"applicationType": {"const": "FRESH"}}}, "else": {"$comment": "ADDITIONAL_CLASS and DUPLICATE are both filed against a learner''s licence the applicant already holds, so the number is the field the officer looks the record up by and cannot be optional. Reached for every non-FRESH value, including any value added to the applicationType enum later — which is the point of expressing it as `else` rather than naming the two values.", "required": ["existingLearnerLicenceNumber"]}, "then": {"$comment": "A first-time licence is the only application that establishes the licence face, so the two statutory identification marks are collected here and nowhere else. ADDITIONAL_CLASS and DUPLICATE reprint what the existing record already holds.", "required": ["identificationMarks"]}, "$comment": "Conditional requiredness — the if/then/else form. The root `required` array can only ever be unconditional, so ''mandatory for this applicationType only'' has to live here, and ajv (Draft 2020-12, the formAjv singleton in renderers/shared.ts) is what actually enforces it. Three constraints on how these blocks are written, none of them JSON Schema rules — all of them frontend behaviour: (1) the `if` matches on `const`, never `enum`. isFieldCurrentlyRequired (packages/shared/src/utils/jsonforms-rule.ts) only reads `const` out of if.properties and treats an `enum` there as trivially satisfied, so an enum-keyed `if` paints the required asterisk on its `then` fields permanently, from the first render, even though ajv keeps validating correctly. (2) the `if` carries its own `required` naming the field it tests, so the branch cannot fire before the applicant has answered: `properties` alone passes vacuously for absent data, which would apply `then` immediately. (3) a field made required here MUST be visible in exactly the cases it is required. useApplyWizard''s sub-screen Next gating collects every Control in the sub-screen via collectControls WITHOUT filtering on rule visibility, so a required error on a rule-hidden control blocks Next with nothing on screen to fix. identificationMarks is unconditionally visible; existingLearnerLicenceNumber is hidden for exactly FRESH by its uischema rule, which is the precise complement of this `else`. One asymmetry to know when reading the form: isFieldCurrentlyRequired evaluates allOf[].then only and ignores `else` outright, so the `else` branch is enforced by ajv but never draws an asterisk — it surfaces as an inline error once showErrors flips. Splitting it into two `if`/`then` blocks (one per non-FRESH value) would buy the asterisk at the cost of two rules to keep in step; kept as one `else` deliberately."}, {"if": {"required": ["guardianConsentProvided"], "properties": {"guardianConsentProvided": {"const": true}}}, "then": {"required": ["guardianName"]}, "$comment": "The dependent-field pair in its simplest form: a boolean gate and the field it unlocks. guardianConsentProvided is asserted by a 16- or 17-year-old applicant''s guardian, and a consent with no consenting party named is unusable on the licence face, so the name follows the assertion. Visibility and requiredness are driven from the same `const: true` — the uischema SHOW rule on guardianName and this `if` — which is what keeps the field on screen at exactly the moment it becomes mandatory. Note what this still cannot express: the age gate itself. ''dateOfBirth is less than 18 years before today'' is not statable in JSON Schema (nor in a jsonforms rule condition), so consent stays a self-assertion the document_verifier reconciles against dateOfBirth and the GUARDIAN_CONSENT_FORM document by eye at PENDING_DOCUMENT_VERIFICATION."}], "$schema": "https://json-schema.org/draft/2020-12/schema", "$comment": "Learner''s Licence — the licence-specific section of the application ONLY. Applicant identity, addresses, uploaded documents and the declaration are hardcoded on the frontend and submitted to different services entirely (holder/partyDetails, the documents list, the declaration block on CertificateApplyRequest); none of that reaches certificateDetail, so nothing here duplicates them. Boundary (the applicant''s RTO jurisdiction) is driven by certificate_type.boundaryConfig and submitted as CertificateApplyRequest.boundaryDetail, a top-level field outside certificateDetail, so it is deliberately absent here too. Every field a jsonPath elsewhere in this bundle resolves against — calculator/calculation-rules.json and vc/vc-credential-type.json — is a property of this file.", "required": ["applicationType", "vehicleClass", "dateOfBirth", "bloodGroup"], "properties": {"bloodGroup": {"enum": ["A+", "A-", "B+", "B-", "AB+", "AB-", "O+", "O-"], "type": "string"}, "dateOfBirth": {"type": "string", "format": "date", "$comment": "Load-bearing for this type in a way it is not for DRIVING_LICENSE: the statutory minimum age (16 with guardian consent for a gearless motorcycle, 18 otherwise, 20 for Transport) is gated at the learner''s licence, and this is the applicant''s first licence, so there is no prior record to infer age from. The gate is still NOT enforced by the service — no config anywhere can express ''at least 18 years before today'' — so this is collected for the licence face and for the document_verifier''s own check at PENDING_DOCUMENT_VERIFICATION."}, "guardianName": {"type": "string", "$comment": "Name of the consenting parent or guardian. Printed on the learner''s licence for an under-18 holder.", "maxLength": 128}, "vehicleClass": {"type": "object", "$comment": "group is the categoryTree''s own top-level path segment (''nontransport'' / ''transport'') — NOT the display name. licenceClass is the full dotted leaf path. MUST stay value-for-value identical to DRIVING_LICENSE''s, because a learner''s licence converts to a permanent licence of the same class and nothing in the platform links the two records. Nested, and therefore NOT searchable — an officer cannot search learner applications by class.", "required": ["group", "licenceClass"], "properties": {"group": {"enum": ["nontransport", "transport"], "type": "string"}, "licenceClass": {"type": "string"}}}, "applicationType": {"enum": ["FRESH", "ADDITIONAL_CLASS", "DUPLICATE"], "type": "string", "$comment": "Drives BASE_FEE and TEST_FEE in calculation-rules.json. Both are RATE_MATRIX components, so every value in this enum MUST have a matching rule or RateMatrixEvaluator throws Rule.NoMatch — adding a value here without adding two rules there breaks fee calculation for that value only, at /estimate time. There is deliberately NO RENEWAL value: a learner''s licence lapses at 180 days and is replaced by a fresh application, never renewed, which is also why gracePeriodDays is 0 and no penalty component exists. Top-level and flat, so it is searchable (CertificateSpecification matches single top-level keys only)."}, "identificationMarks": {"type": "string", "$comment": "Printed on the licence face; two marks is the statutory norm, entered as one free-text line. A string, NOT an array, and that is forced by the PDF: CertificatePdfService.flattenJson skips arrays and nested objects outright rather than half-rendering them, so an array here would be silently absent from every licence document.", "maxLength": 240}, "emergencyContactName": {"type": "string", "maxLength": 128}, "emergencyContactNumber": {"type": "string", "maxLength": 16}, "guardianConsentProvided": {"type": "boolean", "default": false, "$comment": "Set by a 16- or 17-year-old applicant for a gearless motorcycle, whose guardian''s signed consent is statutorily required. A boolean the applicant asserts, backed by the GUARDIAN_CONSENT_FORM document — the service validates neither the assertion nor the document against dateOfBirth, so the document_verifier reconciles the three by eye. Flat, so it is searchable, which is the point: an auditor reviewing minor applicants searches on this."}, "medicalCertificateNumber": {"type": "string", "$comment": "Form 1A medical certificate reference. Statutorily required for every Transport class and for any applicant over 40; the document itself is uploaded against the MEDICAL_CERTIFICATE_FORM_1A category.", "maxLength": 64}, "existingLearnerLicenceNumber": {"type": "string", "$comment": "The learner''s licence being duplicated, or the one an additional class is being added to. Flat, so it is searchable — this is the field an officer looks an applicant up by. Empty for a FRESH application.", "maxLength": 32}}}', 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788283088887, 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788283088887);
INSERT INTO "BASETENANT".schema_definition (id, module_code, entity_code, tag, version, is_active, notes, schema_body, created_by, created_time, modified_by, modified_time) VALUES ('39906e1b-afb7-4aa4-9d24-c1cb88215e2c', 'certificate', 'DRIVING_LICENSE.form.1594690b-b1cf-4677-b0a3-de4e8a4c5925', NULL, 1, false, NULL, '{"type": "object", "$schema": "https://json-schema.org/draft/2020-12/schema", "$comment": "Driving License — the licence-specific section of the application ONLY. Applicant identity, addresses, uploaded documents and the declaration are hardcoded on the frontend and submitted to different services entirely (holder/partyDetails, the documents list, the declaration block on CertificateApplyRequest); none of that reaches certificateDetail, so nothing here duplicates them. Boundary (the applicant''s RTO jurisdiction) is driven by certificate_type.boundaryConfig and submitted as CertificateApplyRequest.boundaryDetail, a top-level field outside certificateDetail, so it is deliberately absent here too. Every field a jsonPath elsewhere in this bundle resolves against — calculator/calculation-rules.json and vc/vc-credential-type.json — is a property of this file.", "required": ["applicationType", "vehicleClass", "dateOfBirth", "bloodGroup"], "properties": {"bloodGroup": {"enum": ["A+", "A-", "B+", "B-", "AB+", "AB-", "O+", "O-"], "type": "string"}, "dateOfBirth": {"type": "string", "format": "date", "$comment": "The age gates in eligibilityCriteria are advisory and never enforced by the service, so this is collected for the licence face and for the issuing officer''s own check, not for validation here."}, "vehicleClass": {"type": "object", "$comment": "group is the categoryTree''s own top-level path segment (''nontransport'' / ''transport'') — NOT the display name; CLASS_SURCHARGE in calculation-rules.json matches on it with equals. licenceClass is the full dotted leaf path. Nested, and therefore NOT searchable — the same shape and the same limitation as FIRE_NOC''s usageType.", "required": ["group", "licenceClass"], "properties": {"group": {"enum": ["nontransport", "transport"], "type": "string"}, "licenceClass": {"type": "string"}}}, "applicationType": {"enum": ["PERMANENT", "RENEWAL", "DUPLICATE", "INTERNATIONAL"], "type": "string", "$comment": "Drives BASE_FEE and TEST_FEE in calculation-rules.json. Both are RATE_MATRIX components, so every value in this enum MUST have a matching rule or RateMatrixEvaluator throws Rule.NoMatch — adding a value here without adding two rules there breaks fee calculation for that value only, at /estimate time. Top-level and flat, so it is searchable (CertificateSpecification matches single top-level keys only). LEARNER is deliberately NOT a value here: a learner''s licence is the separate LEARNER_LICENSE certificate type, because the two need different checklists and one type can hold only one (CertificateSchemaService binds exactly one checklist per type, under the single hardcoded PENDING_INSPECTION.COMPLETE_INSPECTION tag)."}, "daysSinceExpiry": {"type": "integer", "minimum": 0, "$comment": "Drives LATE_RENEWAL_PENALTY in calculation-rules.json via a from/to range condition. Submitted by the frontend as a computed value rather than derived here, because the calculator''s condition grammar resolves jsonPaths against the payload only — it cannot compute a date difference (AttributeCondition supports equals XOR from/to XOR presence, nothing more). 0 for anything that is not an overdue renewal."}, "drivingSchoolName": {"type": "string", "maxLength": 128}, "organDonorConsent": {"type": "boolean", "default": false}, "identificationMarks": {"type": "string", "$comment": "Printed on the licence face; two marks is the statutory norm, entered as one free-text line. A string, NOT an array, and that is forced by the PDF: CertificatePdfService.flattenJson skips arrays and nested objects outright rather than half-rendering them, so an array here would be silently absent from every licence card. The data model bends to the renderer because the alternative is a blank field on a statutory document.", "maxLength": 240}, "emergencyContactName": {"type": "string", "maxLength": 128}, "learnerLicenceNumber": {"type": "string", "$comment": "Required in practice for applicationType PERMANENT, but not expressible as a conditional requirement here: this schema is validated as-is by CertificateDetailValidator, and a JSON Schema if/then block would be enforced by the validator but ignored by the jsonforms UI, which reads ui_schema''s own rule blocks instead. The conditional visibility lives in DRIVING_LICENSE_ui_schema.json; the officer''s own check at PENDING_DOCUMENT_VERIFICATION is the real gate. Flat, so it is searchable.", "maxLength": 32}, "existingLicenceNumber": {"type": "string", "$comment": "The licence being renewed, duplicated or converted. Flat, so it is searchable — this is the field an officer looks an applicant up by.", "maxLength": 32}, "emergencyContactNumber": {"type": "string", "maxLength": 16}, "medicalCertificateNumber": {"type": "string", "$comment": "Form 1A medical certificate reference. Statutorily required for every Transport class and for any applicant over 40; the document itself is uploaded against the MEDICAL_CERTIFICATE_FORM_1A category (see filestore/document-categories.json).", "maxLength": 64}, "hasPreviousLicenceSuspension": {"type": "boolean", "default": false}}}', 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788277726740, 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788277726740);
INSERT INTO "BASETENANT".schema_definition (id, module_code, entity_code, tag, version, is_active, notes, schema_body, created_by, created_time, modified_by, modified_time) VALUES ('666070e9-5038-4106-aacf-180fd7e9a21f', 'certificate', 'LEARNER_LICENSE.checklist.59ddb7cd-c745-4a97-90c5-247da42e2ea4', 'PENDING_INSPECTION.COMPLETE_INSPECTION', 1, false, NULL, '{"type": "object", "title": "Theory Test Result", "$schema": "https://json-schema.org/draft/2020-12/schema", "$comment": "The THEORY-test result form, submitted by the examiner alongside the PENDING_INSPECTION.COMPLETE_INSPECTION transition. ''Inspection'' is the platform''s word, not the domain''s — CertificateSchemaService.CHECKLIST_TAG is hardcoded to that exact state.action pair, so this checklist binds to the theory test only because the workflow state is named PENDING_INSPECTION. THIS FILE IS THE REASON LEARNER_LICENSE EXISTS as a separate certificate type from a permanent driving licence: exactly one checklist binds per type, under that one hardcoded tag, and a theory test and a practical driving test cannot be the same form.", "required": ["testConducted", "identityVerifiedAtCentre", "eyesightTestResult", "theoryTestScore", "theoryTestResult"], "properties": {"testMode": {"enum": ["ONLINE_TERMINAL", "WRITTEN", "ORAL"], "type": "string", "title": "Test Mode"}, "testConducted": {"type": "boolean", "title": "Test was conducted"}, "testCentreCode": {"type": "string", "title": "Test Centre Code"}, "examinerRemarks": {"type": "string", "title": "Examiner''s Remarks"}, "theoryTestScore": {"type": "integer", "title": "Theory Test Score (out of 15)", "maximum": 15, "minimum": 0, "$comment": "Out of 15, the standard number of questions in the RTO learner''s theory test. A theory score is the entire substance of this examination."}, "theoryTestResult": {"enum": ["PASS", "FAIL", "ABSENT"], "type": "string", "title": "Theory Test Result", "$comment": "The examiner''s verdict, kept separate from theoryTestScore rather than derived from it — the pass mark is an RTO policy that varies, and nothing in the schema grammar can express ''PASS when score >= 9''."}, "eyesightTestResult": {"enum": ["PASS", "FAIL", "PASS_WITH_CORRECTIVE_LENSES"], "type": "string", "title": "Eyesight Test Result", "$comment": "The eyesight test is statutorily part of the learner''s licence examination, not the permanent one — this is where a corrective-lenses endorsement originates."}, "identityVerifiedAtCentre": {"enum": ["YES", "NO"], "type": "string", "title": "Identity verified at the test centre"}}}', 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788241051018, 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788241051119);
INSERT INTO "BASETENANT".schema_definition (id, module_code, entity_code, tag, version, is_active, notes, schema_body, created_by, created_time, modified_by, modified_time) VALUES ('c7027863-2bf7-4a5b-9d71-ce240353d364', 'certificate', 'LEARNER_LICENSE_V2.form.61e6d73a-eb58-4265-9dae-457ea9bdeffa', NULL, 1, true, NULL, '{"type": "object", "allOf": [{"if": {"required": ["applicationType"], "properties": {"applicationType": {"const": "FRESH"}}}, "else": {"$comment": "ADDITIONAL_CLASS and DUPLICATE are both filed against a learner''s licence the applicant already holds, so the number is the field the officer looks the record up by and cannot be optional. Reached for every non-FRESH value, including any value added to the applicationType enum later — which is the point of expressing it as `else` rather than naming the two values.", "required": ["existingLearnerLicenceNumber"]}, "then": {"$comment": "A first-time licence is the only application that establishes the licence face, so the two statutory identification marks are collected here and nowhere else. ADDITIONAL_CLASS and DUPLICATE reprint what the existing record already holds.", "required": ["identificationMarks"]}, "$comment": "Conditional requiredness — the if/then/else form. The root `required` array can only ever be unconditional, so ''mandatory for this applicationType only'' has to live here, and ajv (Draft 2020-12, the formAjv singleton in renderers/shared.ts) is what actually enforces it. Three constraints on how these blocks are written, none of them JSON Schema rules — all of them frontend behaviour: (1) the `if` matches on `const`, never `enum`. isFieldCurrentlyRequired (packages/shared/src/utils/jsonforms-rule.ts) only reads `const` out of if.properties and treats an `enum` there as trivially satisfied, so an enum-keyed `if` paints the required asterisk on its `then` fields permanently, from the first render, even though ajv keeps validating correctly. (2) the `if` carries its own `required` naming the field it tests, so the branch cannot fire before the applicant has answered: `properties` alone passes vacuously for absent data, which would apply `then` immediately. (3) a field made required here MUST be visible in exactly the cases it is required. useApplyWizard''s sub-screen Next gating collects every Control in the sub-screen via collectControls WITHOUT filtering on rule visibility, so a required error on a rule-hidden control blocks Next with nothing on screen to fix. identificationMarks is unconditionally visible; existingLearnerLicenceNumber is hidden for exactly FRESH by its uischema rule, which is the precise complement of this `else`. One asymmetry to know when reading the form: isFieldCurrentlyRequired evaluates allOf[].then only and ignores `else` outright, so the `else` branch is enforced by ajv but never draws an asterisk — it surfaces as an inline error once showErrors flips. Splitting it into two `if`/`then` blocks (one per non-FRESH value) would buy the asterisk at the cost of two rules to keep in step; kept as one `else` deliberately."}, {"if": {"required": ["guardianConsentProvided"], "properties": {"guardianConsentProvided": {"const": true}}}, "then": {"required": ["guardianName"]}, "$comment": "The dependent-field pair in its simplest form: a boolean gate and the field it unlocks. guardianConsentProvided is asserted by a 16- or 17-year-old applicant''s guardian, and a consent with no consenting party named is unusable on the licence face, so the name follows the assertion. Visibility and requiredness are driven from the same `const: true` — the uischema SHOW rule on guardianName and this `if` — which is what keeps the field on screen at exactly the moment it becomes mandatory. Note what this still cannot express: the age gate itself. ''dateOfBirth is less than 18 years before today'' is not statable in JSON Schema (nor in a jsonforms rule condition), so consent stays a self-assertion the document_verifier reconciles against dateOfBirth and the GUARDIAN_CONSENT_FORM document by eye at PENDING_DOCUMENT_VERIFICATION."}], "$schema": "https://json-schema.org/draft/2020-12/schema", "$comment": "Learner''s Licence — the licence-specific section of the application ONLY. Applicant identity, addresses, uploaded documents and the declaration are hardcoded on the frontend and submitted to different services entirely (holder/partyDetails, the documents list, the declaration block on CertificateApplyRequest); none of that reaches certificateDetail, so nothing here duplicates them. Boundary (the applicant''s RTO jurisdiction) is driven by certificate_type.boundaryConfig and submitted as CertificateApplyRequest.boundaryDetail, a top-level field outside certificateDetail, so it is deliberately absent here too. Every field a jsonPath elsewhere in this bundle resolves against — calculator/calculation-rules.json and vc/vc-credential-type.json — is a property of this file.", "required": ["applicationType", "vehicleClass", "dateOfBirth", "bloodGroup"], "properties": {"bloodGroup": {"enum": ["A+", "A-", "B+", "B-", "AB+", "AB-", "O+", "O-"], "type": "string", "title": "Blood Group"}, "dateOfBirth": {"type": "string", "title": "Date of Birth", "format": "date", "$comment": "Load-bearing for this type in a way it is not for DRIVING_LICENSE: the statutory minimum age (16 with guardian consent for a gearless motorcycle, 18 otherwise, 20 for Transport) is gated at the learner''s licence, and this is the applicant''s first licence, so there is no prior record to infer age from. The gate is still NOT enforced by the service — no config anywhere can express ''at least 18 years before today'' — so this is collected for the licence face and for the document_verifier''s own check at PENDING_DOCUMENT_VERIFICATION."}, "guardianName": {"type": "string", "title": "Name of Parent or Guardian", "$comment": "Name of the consenting parent or guardian. Printed on the learner''s licence for an under-18 holder.", "maxLength": 128}, "vehicleClass": {"type": "object", "title": "Class of Vehicle", "$comment": "group is the categoryTree''s own top-level path segment (''nontransport'' / ''transport'') — NOT the display name. licenceClass is the full dotted leaf path. MUST stay value-for-value identical to DRIVING_LICENSE''s, because a learner''s licence converts to a permanent licence of the same class and nothing in the platform links the two records. Nested, and therefore NOT searchable — an officer cannot search learner applications by class.", "required": ["group", "licenceClass"], "properties": {"group": {"enum": ["nontransport", "transport"], "type": "string", "title": "Vehicle Class Group"}, "licenceClass": {"type": "string", "title": "Vehicle Class"}}}, "applicationType": {"enum": ["FRESH", "ADDITIONAL_CLASS", "DUPLICATE"], "type": "string", "title": "Application Type", "$comment": "Drives BASE_FEE and TEST_FEE in calculation-rules.json. Both are RATE_MATRIX components, so every value in this enum MUST have a matching rule or RateMatrixEvaluator throws Rule.NoMatch — adding a value here without adding two rules there breaks fee calculation for that value only, at /estimate time. There is deliberately NO RENEWAL value: a learner''s licence lapses at 180 days and is replaced by a fresh application, never renewed, which is also why gracePeriodDays is 0 and no penalty component exists. Top-level and flat, so it is searchable (CertificateSpecification matches single top-level keys only)."}, "identificationMarks": {"type": "string", "title": "Identification Marks", "$comment": "Printed on the licence face; two marks is the statutory norm, entered as one free-text line. A string, NOT an array, and that is forced by the PDF: CertificatePdfService.flattenJson skips arrays and nested objects outright rather than half-rendering them, so an array here would be silently absent from every licence document.", "maxLength": 240}, "emergencyContactName": {"type": "string", "title": "Emergency Contact Name", "maxLength": 128}, "emergencyContactNumber": {"type": "string", "title": "Emergency Contact Number", "maxLength": 16}, "guardianConsentProvided": {"type": "boolean", "title": "A parent or guardian has consented to this application", "default": false, "$comment": "Set by a 16- or 17-year-old applicant for a gearless motorcycle, whose guardian''s signed consent is statutorily required. A boolean the applicant asserts, backed by the GUARDIAN_CONSENT_FORM document — the service validates neither the assertion nor the document against dateOfBirth, so the document_verifier reconciles the three by eye. Flat, so it is searchable, which is the point: an auditor reviewing minor applicants searches on this."}, "medicalCertificateNumber": {"type": "string", "title": "Medical Certificate Number (Form 1A)", "$comment": "Form 1A medical certificate reference. Statutorily required for every Transport class and for any applicant over 40; the document itself is uploaded against the MEDICAL_CERTIFICATE_FORM_1A category.", "maxLength": 64}, "existingLearnerLicenceNumber": {"type": "string", "title": "Existing Learner''s Licence Number", "$comment": "The learner''s licence being duplicated, or the one an additional class is being added to. Flat, so it is searchable — this is the field an officer looks an applicant up by. Empty for a FRESH application.", "maxLength": 32}}}', 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788298570635, 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788298570635);
INSERT INTO "BASETENANT".schema_definition (id, module_code, entity_code, tag, version, is_active, notes, schema_body, created_by, created_time, modified_by, modified_time) VALUES ('ea95b3cd-5f6a-4189-8329-d77269117f61', 'certificate', 'LEARNER_LICENSE.checklist.59ddb7cd-c745-4a97-90c5-247da42e2ea4', 'PENDING_INSPECTION.COMPLETE_INSPECTION', 2, false, NULL, '{"type": "object", "title": "checklist.title", "$schema": "https://json-schema.org/draft/2020-12/schema", "$comment": "The THEORY-test result form, submitted by the examiner alongside the PENDING_INSPECTION.COMPLETE_INSPECTION transition. ''Inspection'' is the platform''s word, not the domain''s — CertificateSchemaService.CHECKLIST_TAG is hardcoded to that exact state.action pair, so this checklist binds to the theory test only because the workflow state is named PENDING_INSPECTION. The label renders as ''Theory Test'' (see workflow.labels.json); the codes cannot change. THIS FILE IS THE REASON LEARNER_LICENSE EXISTS as a separate certificate type: exactly one checklist binds per type, under that one hardcoded tag, and a theory test and a practical driving test cannot be the same form. DRIVING_LICENSE''s checklist requires practicalTestResult, which a learner applicant could never supply.", "required": ["testConducted", "identityVerifiedAtCentre", "eyesightTestResult", "theoryTestScore", "theoryTestResult"], "properties": {"testMode": {"enum": ["ONLINE_TERMINAL", "WRITTEN", "ORAL"], "type": "string", "title": "testMode"}, "testConducted": {"type": "boolean", "title": "testConducted"}, "testCentreCode": {"type": "string", "title": "testCentreCode"}, "examinerRemarks": {"type": "string", "title": "examinerRemarks"}, "theoryTestScore": {"type": "integer", "title": "theoryTestScore", "maximum": 15, "minimum": 0, "$comment": "Out of 15, the standard number of questions in the RTO learner''s theory test. Required here, where DRIVING_LICENSE''s checklist does not carry it at all: a theory score is the entire substance of this examination."}, "theoryTestResult": {"enum": ["PASS", "FAIL", "ABSENT"], "type": "string", "title": "theoryTestResult", "$comment": "The examiner''s verdict, kept separate from theoryTestScore rather than derived from it — the pass mark is an RTO policy that varies, and nothing in the schema grammar can express ''PASS when score >= 9''."}, "eyesightTestResult": {"enum": ["PASS", "FAIL", "PASS_WITH_CORRECTIVE_LENSES"], "type": "string", "title": "eyesightTestResult", "$comment": "The eyesight test is statutorily part of the learner''s licence examination, not the permanent one — this is where a corrective-lenses endorsement originates."}, "identityVerifiedAtCentre": {"enum": ["YES", "NO"], "type": "string", "title": "identityVerifiedAtCentre"}}}', 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788283090575, 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788283090575);
INSERT INTO "BASETENANT".schema_definition (id, module_code, entity_code, tag, version, is_active, notes, schema_body, created_by, created_time, modified_by, modified_time) VALUES ('a29894da-105a-4a6f-99f5-e16d619ede9f', 'certificate', 'FOOD_LICENSE.form.3136481e-e525-47e3-862e-f12b9b8967c0', NULL, 2, false, NULL, '{"if": {"required": ["applicationType"], "properties": {"applicationType": {"const": "NEW"}}}, "else": {"required": ["previousLicenceNumber"]}, "then": {"not": {"required": ["previousLicenceNumber"]}}, "type": "object", "allOf": [{"if": {"required": ["handlesAnimalOrigin"], "properties": {"handlesAnimalOrigin": {"const": true}}}, "then": {"properties": {"licenceClass": {"const": "APPROVAL"}}}, "$comment": "Product of animal origin forces the APPROVAL class. A genuine cross-field constraint between two independent applicant-declared fields — the thing the earlier draft of this bundle wrongly recorded as impossible."}, {"if": {"required": ["licenceClass"], "properties": {"licenceClass": {"const": "APPROVAL"}}}, "then": {"required": ["haccpPlanRef"]}, "$comment": "The APPROVAL class requires a HACCP plan reference."}, {"if": {"required": ["annualTurnover"], "properties": {"annualTurnover": {"minimum": 5000001}}}, "then": {"properties": {"licenceClass": {"not": {"const": "REGISTRATION"}}}}, "$comment": "Turnover above the notify-only ceiling rules OUT the REGISTRATION class. Uses `not` rather than an enum of the remaining values so that adding a fourth licenceClass does not silently exclude it. Enforced in this direction only: a declared turnover BELOW the ceiling does not force REGISTRATION, because turnover at application time is routinely approximate or projected and a hard floor would bounce an applicant who rounded conservatively."}, {"if": {"required": ["applicationType"], "properties": {"applicationType": {"const": "RENEWAL"}}}, "then": {"required": ["daysSinceExpiry"]}, "$comment": "A RENEWAL must state how overdue it is, so the penalty and interest rules have a value to band on. Zero is a valid answer and the expected one for a renewal filed in time."}, {"if": {"required": ["activityGroup"], "properties": {"activityGroup": {"const": "logistics"}}}, "then": {"required": ["outlets"]}, "$comment": "Storage and transport operators declare their premises. The five blocks that follow enforce activityPath against activityGroup — JSON Schema cannot compare two properties directly, so consistency is expressed as one if/then per group value. (\\\\.|$) admits a group-only path, since the category tree''s second level is optional."}, {"if": {"required": ["activityGroup"], "properties": {"activityGroup": {"const": "manufacturing"}}}, "then": {"properties": {"activityPath": {"pattern": "^manufacturing(\\.|$)"}}}}, {"if": {"required": ["activityGroup"], "properties": {"activityGroup": {"const": "retail"}}}, "then": {"properties": {"activityPath": {"pattern": "^retail(\\.|$)"}}}}, {"if": {"required": ["activityGroup"], "properties": {"activityGroup": {"const": "foodservice"}}}, "then": {"properties": {"activityPath": {"pattern": "^foodservice(\\.|$)"}}}}, {"if": {"required": ["activityGroup"], "properties": {"activityGroup": {"const": "logistics"}}}, "then": {"properties": {"activityPath": {"pattern": "^logistics(\\.|$)"}}}}, {"if": {"required": ["activityGroup"], "properties": {"activityGroup": {"const": "trade"}}}, "then": {"properties": {"activityPath": {"pattern": "^trade(\\.|$)"}}}}], "$schema": "https://json-schema.org/draft/2020-12/schema", "$comment": "Food Licence — worldwide-generic, deliberately SMALL (13 properties) and deliberately BROAD in the JSON Schema features it exercises. This file is the capability reference for the catalogue: every construct below is enforced server-side by CertificateDetailValidator, which runs networknt on SpecVersion.V202012, so if/then/else, allOf, not, dependentRequired and dependentSchemas are all real validation and not documentation. Modelled on the common shape of food-business authorisation across regimes — FSSAI registration/licence tiers (India), Regulation 852/2004 registration-vs-approval (EU), FDA facility registration plus state retail permits (US), SFA licensing (Singapore) — which all reduce to: a class of authorisation, an activity type, a measure of scale, whether animal-origin product is handled, and a HACCP/FSMS plan. NOT MODELLED HERE: applicant identity, addresses, uploaded documents and the declaration, all of which ride the fixed envelope and never reach certificateDetail; and the jurisdiction, which is CertificateApplyRequest.boundaryDetail. Every jsonPath in calculator/calculation-rules.json and vc/vc-credential-type.json resolves against a property of this file.", "required": ["applicationType", "licenceClass", "activityGroup", "activityPath", "annualTurnover", "premisesAreaSqm", "handlesAnimalOrigin", "licenceTermYears", "productCategories"], "properties": {"outlets": {"type": "array", "items": {"type": "object", "required": ["outletCode", "staffCount", "highRisk"], "properties": {"highRisk": {"type": "boolean"}, "openedOn": {"type": "string", "format": "date"}, "outletCode": {"type": "string", "pattern": "^[A-Z0-9-]{3,12}$"}, "staffCount": {"type": "integer", "maximum": 5000, "minimum": 1}}}, "$comment": "Premises operated under this licence. THE HIGHEST-VALUE FIELD IN THE BUNDLE: one property unlocks three calculator capabilities nothing else reaches — Scope.SUBENTITY (OUTLET_FEE prices each element separately), ruleType AGGREGATION (TOTAL_OUTLET_STAFF sums staffCount across elements), and AttributeCondition.derivedFrom (STAFF_LEVY bands on that derived total rather than on a payload field). DELIBERATELY OPTIONAL: JsonPathResolver.readArray returns List.of() on PathNotFound rather than throwing, so a single-premises applicant who omits it produces no OUTLET_FEE line items and a derived staff total of 0 — both paths are exercisable, which is the point of a test bundle. Inside a SUBENTITY rule, condition and appliesOn jsonPaths are RELATIVE to one element (''highRisk'', ''staffCount''), not rooted at $.certificateDetail.", "maxItems": 50, "minItems": 1}, "activityPath": {"type": "string", "pattern": "^(manufacturing|retail|foodservice|logistics|trade)(\\.[a-z0-9]+)?$", "$comment": "The full dotted path from categoryTree, e.g. ''manufacturing.dairy''. A flat string, so it prints on the licence and is prefix-searchable (''activityPath=manufacturing.*''). The pattern enforces the grammar; the allOf blocks below additionally enforce that it agrees with activityGroup, which pattern alone cannot express.", "maxLength": 64}, "haccpPlanRef": {"type": "string", "pattern": "^HACCP-[A-Z0-9]{4,12}$", "$comment": "Reference of the HACCP / food safety management plan. Conditionally required for the APPROVAL class (allOf below). Its mere PRESENCE earns HACCP_REBATE — the catalogue''s only presence-only condition, the third condition form AttributeCondition supports alongside equals and from/to, written as a condition object carrying a jsonPath and neither equals nor from.", "maxLength": 18, "minLength": 10}, "licenceClass": {"enum": ["REGISTRATION", "STANDARD", "APPROVAL"], "type": "string", "$comment": "The authorisation tier, worldwide-neutral. REGISTRATION is the notify-only tier (EU Art. 6(2) registration, FSSAI basic registration, FDA facility registration); STANDARD is an ordinary licence; APPROVAL is the establishment-approval tier that handling product of animal origin triggers (EU Art. 4(2)). Drives LICENCE_FEE as a RATE_MATRIX equals condition, so every value here needs a covering rule or RateMatrixEvaluator throws Rule.NoMatch."}, "activityGroup": {"enum": ["manufacturing", "retail", "foodservice", "logistics", "trade"], "type": "string", "$comment": "The categoryTree''s own top-level path segment — NOT the display name. THIS IS THE FIELD THAT LETS A FEE RULE CONDITION ON THE CATEGORY: ACTIVITY_FEE matches it with equals, and AttributeCondition has no prefix match, so the group cannot be read off activityPath''s dotted string by any rule. Carried separately for exactly that reason and no other; certificate search can prefix-match activityPath with a trailing ''*'', so search does not need it."}, "annualTurnover": {"type": "integer", "minimum": 0, "$comment": "Whole currency units, INTEGER not number. The integrality is load-bearing: AttributeConditionMatcher.inRange is inclusive at BOTH ends, so bands sharing a boundary tie at equal specificity and are resolved by a log warning and a deterministic pick rather than an error. Integer units let LICENCE_FEE''s bands be integer-adjacent with no epsilon. Also the subject of the turnover-versus-class cross-field rule below."}, "applicationType": {"enum": ["NEW", "RENEWAL", "VARIATION", "DUPLICATE"], "type": "string", "$comment": "Gates the conditional requirement of previousLicenceNumber via the top-level if/then/ELSE below — the one place in the catalogue that uses `else`, and it earns it: a NEW application must NOT cite a previous licence, every other type must. Flat, so it is searchable."}, "daysSinceExpiry": {"type": "integer", "maximum": 3650, "minimum": 0, "$comment": "Drives both LATE_RENEWAL_PENALTY (PENALTY, per-day) and LATE_PAYMENT_INTEREST (INTEREST, percentage) through from/to range conditions on the same field — two different rule types banding the same value. Frontend-computed, because the engine resolves jsonPaths against the payload and cannot do date arithmetic; this is the platform gap the spec''s HookConfig section is aimed at."}, "premisesAreaSqm": {"type": "number", "maximum": 100000, "$comment": "Drives PREMISES_INSPECTION_FEE, which is the catalogue''s one CORRECT use of calculationType SLAB: inspection effort genuinely scales with area at a decreasing marginal rate, so each tier''s rate applies only to the portion of the area inside it. That is what computeSlab does. It is the opposite of a banded flat fee, which is RATE_MATRIX + from/to — see LICENCE_FEE.", "exclusiveMinimum": 0}, "licenceTermYears": {"type": "integer", "maximum": 5, "minimum": 1, "$comment": "The term being bought. LICENCE_FEE is PER_UNIT with appliesOn.jsonPath pointing here, so the matched annual rate is multiplied by this. REQUIRED, and that is load-bearing: computePerUnit resolves this path AFTER the rule has matched and throws attributePathNotResolved if absent, which fails /estimate outright rather than degrading. NOTE THE DUPLICATION: the term that actually stamps validFrom/validUntil is CertificateApplyRequest.requestedValidityDays, an envelope field the calculator cannot see. See the bundle README''s gap 1."}, "productCategories": {"type": "array", "items": {"enum": ["DAIRY", "MEAT", "FISH", "PRODUCE", "BAKERY", "BEVERAGES", "PACKAGED", "OTHER"], "type": "string"}, "$comment": "The product scope endorsed on the licence. An ARRAY with uniqueItems and bounded length — exercising array-shaped validation, which nothing else in the catalogue does. It is deliberately NOT rendered on the PDF: flattenJson skips arrays outright, so any array is invisible to the document. Where a list MUST print, it has to be a flat string instead; DRIVING_LICENSE.identificationMarks is that trade-off, and this field is the counter-example where structure wins because the licence prints activityPath instead.", "maxItems": 8, "minItems": 1, "uniqueItems": true}, "handlesAnimalOrigin": {"type": "boolean", "$comment": "Whether product of animal origin is handled. A BOOLEAN condition target — ANIMAL_ORIGIN_SURCHARGE matches it with equals:true, which exercises AttributeConditionMatcher.valuesEqual''s String.valueOf comparison against a JSON boolean rather than a string enum. Also forces licenceClass to APPROVAL through the cross-field allOf block below, which is Regulation 852/2004 Article 4(2) expressed as config rather than as prose in eligibilityCriteria."}, "previousLicenceNumber": {"type": "string", "$comment": "Required for RENEWAL/VARIATION/DUPLICATE and forbidden for NEW — see the top-level if/then/else. dependentRequired below additionally ties daysSinceExpiry to it, so a late-renewal penalty can never be charged against an application that names no prior licence.", "maxLength": 32}}, "dependentSchemas": {"outlets": {"properties": {"licenceClass": {"not": {"const": "REGISTRATION"}}}}}, "dependentRequired": {"daysSinceExpiry": ["previousLicenceNumber"]}, "$comment_conditionals": "Everything below is ENFORCED, not advisory. CertificateDetailValidator runs networknt V202012 and CertificateSchemaService.validateChecklist calls the same validator, so the same vocabulary is available to checklists."}', 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788283169983, 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788283169983);
INSERT INTO "BASETENANT".schema_definition (id, module_code, entity_code, tag, version, is_active, notes, schema_body, created_by, created_time, modified_by, modified_time) VALUES ('e815db17-1e40-4ffd-b48f-71bcada808d3', 'certificate', 'FOOD_LICENSE.checklist.e504a163-a165-4ab6-a479-60a5913be4cc', 'PENDING_INSPECTION.COMPLETE_INSPECTION', 2, false, NULL, '{"if": {"required": ["riskRating"], "properties": {"riskRating": {"const": "HIGH"}}}, "then": {"required": ["correctiveActionDueBy", "inspectorNotes"]}, "type": "object", "title": "checklist.title", "$schema": "https://json-schema.org/draft/2020-12/schema", "$comment": "The food safety inspection report, submitted by the inspector alongside the PENDING_INSPECTION.COMPLETE_INSPECTION transition — the single tag CertificateSchemaService.CHECKLIST_TAG is hardcoded to. Eight fields, and each one is a DIFFERENT data type on purpose: this is the catalogue''s reference for what a checklist can carry. boolean, date, free text, integer, single-choice enum, multi-choice enum array, file array, and one conditionally-required date. CertificateSchemaService.validateChecklist calls the SAME CertificateDetailValidator the application form goes through, so everything here is enforced server-side — including the if/then block at the bottom, which nothing else in the catalogue demonstrates on a checklist.", "required": ["inspectionPassed", "inspectionDate", "hygieneScore", "riskRating", "evidencePhotos"], "properties": {"riskRating": {"enum": ["LOW", "MEDIUM", "HIGH"], "type": "string", "title": "riskRating", "$comment": "SINGLE-CHOICE ENUM — renders as radio buttons. Drives the conditional requirement at the bottom of this file."}, "hygieneScore": {"type": "integer", "title": "hygieneScore", "maximum": 100, "minimum": 0, "$comment": "INTEGER with bounds — renders as a number input. Scored out of 100 and constrained to multiples of 5, which exercises multipleOf.", "multipleOf": 5}, "evidencePhotos": {"type": "array", "items": {"type": "string", "format": "uri"}, "title": "evidencePhotos", "$comment": "FILE ARRAY — items are format: uri, renders as a multi-file upload. At least one is required, so an inspection cannot be closed on assertion alone.", "minItems": 1}, "inspectionDate": {"type": "string", "title": "inspectionDate", "format": "date", "$comment": "DATE — format: date, renders as a date picker. The officer''s own date of attendance, which can differ from the transition timestamp."}, "inspectorNotes": {"type": "string", "title": "inspectorNotes", "$comment": "FREE TEXT — renders as a textarea. Bounded so a pasted report cannot bloat the JSONB row.", "maxLength": 2000}, "nonConformities": {"type": "array", "items": {"enum": ["HYGIENE", "PEST_CONTROL", "TEMPERATURE_CONTROL", "LABELLING", "WATER_QUALITY", "STAFF_TRAINING", "RECORD_KEEPING"], "type": "string"}, "title": "nonConformities", "$comment": "MULTI-CHOICE ENUM ARRAY with uniqueItems — renders as a multiselect. An array, so it can never appear on a rendered document; that is fine, a checklist is not printed.", "maxItems": 7, "uniqueItems": true}, "inspectionPassed": {"type": "boolean", "title": "inspectionPassed", "$comment": "BOOLEAN — renders as a checkbox."}, "correctiveActionDueBy": {"type": "string", "title": "correctiveActionDueBy", "format": "date", "$comment": "CONDITIONALLY-REQUIRED DATE — required only when riskRating is HIGH, via the if/then below. Proof that the same conditional vocabulary the application form uses is available on a checklist, because both go through CertificateDetailValidator."}}}', 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788283170687, 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788283170687);
INSERT INTO "BASETENANT".schema_definition (id, module_code, entity_code, tag, version, is_active, notes, schema_body, created_by, created_time, modified_by, modified_time) VALUES ('f6e6b080-97e4-4a19-aed1-2422df2e4154', 'certificate', 'LEARNER_LICENSE_V2.checklist.c8e858f6-726a-494e-9095-5a02aeecc793', 'PENDING_INSPECTION.COMPLETE_INSPECTION', 1, true, NULL, '{"type": "object", "title": "Theory Test Result", "$schema": "https://json-schema.org/draft/2020-12/schema", "$comment": "The THEORY-test result form, submitted by the examiner alongside the PENDING_INSPECTION.COMPLETE_INSPECTION transition. ''Inspection'' is the platform''s word, not the domain''s — CertificateSchemaService.CHECKLIST_TAG is hardcoded to that exact state.action pair, so this checklist binds to the theory test only because the workflow state is named PENDING_INSPECTION. The workflow state''s name renders as ''Theory Test'' (see workflow/LEARNER_LICENSE_V2.json); the codes cannot change. THIS FILE IS THE REASON LEARNER_LICENSE_V2 EXISTS as a separate certificate type: exactly one checklist binds per type, under that one hardcoded tag, and a theory test and a practical driving test cannot be the same form. DRIVING_LICENSE''s checklist requires practicalTestResult, which a learner applicant could never supply.", "required": ["testConducted", "identityVerifiedAtCentre", "eyesightTestResult", "theoryTestScore", "theoryTestResult"], "properties": {"testMode": {"enum": ["ONLINE_TERMINAL", "WRITTEN", "ORAL"], "type": "string", "title": "Test Mode"}, "testConducted": {"type": "boolean", "title": "Test was conducted"}, "testCentreCode": {"type": "string", "title": "Test Centre Code"}, "examinerRemarks": {"type": "string", "title": "Examiner''s Remarks"}, "theoryTestScore": {"type": "integer", "title": "Theory Test Score (out of 15)", "maximum": 15, "minimum": 0, "$comment": "Out of 15, the standard number of questions in the RTO learner''s theory test. Required here, where DRIVING_LICENSE''s checklist does not carry it at all: a theory score is the entire substance of this examination."}, "theoryTestResult": {"enum": ["PASS", "FAIL", "ABSENT"], "type": "string", "title": "Theory Test Result", "$comment": "The examiner''s verdict, kept separate from theoryTestScore rather than derived from it — the pass mark is an RTO policy that varies, and nothing in the schema grammar can express ''PASS when score >= 9''."}, "eyesightTestResult": {"enum": ["PASS", "FAIL", "PASS_WITH_CORRECTIVE_LENSES"], "type": "string", "title": "Eyesight Test Result", "$comment": "The eyesight test is statutorily part of the learner''s licence examination, not the permanent one — this is where a corrective-lenses endorsement originates."}, "identityVerifiedAtCentre": {"enum": ["YES", "NO"], "type": "string", "title": "Identity verified at the test centre"}}}', 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788298572132, 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788298572336);
INSERT INTO "BASETENANT".schema_definition (id, module_code, entity_code, tag, version, is_active, notes, schema_body, created_by, created_time, modified_by, modified_time) VALUES ('17d68a70-db19-475b-8feb-1aff09b9688b', 'certificate', 'LEARNER_LICENSE.checklist.59ddb7cd-c745-4a97-90c5-247da42e2ea4', 'PENDING_INSPECTION.COMPLETE_INSPECTION', 3, true, NULL, '{"type": "object", "title": "Theory Test Result", "$schema": "https://json-schema.org/draft/2020-12/schema", "$comment": "The THEORY-test result form, submitted by the examiner alongside the PENDING_INSPECTION.COMPLETE_INSPECTION transition. ''Inspection'' is the platform''s word, not the domain''s — CertificateSchemaService.CHECKLIST_TAG is hardcoded to that exact state.action pair, so this checklist binds to the theory test only because the workflow state is named PENDING_INSPECTION. The workflow state''s name renders as ''Theory Test'' (see workflow/LEARNER_LICENSE.json); the codes cannot change. THIS FILE IS THE REASON LEARNER_LICENSE EXISTS as a separate certificate type: exactly one checklist binds per type, under that one hardcoded tag, and a theory test and a practical driving test cannot be the same form. DRIVING_LICENSE''s checklist requires practicalTestResult, which a learner applicant could never supply.", "required": ["testConducted", "identityVerifiedAtCentre", "eyesightTestResult", "theoryTestScore", "theoryTestResult"], "properties": {"testMode": {"enum": ["ONLINE_TERMINAL", "WRITTEN", "ORAL"], "type": "string", "title": "Test Mode"}, "testConducted": {"type": "boolean", "title": "Test was conducted"}, "testCentreCode": {"type": "string", "title": "Test Centre Code"}, "examinerRemarks": {"type": "string", "title": "Examiner''s Remarks"}, "theoryTestScore": {"type": "integer", "title": "Theory Test Score (out of 15)", "maximum": 15, "minimum": 0, "$comment": "Out of 15, the standard number of questions in the RTO learner''s theory test. Required here, where DRIVING_LICENSE''s checklist does not carry it at all: a theory score is the entire substance of this examination."}, "theoryTestResult": {"enum": ["PASS", "FAIL", "ABSENT"], "type": "string", "title": "Theory Test Result", "$comment": "The examiner''s verdict, kept separate from theoryTestScore rather than derived from it — the pass mark is an RTO policy that varies, and nothing in the schema grammar can express ''PASS when score >= 9''."}, "eyesightTestResult": {"enum": ["PASS", "FAIL", "PASS_WITH_CORRECTIVE_LENSES"], "type": "string", "title": "Eyesight Test Result", "$comment": "The eyesight test is statutorily part of the learner''s licence examination, not the permanent one — this is where a corrective-lenses endorsement originates."}, "identityVerifiedAtCentre": {"enum": ["YES", "NO"], "type": "string", "title": "Identity verified at the test centre"}}}', 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788439662067, 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788439662067);
INSERT INTO "BASETENANT".schema_definition (id, module_code, entity_code, tag, version, is_active, notes, schema_body, created_by, created_time, modified_by, modified_time) VALUES ('010f0000-a052-4f60-85c7-adc4c1f2c248', 'certificate', 'DRIVING_LICENSE.form.1594690b-b1cf-4677-b0a3-de4e8a4c5925', NULL, 2, true, NULL, '{"type": "object", "$schema": "https://json-schema.org/draft/2020-12/schema", "$comment": "Driving License — the licence-specific section of the application ONLY. Applicant identity, addresses, uploaded documents and the declaration are hardcoded on the frontend and submitted to different services entirely (holder/partyDetails, the documents list, the declaration block on CertificateApplyRequest); none of that reaches certificateDetail, so nothing here duplicates them. Boundary (the applicant''s RTO jurisdiction) is driven by certificate_type.boundaryConfig and submitted as CertificateApplyRequest.boundaryDetail, a top-level field outside certificateDetail, so it is deliberately absent here too. Every field a jsonPath elsewhere in this bundle resolves against — calculator/calculation-rules.json and vc/vc-credential-type.json — is a property of this file.", "required": ["applicationType", "vehicleClass", "dateOfBirth", "bloodGroup"], "properties": {"bloodGroup": {"enum": ["A+", "A-", "B+", "B-", "AB+", "AB-", "O+", "O-"], "type": "string", "title": "Blood Group"}, "dateOfBirth": {"type": "string", "title": "Date of Birth", "format": "date", "$comment": "The age gates in eligibilityCriteria are advisory and never enforced by the service, so this is collected for the licence face and for the issuing officer''s own check, not for validation here."}, "vehicleClass": {"type": "object", "title": "Class of Vehicle", "$comment": "group is the categoryTree''s own top-level path segment (''nontransport'' / ''transport'') — NOT the display name; CLASS_SURCHARGE in calculation-rules.json matches on it with equals. licenceClass is the full dotted leaf path. Nested, and therefore NOT searchable — the same shape and the same limitation as FIRE_NOC''s usageType.", "required": ["group", "licenceClass"], "properties": {"group": {"enum": ["nontransport", "transport"], "type": "string", "title": "Vehicle Class Group"}, "licenceClass": {"type": "string", "title": "Vehicle Class"}}}, "applicationType": {"enum": ["PERMANENT", "RENEWAL", "DUPLICATE", "INTERNATIONAL"], "type": "string", "title": "Application Type", "$comment": "Drives BASE_FEE and TEST_FEE in calculation-rules.json. Both are RATE_MATRIX components, so every value in this enum MUST have a matching rule or RateMatrixEvaluator throws Rule.NoMatch — adding a value here without adding two rules there breaks fee calculation for that value only, at /estimate time. Top-level and flat, so it is searchable (CertificateSpecification matches single top-level keys only). LEARNER is deliberately NOT a value here: a learner''s licence is the separate LEARNER_LICENSE certificate type, because the two need different checklists and one type can hold only one (CertificateSchemaService binds exactly one checklist per type, under the single hardcoded PENDING_INSPECTION.COMPLETE_INSPECTION tag)."}, "daysSinceExpiry": {"type": "integer", "title": "Days Since Expiry", "minimum": 0, "$comment": "Drives LATE_RENEWAL_PENALTY in calculation-rules.json via a from/to range condition. Submitted by the frontend as a computed value rather than derived here, because the calculator''s condition grammar resolves jsonPaths against the payload only — it cannot compute a date difference (AttributeCondition supports equals XOR from/to XOR presence, nothing more). 0 for anything that is not an overdue renewal."}, "drivingSchoolName": {"type": "string", "title": "Driving School Name", "maxLength": 128}, "organDonorConsent": {"type": "boolean", "title": "I consent to be recorded as an organ donor", "default": false}, "identificationMarks": {"type": "string", "title": "Identification Marks", "$comment": "Printed on the licence face; two marks is the statutory norm, entered as one free-text line. A string, NOT an array, and that is forced by the PDF: CertificatePdfService.flattenJson skips arrays and nested objects outright rather than half-rendering them, so an array here would be silently absent from every licence card. The data model bends to the renderer because the alternative is a blank field on a statutory document.", "maxLength": 240}, "emergencyContactName": {"type": "string", "title": "Emergency Contact Name", "maxLength": 128}, "learnerLicenceNumber": {"type": "string", "title": "Learner''s Licence Number", "$comment": "Required in practice for applicationType PERMANENT, but not expressible as a conditional requirement here: this schema is validated as-is by CertificateDetailValidator, and a JSON Schema if/then block would be enforced by the validator but ignored by the jsonforms UI, which reads ui_schema''s own rule blocks instead. The conditional visibility lives in DRIVING_LICENSE_ui_schema.json; the officer''s own check at PENDING_DOCUMENT_VERIFICATION is the real gate. Flat, so it is searchable.", "maxLength": 32}, "existingLicenceNumber": {"type": "string", "title": "Existing Licence Number", "$comment": "The licence being renewed, duplicated or converted. Flat, so it is searchable — this is the field an officer looks an applicant up by.", "maxLength": 32}, "emergencyContactNumber": {"type": "string", "title": "Emergency Contact Number", "maxLength": 16}, "medicalCertificateNumber": {"type": "string", "title": "Medical Certificate Number (Form 1A)", "$comment": "Form 1A medical certificate reference. Statutorily required for every Transport class and for any applicant over 40; the document itself is uploaded against the MEDICAL_CERTIFICATE_FORM_1A category (see filestore/document-categories.json).", "maxLength": 64}, "hasPreviousLicenceSuspension": {"type": "boolean", "title": "Has a previous licence ever been suspended or revoked?", "default": false}}}', 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788439725376, 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788439725376);
INSERT INTO "BASETENANT".schema_definition (id, module_code, entity_code, tag, version, is_active, notes, schema_body, created_by, created_time, modified_by, modified_time) VALUES ('420fbbd1-ce17-426b-88fe-1dbd75b96492', 'certificate', 'DRIVING_LICENSE.checklist.fef7a534-4fd7-49de-b882-615a34612a44', 'PENDING_INSPECTION.COMPLETE_INSPECTION', 2, false, NULL, '{"type": "object", "title": "checklist.title", "$schema": "https://json-schema.org/draft/2020-12/schema", "$comment": "The PRACTICAL driving-test result form, submitted by the examiner alongside the PENDING_INSPECTION.COMPLETE_INSPECTION transition. ''Inspection'' is the platform''s word, not the domain''s — CertificateSchemaService.CHECKLIST_TAG is hardcoded to that exact state.action pair, so this checklist binds to the driving test only because the workflow state is named PENDING_INSPECTION. The label renders as ''Driving Test'' (see workflow.labels.json); the codes cannot change. THE THEORY TEST IS NOT HERE: exactly one checklist binds per certificate type (one type, one hardcoded tag), so the learner''s theory test lives in the LEARNER_LICENSE bundle''s own checklist. That constraint is why the two are separate certificate types at all — practicalTestResult is required below, and a learner applicant could never satisfy it.", "required": ["testConducted", "identityVerifiedAtCentre", "eyesightTestResult", "practicalTestResult", "testPhotos"], "properties": {"testPhotos": {"type": "array", "items": {"type": "string", "format": "uri"}, "title": "testPhotos", "minItems": 1}, "testConducted": {"type": "boolean", "title": "testConducted"}, "testTrackCode": {"type": "string", "title": "testTrackCode"}, "examinerRemarks": {"type": "string", "title": "examinerRemarks"}, "eyesightTestResult": {"enum": ["PASS", "FAIL", "PASS_WITH_CORRECTIVE_LENSES"], "type": "string", "title": "eyesightTestResult"}, "vehicleUsedForTest": {"type": "string", "title": "vehicleUsedForTest"}, "practicalTestResult": {"enum": ["PASS", "FAIL", "ABSENT"], "type": "string", "title": "practicalTestResult"}, "identityVerifiedAtCentre": {"enum": ["YES", "NO"], "type": "string", "title": "identityVerifiedAtCentre"}}}', 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788283181178, 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788283181178);
INSERT INTO "BASETENANT".schema_definition (id, module_code, entity_code, tag, version, is_active, notes, schema_body, created_by, created_time, modified_by, modified_time) VALUES ('49a81cbd-84cf-4df6-a948-5d7ae8c67d64', 'certificate', 'DRIVING_LICENSE.checklist.fef7a534-4fd7-49de-b882-615a34612a44', 'PENDING_INSPECTION.COMPLETE_INSPECTION', 3, true, NULL, '{"type": "object", "title": "Driving Test Result", "$schema": "https://json-schema.org/draft/2020-12/schema", "$comment": "The PRACTICAL driving-test result form, submitted by the examiner alongside the PENDING_INSPECTION.COMPLETE_INSPECTION transition. ''Inspection'' is the platform''s word, not the domain''s — CertificateSchemaService.CHECKLIST_TAG is hardcoded to that exact state.action pair, so this checklist binds to the driving test only because the workflow state is named PENDING_INSPECTION. The label renders as ''Driving Test'' (see workflow.labels.json); the codes cannot change. THE THEORY TEST IS NOT HERE: exactly one checklist binds per certificate type (one type, one hardcoded tag), so the learner''s theory test lives in the LEARNER_LICENSE bundle''s own checklist. That constraint is why the two are separate certificate types at all — practicalTestResult is required below, and a learner applicant could never satisfy it.", "required": ["testConducted", "identityVerifiedAtCentre", "eyesightTestResult", "practicalTestResult", "testPhotos"], "properties": {"testPhotos": {"type": "array", "items": {"type": "string", "format": "uri"}, "title": "Test Photographs", "minItems": 1}, "testConducted": {"type": "boolean", "title": "Test was conducted"}, "testTrackCode": {"type": "string", "title": "Test Track Code"}, "examinerRemarks": {"type": "string", "title": "Examiner''s Remarks"}, "eyesightTestResult": {"enum": ["PASS", "FAIL", "PASS_WITH_CORRECTIVE_LENSES"], "type": "string", "title": "Eyesight Test Result"}, "vehicleUsedForTest": {"type": "string", "title": "Vehicle Used for the Test"}, "practicalTestResult": {"enum": ["PASS", "FAIL", "ABSENT"], "type": "string", "title": "Practical Test Result"}, "identityVerifiedAtCentre": {"enum": ["YES", "NO"], "type": "string", "title": "Identity verified at the test centre"}}}', 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788439725885, 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788439725885);
INSERT INTO "BASETENANT".schema_definition (id, module_code, entity_code, tag, version, is_active, notes, schema_body, created_by, created_time, modified_by, modified_time) VALUES ('bbf5b4a7-f733-441b-8486-5c1d4cb9d180', 'certificate', 'FOOD_LICENSE.form.3136481e-e525-47e3-862e-f12b9b8967c0', NULL, 3, true, NULL, '{"if": {"required": ["applicationType"], "properties": {"applicationType": {"const": "NEW"}}}, "else": {"required": ["previousLicenceNumber"]}, "then": {"not": {"required": ["previousLicenceNumber"]}}, "type": "object", "allOf": [{"if": {"required": ["handlesAnimalOrigin"], "properties": {"handlesAnimalOrigin": {"const": true}}}, "then": {"properties": {"licenceClass": {"const": "APPROVAL"}}}, "$comment": "Product of animal origin forces the APPROVAL class. A genuine cross-field constraint between two independent applicant-declared fields — the thing the earlier draft of this bundle wrongly recorded as impossible."}, {"if": {"required": ["licenceClass"], "properties": {"licenceClass": {"const": "APPROVAL"}}}, "then": {"required": ["haccpPlanRef"]}, "$comment": "The APPROVAL class requires a HACCP plan reference."}, {"if": {"required": ["annualTurnover"], "properties": {"annualTurnover": {"minimum": 5000001}}}, "then": {"properties": {"licenceClass": {"not": {"const": "REGISTRATION"}}}}, "$comment": "Turnover above the notify-only ceiling rules OUT the REGISTRATION class. Uses `not` rather than an enum of the remaining values so that adding a fourth licenceClass does not silently exclude it. Enforced in this direction only: a declared turnover BELOW the ceiling does not force REGISTRATION, because turnover at application time is routinely approximate or projected and a hard floor would bounce an applicant who rounded conservatively."}, {"if": {"required": ["applicationType"], "properties": {"applicationType": {"const": "RENEWAL"}}}, "then": {"required": ["daysSinceExpiry"]}, "$comment": "A RENEWAL must state how overdue it is, so the penalty and interest rules have a value to band on. Zero is a valid answer and the expected one for a renewal filed in time."}, {"if": {"required": ["activityGroup"], "properties": {"activityGroup": {"const": "logistics"}}}, "then": {"required": ["outlets"]}, "$comment": "Storage and transport operators declare their premises. The five blocks that follow enforce activityPath against activityGroup — JSON Schema cannot compare two properties directly, so consistency is expressed as one if/then per group value. (\\\\.|$) admits a group-only path, since the category tree''s second level is optional."}, {"if": {"required": ["activityGroup"], "properties": {"activityGroup": {"const": "manufacturing"}}}, "then": {"properties": {"activityPath": {"pattern": "^manufacturing(\\.|$)"}}}}, {"if": {"required": ["activityGroup"], "properties": {"activityGroup": {"const": "retail"}}}, "then": {"properties": {"activityPath": {"pattern": "^retail(\\.|$)"}}}}, {"if": {"required": ["activityGroup"], "properties": {"activityGroup": {"const": "foodservice"}}}, "then": {"properties": {"activityPath": {"pattern": "^foodservice(\\.|$)"}}}}, {"if": {"required": ["activityGroup"], "properties": {"activityGroup": {"const": "logistics"}}}, "then": {"properties": {"activityPath": {"pattern": "^logistics(\\.|$)"}}}}, {"if": {"required": ["activityGroup"], "properties": {"activityGroup": {"const": "trade"}}}, "then": {"properties": {"activityPath": {"pattern": "^trade(\\.|$)"}}}}], "$schema": "https://json-schema.org/draft/2020-12/schema", "$comment": "Food Licence — worldwide-generic, deliberately SMALL (13 properties) and deliberately BROAD in the JSON Schema features it exercises. This file is the capability reference for the catalogue: every construct below is enforced server-side by CertificateDetailValidator, which runs networknt on SpecVersion.V202012, so if/then/else, allOf, not, dependentRequired and dependentSchemas are all real validation and not documentation. Modelled on the common shape of food-business authorisation across regimes — FSSAI registration/licence tiers (India), Regulation 852/2004 registration-vs-approval (EU), FDA facility registration plus state retail permits (US), SFA licensing (Singapore) — which all reduce to: a class of authorisation, an activity type, a measure of scale, whether animal-origin product is handled, and a HACCP/FSMS plan. NOT MODELLED HERE: applicant identity, addresses, uploaded documents and the declaration, all of which ride the fixed envelope and never reach certificateDetail; and the jurisdiction, which is CertificateApplyRequest.boundaryDetail. Every jsonPath in calculator/calculation-rules.json and vc/vc-credential-type.json resolves against a property of this file.", "required": ["applicationType", "licenceClass", "activityGroup", "activityPath", "annualTurnover", "premisesAreaSqm", "handlesAnimalOrigin", "licenceTermYears", "productCategories"], "properties": {"outlets": {"type": "array", "items": {"type": "object", "required": ["outletCode", "staffCount", "highRisk"], "properties": {"highRisk": {"type": "boolean"}, "openedOn": {"type": "string", "format": "date"}, "outletCode": {"type": "string", "pattern": "^[A-Z0-9-]{3,12}$"}, "staffCount": {"type": "integer", "maximum": 5000, "minimum": 1}}}, "title": "Outlets", "$comment": "Premises operated under this licence. THE HIGHEST-VALUE FIELD IN THE BUNDLE: one property unlocks three calculator capabilities nothing else reaches — Scope.SUBENTITY (OUTLET_FEE prices each element separately), ruleType AGGREGATION (TOTAL_OUTLET_STAFF sums staffCount across elements), and AttributeCondition.derivedFrom (STAFF_LEVY bands on that derived total rather than on a payload field). DELIBERATELY OPTIONAL: JsonPathResolver.readArray returns List.of() on PathNotFound rather than throwing, so a single-premises applicant who omits it produces no OUTLET_FEE line items and a derived staff total of 0 — both paths are exercisable, which is the point of a test bundle. Inside a SUBENTITY rule, condition and appliesOn jsonPaths are RELATIVE to one element (''highRisk'', ''staffCount''), not rooted at $.certificateDetail.", "maxItems": 50, "minItems": 1}, "activityPath": {"type": "string", "title": "Activity", "pattern": "^(manufacturing|retail|foodservice|logistics|trade)(\\.[a-z0-9]+)?$", "$comment": "The full dotted path from categoryTree, e.g. ''manufacturing.dairy''. A flat string, so it prints on the licence and is prefix-searchable (''activityPath=manufacturing.*''). The pattern enforces the grammar; the allOf blocks below additionally enforce that it agrees with activityGroup, which pattern alone cannot express.", "maxLength": 64}, "haccpPlanRef": {"type": "string", "title": "HACCP Plan Reference", "pattern": "^HACCP-[A-Z0-9]{4,12}$", "$comment": "Reference of the HACCP / food safety management plan. Conditionally required for the APPROVAL class (allOf below). Its mere PRESENCE earns HACCP_REBATE — the catalogue''s only presence-only condition, the third condition form AttributeCondition supports alongside equals and from/to, written as a condition object carrying a jsonPath and neither equals nor from.", "maxLength": 18, "minLength": 10}, "licenceClass": {"enum": ["REGISTRATION", "STANDARD", "APPROVAL"], "type": "string", "title": "Authorisation Class", "$comment": "The authorisation tier, worldwide-neutral. REGISTRATION is the notify-only tier (EU Art. 6(2) registration, FSSAI basic registration, FDA facility registration); STANDARD is an ordinary licence; APPROVAL is the establishment-approval tier that handling product of animal origin triggers (EU Art. 4(2)). Drives LICENCE_FEE as a RATE_MATRIX equals condition, so every value here needs a covering rule or RateMatrixEvaluator throws Rule.NoMatch."}, "activityGroup": {"enum": ["manufacturing", "retail", "foodservice", "logistics", "trade"], "type": "string", "title": "Activity Group", "$comment": "The categoryTree''s own top-level path segment — NOT the display name. THIS IS THE FIELD THAT LETS A FEE RULE CONDITION ON THE CATEGORY: ACTIVITY_FEE matches it with equals, and AttributeCondition has no prefix match, so the group cannot be read off activityPath''s dotted string by any rule. Carried separately for exactly that reason and no other; certificate search can prefix-match activityPath with a trailing ''*'', so search does not need it."}, "annualTurnover": {"type": "integer", "title": "Annual Turnover", "minimum": 0, "$comment": "Whole currency units, INTEGER not number. The integrality is load-bearing: AttributeConditionMatcher.inRange is inclusive at BOTH ends, so bands sharing a boundary tie at equal specificity and are resolved by a log warning and a deterministic pick rather than an error. Integer units let LICENCE_FEE''s bands be integer-adjacent with no epsilon. Also the subject of the turnover-versus-class cross-field rule below."}, "applicationType": {"enum": ["NEW", "RENEWAL", "VARIATION", "DUPLICATE"], "type": "string", "title": "Application Type", "$comment": "Gates the conditional requirement of previousLicenceNumber via the top-level if/then/ELSE below — the one place in the catalogue that uses `else`, and it earns it: a NEW application must NOT cite a previous licence, every other type must. Flat, so it is searchable."}, "daysSinceExpiry": {"type": "integer", "title": "Days Since Expiry", "maximum": 3650, "minimum": 0, "$comment": "Drives both LATE_RENEWAL_PENALTY (PENALTY, per-day) and LATE_PAYMENT_INTEREST (INTEREST, percentage) through from/to range conditions on the same field — two different rule types banding the same value. Frontend-computed, because the engine resolves jsonPaths against the payload and cannot do date arithmetic; this is the platform gap the spec''s HookConfig section is aimed at."}, "premisesAreaSqm": {"type": "number", "title": "Premises Area (sq m)", "maximum": 100000, "$comment": "Drives PREMISES_INSPECTION_FEE, which is the catalogue''s one CORRECT use of calculationType SLAB: inspection effort genuinely scales with area at a decreasing marginal rate, so each tier''s rate applies only to the portion of the area inside it. That is what computeSlab does. It is the opposite of a banded flat fee, which is RATE_MATRIX + from/to — see LICENCE_FEE.", "exclusiveMinimum": 0}, "licenceTermYears": {"type": "integer", "title": "Licence Term (Years)", "maximum": 5, "minimum": 1, "$comment": "The term being bought. LICENCE_FEE is PER_UNIT with appliesOn.jsonPath pointing here, so the matched annual rate is multiplied by this. REQUIRED, and that is load-bearing: computePerUnit resolves this path AFTER the rule has matched and throws attributePathNotResolved if absent, which fails /estimate outright rather than degrading. NOTE THE DUPLICATION: the term that actually stamps validFrom/validUntil is CertificateApplyRequest.requestedValidityDays, an envelope field the calculator cannot see. See the bundle README''s gap 1."}, "productCategories": {"type": "array", "items": {"enum": ["DAIRY", "MEAT", "FISH", "PRODUCE", "BAKERY", "BEVERAGES", "PACKAGED", "OTHER"], "type": "string"}, "title": "Product Categories", "$comment": "The product scope endorsed on the licence. An ARRAY with uniqueItems and bounded length — exercising array-shaped validation, which nothing else in the catalogue does. It is deliberately NOT rendered on the PDF: flattenJson skips arrays outright, so any array is invisible to the document. Where a list MUST print, it has to be a flat string instead; DRIVING_LICENSE.identificationMarks is that trade-off, and this field is the counter-example where structure wins because the licence prints activityPath instead.", "maxItems": 8, "minItems": 1, "uniqueItems": true}, "handlesAnimalOrigin": {"type": "boolean", "title": "Handles Product of Animal Origin", "$comment": "Whether product of animal origin is handled. A BOOLEAN condition target — ANIMAL_ORIGIN_SURCHARGE matches it with equals:true, which exercises AttributeConditionMatcher.valuesEqual''s String.valueOf comparison against a JSON boolean rather than a string enum. Also forces licenceClass to APPROVAL through the cross-field allOf block below, which is Regulation 852/2004 Article 4(2) expressed as config rather than as prose in eligibilityCriteria."}, "previousLicenceNumber": {"type": "string", "title": "Previous Licence Number", "$comment": "Required for RENEWAL/VARIATION/DUPLICATE and forbidden for NEW — see the top-level if/then/else. dependentRequired below additionally ties daysSinceExpiry to it, so a late-renewal penalty can never be charged against an application that names no prior licence.", "maxLength": 32}}, "dependentSchemas": {"outlets": {"properties": {"licenceClass": {"not": {"const": "REGISTRATION"}}}}}, "dependentRequired": {"daysSinceExpiry": ["previousLicenceNumber"]}, "$comment_conditionals": "Everything below is ENFORCED, not advisory. CertificateDetailValidator runs networknt V202012 and CertificateSchemaService.validateChecklist calls the same validator, so the same vocabulary is available to checklists."}', 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788439834069, 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788439834069);
INSERT INTO "BASETENANT".schema_definition (id, module_code, entity_code, tag, version, is_active, notes, schema_body, created_by, created_time, modified_by, modified_time) VALUES ('bdf132ff-81cd-49d8-afee-c24222713862', 'certificate', 'FOOD_LICENSE.checklist.e504a163-a165-4ab6-a479-60a5913be4cc', 'PENDING_INSPECTION.COMPLETE_INSPECTION', 3, true, NULL, '{"if": {"required": ["riskRating"], "properties": {"riskRating": {"const": "HIGH"}}}, "then": {"required": ["correctiveActionDueBy", "inspectorNotes"]}, "type": "object", "title": "Food Safety Inspection Report", "$schema": "https://json-schema.org/draft/2020-12/schema", "$comment": "The food safety inspection report, submitted by the inspector alongside the PENDING_INSPECTION.COMPLETE_INSPECTION transition — the single tag CertificateSchemaService.CHECKLIST_TAG is hardcoded to. Eight fields, and each one is a DIFFERENT data type on purpose: this is the catalogue''s reference for what a checklist can carry. boolean, date, free text, integer, single-choice enum, multi-choice enum array, file array, and one conditionally-required date. CertificateSchemaService.validateChecklist calls the SAME CertificateDetailValidator the application form goes through, so everything here is enforced server-side — including the if/then block at the bottom, which nothing else in the catalogue demonstrates on a checklist.", "required": ["inspectionPassed", "inspectionDate", "hygieneScore", "riskRating", "evidencePhotos"], "properties": {"riskRating": {"enum": ["LOW", "MEDIUM", "HIGH"], "type": "string", "title": "Risk Rating", "$comment": "SINGLE-CHOICE ENUM — renders as radio buttons. Drives the conditional requirement at the bottom of this file."}, "hygieneScore": {"type": "integer", "title": "Hygiene Score (0-100)", "maximum": 100, "minimum": 0, "$comment": "INTEGER with bounds — renders as a number input. Scored out of 100 and constrained to multiples of 5, which exercises multipleOf.", "multipleOf": 5}, "evidencePhotos": {"type": "array", "items": {"type": "string", "format": "uri"}, "title": "Evidence Photographs", "$comment": "FILE ARRAY — items are format: uri, renders as a multi-file upload. At least one is required, so an inspection cannot be closed on assertion alone.", "minItems": 1}, "inspectionDate": {"type": "string", "title": "Date of Inspection", "format": "date", "$comment": "DATE — format: date, renders as a date picker. The officer''s own date of attendance, which can differ from the transition timestamp."}, "inspectorNotes": {"type": "string", "title": "Inspector''s Notes", "$comment": "FREE TEXT — renders as a textarea. Bounded so a pasted report cannot bloat the JSONB row.", "maxLength": 2000}, "nonConformities": {"type": "array", "items": {"enum": ["HYGIENE", "PEST_CONTROL", "TEMPERATURE_CONTROL", "LABELLING", "WATER_QUALITY", "STAFF_TRAINING", "RECORD_KEEPING"], "type": "string"}, "title": "Non-Conformities Found", "$comment": "MULTI-CHOICE ENUM ARRAY with uniqueItems — renders as a multiselect. An array, so it can never appear on a rendered document; that is fine, a checklist is not printed.", "maxItems": 7, "uniqueItems": true}, "inspectionPassed": {"type": "boolean", "title": "Inspection Passed", "$comment": "BOOLEAN — renders as a checkbox."}, "correctiveActionDueBy": {"type": "string", "title": "Corrective Action Due By", "format": "date", "$comment": "CONDITIONALLY-REQUIRED DATE — required only when riskRating is HIGH, via the if/then below. Proof that the same conditional vocabulary the application form uses is available on a checklist, because both go through CertificateDetailValidator."}}}', 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788439834471, 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788439834471);
INSERT INTO "BASETENANT".tenant_configs (id, tenant_id, vc_provider, algorithm, status, created_by, created_at, updated_by, updated_at) VALUES ('dc74e635-1573-48fb-8ade-491ac3b34d27', 'BASETENANT', 'WALT', 'EdDSA', 'ACTIVE', 'e2df874c-b93e-42d3-82cf-d5452f4af31a', '2026-08-31 05:25:22.33572+00', 'system', '2026-08-31 06:57:52.476923+00');
INSERT INTO "BASETENANT".ui_config (id, module_code, entity_code, channel, schema_id, config_body, created_by, created_time, modified_by, modified_time) VALUES ('1cb51460-fc68-4fe0-bfbd-8c37e0f4d1c3', 'certificate', 'FIRE_NOC.form.001f7632-d809-4b15-99ec-b40234320c27', 'web', '9bf98f55-ae3f-4174-b5cf-89b1cf904d3d', '{"type": "Categorization", "elements": [{"type": "Category", "label": "Property Details", "options": {"stepId": "step-2-property-details"}, "elements": [{"type": "Category", "label": "Property Details", "options": {}, "elements": [{"type": "VerticalLayout", "elements": [{"type": "Control", "label": "No. of Buildings", "scope": "#/properties/numberOfBuildings", "options": {"widget": "select"}}, {"type": "Control", "label": "No. of Floors", "scope": "#/properties/numberOfFloors", "options": {"widget": "text"}}, {"type": "Control", "label": "No. of Basements", "scope": "#/properties/numberOfBasements", "options": {"widget": "text"}}, {"type": "Control", "label": "Plot Size (sq ft)", "scope": "#/properties/plotSizeSqFt", "options": {"widget": "text"}}, {"type": "Control", "label": "Ground Floor Built-up Area (sq m)", "scope": "#/properties/groundFloorBuiltUpAreaSqm", "options": {"widget": "text"}}, {"type": "Control", "label": "Height of Building from Ground Level (m)", "scope": "#/properties/heightOfBuildingMeters", "options": {"widget": "text"}}]}]}, {"type": "Category", "label": "Property Location", "options": {}, "elements": [{"type": "VerticalLayout", "elements": [{"type": "Control", "label": "Property ID", "scope": "#/properties/propertyId", "options": {"widget": "text"}}, {"type": "Control", "label": "Applicable Fire Station", "scope": "#/properties/applicableFireStation", "options": {"widget": "text"}}, {"type": "Control", "label": "House No.", "scope": "#/properties/houseNo", "options": {"widget": "text"}}, {"type": "Control", "label": "Street Name", "scope": "#/properties/streetName", "options": {"widget": "text"}}]}]}]}]}', 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788153866327, 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788153866327);
INSERT INTO "BASETENANT".ui_config (id, module_code, entity_code, channel, schema_id, config_body, created_by, created_time, modified_by, modified_time) VALUES ('4886baa3-f881-422e-977b-11f0eade923d', 'certificate', 'FIRE_NOC.checklist.e076c464-ef1b-4ff0-929e-ae5570bdce88', 'web', '2d30d864-ac55-4da2-a126-aa4a0efe73c0', '{"type": "Categorization", "elements": [{"type": "Category", "label": "Fire Safety Inspection", "options": {"stepId": "fire-safety-inspection"}, "elements": [{"type": "VerticalLayout", "elements": [{"type": "Control", "label": "Site visited", "scope": "#/properties/siteVisited", "options": {"widget": "checkbox"}}, {"type": "Control", "label": "Building exists at location", "scope": "#/properties/buildingExists", "options": {"widget": "radio"}}, {"type": "Control", "label": "Fire safety equipment installed", "scope": "#/properties/fireSafetyEquipmentInstalled", "options": {"widget": "radio"}}, {"type": "Control", "label": "Fire escape routes accessible", "scope": "#/properties/fireEscapeRoutesAccessible", "options": {"widget": "radio"}}, {"type": "Control", "label": "Fire-fighting systems functional", "scope": "#/properties/fireFightingSystemsFunctional", "options": {"widget": "radio"}}, {"type": "Control", "label": "Building plan matches site", "scope": "#/properties/buildingPlanMatchesSite", "options": {"widget": "radio"}}, {"type": "Control", "label": "Site photos", "scope": "#/properties/sitePhotos", "options": {"accept": ["image/*", "application/pdf"], "widget": "file", "multiple": true}}, {"type": "Control", "label": "Inspection remarks", "scope": "#/properties/inspectionRemarks", "options": {"widget": "textarea"}}]}]}]}', 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788153867221, 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788153867221);
INSERT INTO "BASETENANT".ui_config (id, module_code, entity_code, channel, schema_id, config_body, created_by, created_time, modified_by, modified_time) VALUES ('ca1f77a6-029b-4385-a0c5-c45ec8018205', 'certificate', 'BUSINESS_LICENSE.form.6816e8d7-afca-42cb-985a-fe81af720ba4', 'web', 'b2613fb2-da10-4250-9ea5-cc621597e45b', '{"type": "Categorization", "elements": [{"type": "Category", "label": "Business Details", "options": {"stepId": "step-1-business-details"}, "elements": [{"type": "Category", "label": "Business Details", "options": {}, "elements": [{"type": "VerticalLayout", "elements": [{"type": "Control", "label": "Business Name", "scope": "#/properties/businessName", "options": {"widget": "text", "placeholder": "e.g. Anita''s General Store"}}, {"type": "Control", "label": "Ownership Type", "scope": "#/properties/ownershipType", "options": {"widget": "select"}}, {"type": "Control", "label": "Number of Employees", "scope": "#/properties/numberOfEmployees", "options": {"widget": "text", "placeholder": "e.g. 5"}}, {"type": "Control", "label": "Annual Turnover", "scope": "#/properties/annualTurnover", "options": {"widget": "text", "placeholder": "e.g. 500000"}}]}]}, {"type": "Category", "label": "Operational Details", "options": {}, "elements": [{"type": "VerticalLayout", "elements": [{"type": "Control", "label": "Business Registration Date", "scope": "#/properties/businessRegistrationDate", "options": {"widget": "text"}}]}]}]}]}', 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788153957918, 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788153957918);
INSERT INTO "BASETENANT".ui_config (id, module_code, entity_code, channel, schema_id, config_body, created_by, created_time, modified_by, modified_time) VALUES ('8e753292-453a-4532-9459-b935e6650eda', 'certificate', 'BUSINESS_LICENSE.checklist.8073cfc7-1849-4bf8-b115-f3035351fb59', 'web', '6820c8d1-a695-4ba8-94bd-2a446bb615da', '{"type": "Categorization", "elements": [{"type": "Category", "label": "Business Verification", "options": {"stepId": "business-verification"}, "elements": [{"type": "VerticalLayout", "elements": [{"type": "Control", "label": "Business exists at the mentioned address", "scope": "#/properties/businessExists", "options": {"widget": "checkbox"}}, {"type": "Control", "label": "Business name displayed on premises matches application", "scope": "#/properties/businessNameMatches", "options": {"widget": "checkbox"}}, {"type": "Control", "label": "Nature of business matches application", "scope": "#/properties/natureOfBusinessMatches", "options": {"widget": "checkbox"}}, {"type": "Control", "label": "Business is currently operational", "scope": "#/properties/businessOperational", "options": {"widget": "checkbox"}}, {"type": "Control", "label": "Upload Business Photo", "scope": "#/properties/businessPhoto", "options": {"accept": ["image/*"], "widget": "file", "multiple": true}}]}]}]}', 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788153958327, 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788153958327);
INSERT INTO "BASETENANT".ui_config (id, module_code, entity_code, channel, schema_id, config_body, created_by, created_time, modified_by, modified_time) VALUES ('d7454cb9-07c2-47be-9038-fd30d377e446', 'certificate', 'LEARNER_LICENSE.form.b5a00577-ea80-491f-9666-b2f5e45f5d87', 'web', '44454846-f714-4c3b-92ba-9fdedd9638b6', '{"type": "Categorization", "elements": [{"type": "Category", "label": "Learner''s Licence Details", "options": {"stepId": "step-2-learner-details"}, "elements": [{"type": "Category", "label": "Licence Details", "options": {}, "elements": [{"type": "VerticalLayout", "elements": [{"type": "Control", "label": "Application Type", "scope": "#/properties/applicationType", "options": {"widget": "select"}}, {"type": "Control", "label": "Class of Vehicle", "scope": "#/properties/vehicleClass", "options": {"widget": "cascading_dropdown", "categories": [{"code": "nontransport", "name": "Non-Transport", "children": [{"code": "nontransport.mcwog", "name": "Motorcycle without Gear (MCWOG)"}, {"code": "nontransport.mcwg", "name": "Motorcycle with Gear (MCWG)"}, {"code": "nontransport.lmv", "name": "Light Motor Vehicle (LMV)"}, {"code": "nontransport.tractor", "name": "Tractor"}, {"code": "nontransport.invalidcarriage", "name": "Invalid Carriage"}]}, {"code": "transport", "name": "Transport", "children": [{"code": "transport.lmvtr", "name": "Light Motor Vehicle - Transport (LMV-TR)"}, {"code": "transport.hgmv", "name": "Heavy Goods Motor Vehicle (HGMV)"}, {"code": "transport.hpmv", "name": "Heavy Passenger Motor Vehicle (HPMV)"}, {"code": "transport.hazardous", "name": "Hazardous Goods Carrier"}, {"code": "transport.trailer", "name": "Trailer"}]}], "levelLabels": ["Vehicle Class Group", "Vehicle Class"]}}, {"type": "Control", "label": "Date of Birth", "scope": "#/properties/dateOfBirth", "options": {"widget": "date"}}, {"type": "Control", "label": "Blood Group", "scope": "#/properties/bloodGroup", "options": {"widget": "select"}}]}]}, {"type": "Category", "label": "Existing Learner''s Licence", "options": {}, "elements": [{"type": "VerticalLayout", "elements": [{"rule": {"effect": "HIDE", "condition": {"scope": "#/properties/applicationType", "schema": {"const": "FRESH"}}}, "type": "Control", "_note": "Shown for the two application types filed against a learner''s licence the applicant already holds, and required for them by the `else` branch of the schema''s first allOf block. Written as HIDE-on-FRESH rather than SHOW-on-enum[ADDITIONAL_CLASS,DUPLICATE] — see LEARNER_LICENSE_ui_schema.json in the source bundle''s own note on why an enum condition here would silently misbehave in isElementVisible.", "label": "Existing Learner''s Licence Number", "scope": "#/properties/existingLearnerLicenceNumber", "options": {"widget": "text"}}]}]}, {"type": "Category", "label": "Guardian Consent (applicants under 18)", "options": {}, "elements": [{"type": "VerticalLayout", "elements": [{"type": "Control", "_note": "Always shown rather than gated on age: ''dateOfBirth is less than 18 years before today'' is not expressible as a jsonforms rule condition. An applicant over 18 leaves both fields alone.", "label": "A parent or guardian has consented to this application", "scope": "#/properties/guardianConsentProvided", "options": {"widget": "checkbox"}}, {"rule": {"effect": "SHOW", "condition": {"scope": "#/properties/guardianConsentProvided", "schema": {"const": true}}}, "type": "Control", "label": "Name of Parent or Guardian", "scope": "#/properties/guardianName", "options": {"widget": "text"}}]}]}, {"type": "Category", "label": "Medical Fitness", "options": {}, "elements": [{"type": "VerticalLayout", "elements": [{"type": "Control", "label": "Medical Certificate Number (Form 1A)", "scope": "#/properties/medicalCertificateNumber", "options": {"widget": "text"}}]}]}, {"type": "Category", "label": "Details Printed on the Licence", "options": {}, "elements": [{"type": "VerticalLayout", "elements": [{"type": "Control", "label": "Identification Marks", "scope": "#/properties/identificationMarks", "options": {"rows": 2, "widget": "textarea"}}, {"type": "Control", "label": "Emergency Contact Name", "scope": "#/properties/emergencyContactName", "options": {"widget": "text"}}, {"type": "Control", "label": "Emergency Contact Number", "scope": "#/properties/emergencyContactNumber", "options": {"widget": "text"}}]}]}]}]}', 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788241050887, 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788241050887);
