INSERT INTO "BASETENANT".ui_config (id, module_code, entity_code, channel, schema_id, config_body, created_by, created_time, modified_by, modified_time) VALUES ('2e6a6ae4-2370-4bc0-947e-c7d11fe91608', 'certificate', 'DRIVING_LICENSE.checklist.fef7a534-4fd7-49de-b882-615a34612a44', 'web', 'e6c1d451-2ceb-49c6-8e7d-97bfc887a54c', '{"type": "Categorization", "elements": [{"type": "Category", "label": "Driving Test", "options": {"stepId": "driving-test"}, "elements": [{"type": "VerticalLayout", "elements": [{"type": "Control", "label": "Test was conducted", "scope": "#/properties/testConducted", "options": {"widget": "checkbox"}}, {"type": "Control", "label": "Identity verified at the test centre", "scope": "#/properties/identityVerifiedAtCentre", "options": {"widget": "radio"}}, {"type": "Control", "label": "Eyesight Test Result", "scope": "#/properties/eyesightTestResult", "options": {"widget": "radio"}}, {"type": "Control", "label": "Practical Test Result", "scope": "#/properties/practicalTestResult", "options": {"widget": "radio"}}, {"type": "Control", "label": "Vehicle Used for the Test", "scope": "#/properties/vehicleUsedForTest", "options": {"widget": "text"}}, {"type": "Control", "label": "Test Track Code", "scope": "#/properties/testTrackCode", "options": {"widget": "text"}}, {"type": "Control", "label": "Test Photographs", "scope": "#/properties/testPhotos", "options": {"accept": ["image/*", "application/pdf"], "widget": "file", "multiple": true}}, {"type": "Control", "label": "Examiner''s Remarks", "scope": "#/properties/examinerRemarks", "options": {"widget": "textarea"}}]}]}]}', 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788277727157, 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788277727157);
INSERT INTO "BASETENANT".ui_config (id, module_code, entity_code, channel, schema_id, config_body, created_by, created_time, modified_by, modified_time) VALUES ('34a0b7d8-77f0-4d32-81f9-e97be5da017b', 'certificate', 'FOOD_LICENSE.form.3136481e-e525-47e3-862e-f12b9b8967c0', 'web', 'd33af063-1945-49ef-92b9-851d28e85df8', '{"type": "Categorization", "elements": [{"type": "Category", "label": "Licence Details", "options": {"stepId": "step-2-licence-details"}, "elements": [{"type": "Category", "label": "Authorisation and Activity", "options": {}, "elements": [{"type": "VerticalLayout", "elements": [{"type": "Control", "label": "Application Type", "scope": "#/properties/applicationType", "options": {"widget": "select"}}, {"type": "Control", "_note": "Constrained server-side: handlesAnimalOrigin true forces APPROVAL, and turnover above the ceiling rules out REGISTRATION. Both are allOf blocks in the schema, so the UI cannot be the only thing enforcing them.", "label": "Authorisation Class", "scope": "#/properties/licenceClass", "options": {"widget": "radio"}}, {"type": "Control", "_note": "Set from the first segment of the cascading selection below. Its own field because ACTIVITY_FEE matches it with equals and the condition grammar has no prefix operator.", "label": "Activity Group", "scope": "#/properties/activityGroup", "options": {"widget": "select"}}, {"type": "Control", "label": "Activity", "scope": "#/properties/activityPath", "options": {"widget": "cascading_dropdown", "categories": [{"code": "manufacturing", "name": "Manufacturing and Processing", "children": [{"code": "manufacturing.processing", "name": "General Food Processing"}, {"code": "manufacturing.dairy", "name": "Dairy Processing"}, {"code": "manufacturing.meat", "name": "Meat, Poultry and Fish Processing"}]}, {"code": "retail", "name": "Retail", "children": [{"code": "retail.shop", "name": "Food Shop"}, {"code": "retail.market", "name": "Market Stall"}]}, {"code": "foodservice", "name": "Food Service", "children": [{"code": "foodservice.restaurant", "name": "Restaurant"}, {"code": "foodservice.catering", "name": "Catering"}, {"code": "foodservice.institutional", "name": "Institutional Kitchen"}]}, {"code": "logistics", "name": "Storage and Transport", "children": [{"code": "logistics.storage", "name": "Storage and Warehousing"}, {"code": "logistics.transport", "name": "Food Transport"}]}, {"code": "trade", "name": "Trade", "children": [{"code": "trade.import", "name": "Import and Export"}, {"code": "trade.wholesale", "name": "Wholesale and Distribution"}]}], "levelLabels": ["Activity Group", "Activity"]}}, {"type": "Control", "_note": "The PER_UNIT multiplier on the licence fee. NOT the field that stamps validUntil — that is the envelope''s requestedValidityDays, which the calculator cannot see.", "label": "Licence Term (Years)", "scope": "#/properties/licenceTermYears", "options": {"max": 5, "min": 1, "widget": "number"}}]}]}, {"type": "Category", "label": "Scale and Risk", "options": {}, "elements": [{"type": "VerticalLayout", "elements": [{"type": "Control", "_note": "Whole currency units. The licence-fee band; integer so adjacent bands need no epsilon.", "label": "Annual Turnover", "scope": "#/properties/annualTurnover", "options": {"min": 0, "step": 1, "widget": "number"}}, {"type": "Control", "_note": "Drives the SLAB inspection fee — a genuinely marginal rate, unlike the banded licence fee.", "label": "Premises Area (sq m)", "scope": "#/properties/premisesAreaSqm", "options": {"min": 0, "widget": "number"}}, {"type": "Control", "label": "Handles Product of Animal Origin", "scope": "#/properties/handlesAnimalOrigin", "options": {"widget": "checkbox"}}, {"type": "Control", "label": "Product Categories", "scope": "#/properties/productCategories", "options": {"widget": "multiselect"}}]}]}, {"type": "Category", "label": "Food Safety Compliance", "options": {}, "elements": [{"type": "VerticalLayout", "elements": [{"rule": {"effect": "SHOW", "condition": {"scope": "#/properties/licenceClass", "schema": {"enum": ["STANDARD", "APPROVAL"]}}}, "type": "Control", "_note": "Required for APPROVAL. Its mere presence also earns the HACCP rebate, so it is shown for STANDARD too.", "label": "HACCP Plan Reference", "scope": "#/properties/haccpPlanRef", "options": {"widget": "text", "placeholder": "HACCP-XXXX"}}]}]}, {"type": "Category", "label": "Previous Licence", "options": {}, "elements": [{"type": "VerticalLayout", "elements": [{"rule": {"effect": "SHOW", "condition": {"scope": "#/properties/applicationType", "schema": {"enum": ["RENEWAL", "VARIATION", "DUPLICATE"]}}}, "type": "Control", "_note": "Required for everything except NEW, and FORBIDDEN for NEW — the schema''s if/then/else enforces both directions.", "label": "Previous Licence Number", "scope": "#/properties/previousLicenceNumber", "options": {"widget": "text"}}, {"rule": {"effect": "SHOW", "condition": {"scope": "#/properties/applicationType", "schema": {"const": "RENEWAL"}}}, "type": "Control", "_note": "Frontend-computed from the expiring licence''s validUntil; the engine cannot do date arithmetic. Bands the penalty and the interest rules.", "label": "Days Since Expiry", "scope": "#/properties/daysSinceExpiry", "options": {"widget": "number", "readOnly": true}}]}]}, {"type": "Category", "label": "Premises and Outlets", "options": {}, "elements": [{"type": "VerticalLayout", "elements": [{"type": "Control", "_note": "Optional, except for logistics. Each element is priced separately by the SUBENTITY rule and summed by the AGGREGATION rule; an absent array yields no line items and a derived staff total of 0.", "label": "Outlets", "scope": "#/properties/outlets", "options": {"detail": {"highRisk": {"widget": "checkbox"}, "openedOn": {"widget": "date"}, "outletCode": {"widget": "text"}, "staffCount": {"widget": "number"}}, "widget": "array"}}]}]}]}]}', 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788277744237, 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788277744237);
INSERT INTO "BASETENANT".ui_config (id, module_code, entity_code, channel, schema_id, config_body, created_by, created_time, modified_by, modified_time) VALUES ('07daef54-2c66-427d-9a20-d7fcd7d43090', 'certificate', 'FOOD_LICENSE.checklist.e504a163-a165-4ab6-a479-60a5913be4cc', 'web', 'faad78fc-4006-49e3-9fca-bb295b340b13', '{"type": "Categorization", "elements": [{"type": "Category", "label": "Food Safety Inspection", "options": {"stepId": "food-safety-inspection"}, "elements": [{"type": "VerticalLayout", "elements": [{"type": "Control", "label": "Inspection Passed", "scope": "#/properties/inspectionPassed", "options": {"widget": "checkbox"}}, {"type": "Control", "label": "Date of Inspection", "scope": "#/properties/inspectionDate", "options": {"widget": "date"}}, {"type": "Control", "label": "Risk Rating", "scope": "#/properties/riskRating", "options": {"widget": "radio"}}, {"type": "Control", "label": "Hygiene Score (0-100)", "scope": "#/properties/hygieneScore", "options": {"max": 100, "min": 0, "step": 5, "widget": "number"}}, {"type": "Control", "label": "Non-Conformities Found", "scope": "#/properties/nonConformities", "options": {"widget": "multiselect"}}, {"type": "Control", "label": "Evidence Photographs", "scope": "#/properties/evidencePhotos", "options": {"accept": ["image/*", "application/pdf"], "widget": "file", "multiple": true}}, {"type": "Control", "label": "Inspector''s Notes", "scope": "#/properties/inspectorNotes", "options": {"rows": 4, "widget": "textarea"}}, {"rule": {"effect": "SHOW", "condition": {"scope": "#/properties/riskRating", "schema": {"const": "HIGH"}}}, "type": "Control", "_note": "Required by the checklist schema''s own if/then when riskRating is HIGH. The UI rule only hides it; the validator is what enforces it.", "label": "Corrective Action Due By", "scope": "#/properties/correctiveActionDueBy", "options": {"widget": "date"}}]}]}]}', 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788277744742, 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788277744742);
INSERT INTO "BASETENANT".ui_config (id, module_code, entity_code, channel, schema_id, config_body, created_by, created_time, modified_by, modified_time) VALUES ('b60a933e-c8f6-4419-a7fb-4fa78e7183d3', 'certificate', 'LEARNER_LICENSE.form.b5a00577-ea80-491f-9666-b2f5e45f5d87', 'web', 'ee628e3c-05fc-431d-9c78-c2087c4765a8', '{"type": "Categorization", "elements": [{"type": "Category", "label": "category.learnerDetailsStep", "options": {"stepId": "step-2-learner-details"}, "elements": [{"type": "Category", "label": "category.licenceDetails", "options": {}, "elements": [{"type": "VerticalLayout", "elements": [{"type": "Control", "label": "applicationType", "scope": "#/properties/applicationType", "options": {"widget": "select"}}, {"type": "Control", "label": "vehicleClass", "scope": "#/properties/vehicleClass", "options": {"widget": "cascading_dropdown", "categories": [{"code": "nontransport", "name": "Non-Transport", "children": [{"code": "nontransport.mcwog", "name": "Motorcycle without Gear (MCWOG)"}, {"code": "nontransport.mcwg", "name": "Motorcycle with Gear (MCWG)"}, {"code": "nontransport.lmv", "name": "Light Motor Vehicle (LMV)"}, {"code": "nontransport.tractor", "name": "Tractor"}, {"code": "nontransport.invalidcarriage", "name": "Invalid Carriage"}]}, {"code": "transport", "name": "Transport", "children": [{"code": "transport.lmvtr", "name": "Light Motor Vehicle - Transport (LMV-TR)"}, {"code": "transport.hgmv", "name": "Heavy Goods Motor Vehicle (HGMV)"}, {"code": "transport.hpmv", "name": "Heavy Passenger Motor Vehicle (HPMV)"}, {"code": "transport.hazardous", "name": "Hazardous Goods Carrier"}, {"code": "transport.trailer", "name": "Trailer"}]}], "levelLabels": ["Vehicle Class Group", "Vehicle Class"]}}, {"type": "Control", "label": "dateOfBirth", "scope": "#/properties/dateOfBirth", "options": {"widget": "date"}}, {"type": "Control", "label": "bloodGroup", "scope": "#/properties/bloodGroup", "options": {"widget": "select"}}]}]}, {"type": "Category", "label": "category.existingLearnerLicence", "options": {}, "elements": [{"type": "VerticalLayout", "elements": [{"rule": {"effect": "HIDE", "condition": {"scope": "#/properties/applicationType", "schema": {"const": "FRESH"}}}, "type": "Control", "_note": "Shown for the two application types filed against a learner''s licence the applicant already holds, and required for them by the `else` branch of the schema''s first allOf block — visibility and requiredness have to agree, because the wizard''s sub-screen Next gating does not exempt rule-hidden controls from validation. Written as HIDE-on-FRESH rather than the more obvious SHOW-on-enum[ADDITIONAL_CLASS,DUPLICATE] for a reason that is not cosmetic: @jsonforms/core evaluates either form correctly while the citizen is filling the form, but isElementVisible (packages/shared/src/utils/jsonforms-rule.ts) reads only `const` off condition.schema and compares it with ===, so an `enum` condition resolves to ''no value matches'' and the row silently disappears from everything that util drives — the Confirm step''s summary and buildDynamicDetailSections, i.e. the employee''s application-detail view. The officer would have been unable to see the licence number on precisely the applications that require it. HIDE + const is the complement of the same set and evaluates identically in both engines.", "label": "existingLearnerLicenceNumber", "scope": "#/properties/existingLearnerLicenceNumber", "options": {"widget": "text"}}]}]}, {"type": "Category", "label": "category.guardianConsent", "options": {}, "elements": [{"type": "VerticalLayout", "elements": [{"type": "Control", "_note": "Always shown rather than gated on age: jsonforms rules resolve against form data with the same equals/enum grammar the calculator has, and ''dateOfBirth is less than 18 years before today'' is not expressible as a condition. An applicant over 18 leaves both fields alone.", "label": "guardianConsentProvided", "scope": "#/properties/guardianConsentProvided", "options": {"widget": "checkbox"}}, {"rule": {"effect": "SHOW", "condition": {"scope": "#/properties/guardianConsentProvided", "schema": {"const": true}}}, "type": "Control", "label": "guardianName", "scope": "#/properties/guardianName", "options": {"widget": "text"}}]}]}, {"type": "Category", "label": "category.medicalFitness", "options": {}, "elements": [{"type": "VerticalLayout", "elements": [{"type": "Control", "label": "medicalCertificateNumber", "scope": "#/properties/medicalCertificateNumber", "options": {"widget": "text"}}]}]}, {"type": "Category", "label": "category.licenceFaceDetails", "options": {}, "elements": [{"type": "VerticalLayout", "elements": [{"type": "Control", "label": "identificationMarks", "scope": "#/properties/identificationMarks", "options": {"rows": 2, "widget": "textarea"}}, {"type": "Control", "label": "emergencyContactName", "scope": "#/properties/emergencyContactName", "options": {"widget": "text"}}, {"type": "Control", "label": "emergencyContactNumber", "scope": "#/properties/emergencyContactNumber", "options": {"widget": "text"}}]}]}]}]}', 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788283089882, 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788283089882);
INSERT INTO "BASETENANT".ui_config (id, module_code, entity_code, channel, schema_id, config_body, created_by, created_time, modified_by, modified_time) VALUES ('a45da520-2859-491c-b22e-7c2b8eae3dcf', 'certificate', 'LEARNER_LICENSE.checklist.59ddb7cd-c745-4a97-90c5-247da42e2ea4', 'web', 'ea95b3cd-5f6a-4189-8329-d77269117f61', '{"type": "Categorization", "elements": [{"type": "Category", "label": "category.theoryTest", "options": {"stepId": "theory-test"}, "elements": [{"type": "VerticalLayout", "elements": [{"type": "Control", "label": "testConducted", "scope": "#/properties/testConducted", "options": {"widget": "checkbox"}}, {"type": "Control", "label": "identityVerifiedAtCentre", "scope": "#/properties/identityVerifiedAtCentre", "options": {"widget": "radio"}}, {"type": "Control", "label": "eyesightTestResult", "scope": "#/properties/eyesightTestResult", "options": {"widget": "radio"}}, {"type": "Control", "label": "testMode", "scope": "#/properties/testMode", "options": {"widget": "select"}}, {"type": "Control", "label": "testCentreCode", "scope": "#/properties/testCentreCode", "options": {"widget": "text"}}, {"type": "Control", "_note": "Required, and 0 is a legal value — an ABSENT candidate is recorded as 0 rather than left blank, because the schema requires the field and there is no null.", "label": "theoryTestScore", "scope": "#/properties/theoryTestScore", "options": {"widget": "number"}}, {"type": "Control", "label": "theoryTestResult", "scope": "#/properties/theoryTestResult", "options": {"widget": "radio"}}, {"type": "Control", "label": "examinerRemarks", "scope": "#/properties/examinerRemarks", "options": {"widget": "textarea"}}]}]}]}', 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788283090783, 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788283090783);
INSERT INTO "BASETENANT".ui_config (id, module_code, entity_code, channel, schema_id, config_body, created_by, created_time, modified_by, modified_time) VALUES ('61256c2d-1dc0-409c-93dd-967dcae4d5bc', 'certificate', 'FOOD_LICENSE.form.3136481e-e525-47e3-862e-f12b9b8967c0', 'web', 'a29894da-105a-4a6f-99f5-e16d619ede9f', '{"type": "Categorization", "elements": [{"type": "Category", "label": "category.licenceDetailsStep", "options": {"stepId": "step-2-licence-details"}, "elements": [{"type": "Category", "label": "category.licenceScope", "options": {}, "elements": [{"type": "VerticalLayout", "elements": [{"type": "Control", "label": "applicationType", "scope": "#/properties/applicationType", "options": {"widget": "select"}}, {"type": "Control", "_note": "Constrained server-side: handlesAnimalOrigin true forces APPROVAL, and turnover above the ceiling rules out REGISTRATION. Both are allOf blocks in the schema, so the UI cannot be the only thing enforcing them.", "label": "licenceClass", "scope": "#/properties/licenceClass", "options": {"widget": "radio"}}, {"type": "Control", "_note": "Set from the first segment of the cascading selection below. Its own field because ACTIVITY_FEE matches it with equals and the condition grammar has no prefix operator.", "label": "activityGroup", "scope": "#/properties/activityGroup", "options": {"widget": "select"}}, {"type": "Control", "label": "activityPath", "scope": "#/properties/activityPath", "options": {"widget": "cascading_dropdown", "categories": [{"code": "manufacturing", "name": "Manufacturing and Processing", "children": [{"code": "manufacturing.processing", "name": "General Food Processing"}, {"code": "manufacturing.dairy", "name": "Dairy Processing"}, {"code": "manufacturing.meat", "name": "Meat, Poultry and Fish Processing"}]}, {"code": "retail", "name": "Retail", "children": [{"code": "retail.shop", "name": "Food Shop"}, {"code": "retail.market", "name": "Market Stall"}]}, {"code": "foodservice", "name": "Food Service", "children": [{"code": "foodservice.restaurant", "name": "Restaurant"}, {"code": "foodservice.catering", "name": "Catering"}, {"code": "foodservice.institutional", "name": "Institutional Kitchen"}]}, {"code": "logistics", "name": "Storage and Transport", "children": [{"code": "logistics.storage", "name": "Storage and Warehousing"}, {"code": "logistics.transport", "name": "Food Transport"}]}, {"code": "trade", "name": "Trade", "children": [{"code": "trade.import", "name": "Import and Export"}, {"code": "trade.wholesale", "name": "Wholesale and Distribution"}]}], "levelLabels": ["Activity Group", "Activity"]}}, {"type": "Control", "_note": "The PER_UNIT multiplier on the licence fee. NOT the field that stamps validUntil — that is the envelope''s requestedValidityDays, which the calculator cannot see.", "label": "licenceTermYears", "scope": "#/properties/licenceTermYears", "options": {"max": 5, "min": 1, "widget": "number"}}]}]}, {"type": "Category", "label": "category.scaleAndRisk", "options": {}, "elements": [{"type": "VerticalLayout", "elements": [{"type": "Control", "_note": "Whole currency units. The licence-fee band; integer so adjacent bands need no epsilon.", "label": "annualTurnover", "scope": "#/properties/annualTurnover", "options": {"min": 0, "step": 1, "widget": "number"}}, {"type": "Control", "_note": "Drives the SLAB inspection fee — a genuinely marginal rate, unlike the banded licence fee.", "label": "premisesAreaSqm", "scope": "#/properties/premisesAreaSqm", "options": {"min": 0, "widget": "number"}}, {"type": "Control", "label": "handlesAnimalOrigin", "scope": "#/properties/handlesAnimalOrigin", "options": {"widget": "checkbox"}}, {"type": "Control", "label": "productCategories", "scope": "#/properties/productCategories", "options": {"widget": "multiselect"}}]}]}, {"type": "Category", "label": "category.compliance", "options": {}, "elements": [{"type": "VerticalLayout", "elements": [{"rule": {"effect": "SHOW", "condition": {"scope": "#/properties/licenceClass", "schema": {"enum": ["STANDARD", "APPROVAL"]}}}, "type": "Control", "_note": "Required for APPROVAL. Its mere presence also earns the HACCP rebate, so it is shown for STANDARD too.", "label": "haccpPlanRef", "scope": "#/properties/haccpPlanRef", "options": {"widget": "text", "placeholder": "HACCP-XXXX"}}]}]}, {"type": "Category", "label": "category.previousLicence", "options": {}, "elements": [{"type": "VerticalLayout", "elements": [{"rule": {"effect": "SHOW", "condition": {"scope": "#/properties/applicationType", "schema": {"enum": ["RENEWAL", "VARIATION", "DUPLICATE"]}}}, "type": "Control", "_note": "Required for everything except NEW, and FORBIDDEN for NEW — the schema''s if/then/else enforces both directions.", "label": "previousLicenceNumber", "scope": "#/properties/previousLicenceNumber", "options": {"widget": "text"}}, {"rule": {"effect": "SHOW", "condition": {"scope": "#/properties/applicationType", "schema": {"const": "RENEWAL"}}}, "type": "Control", "_note": "Frontend-computed from the expiring licence''s validUntil; the engine cannot do date arithmetic. Bands the penalty and the interest rules.", "label": "daysSinceExpiry", "scope": "#/properties/daysSinceExpiry", "options": {"widget": "number", "readOnly": true}}]}]}, {"type": "Category", "label": "category.outlets", "options": {}, "elements": [{"type": "VerticalLayout", "elements": [{"type": "Control", "_note": "Optional, except for logistics. Each element is priced separately by the SUBENTITY rule and summed by the AGGREGATION rule; an absent array yields no line items and a derived staff total of 0.", "label": "outlets", "scope": "#/properties/outlets", "options": {"detail": {"highRisk": {"widget": "checkbox"}, "openedOn": {"widget": "date"}, "outletCode": {"widget": "text"}, "staffCount": {"widget": "number"}}, "widget": "array"}}]}]}]}]}', 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788283170279, 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788283170279);
INSERT INTO "BASETENANT".ui_config (id, module_code, entity_code, channel, schema_id, config_body, created_by, created_time, modified_by, modified_time) VALUES ('f0fb91a5-bf70-46da-9b77-1ccb4ddbd1e7', 'certificate', 'DRIVING_LICENSE.form.1594690b-b1cf-4677-b0a3-de4e8a4c5925', 'web', '010f0000-a052-4f60-85c7-adc4c1f2c248', '{"type": "Categorization", "elements": [{"type": "Category", "label": "Licence Details", "options": {"stepId": "step-2-licence-details"}, "elements": [{"type": "Category", "label": "Licence Applied For", "options": {}, "elements": [{"type": "VerticalLayout", "elements": [{"type": "Control", "label": "Application Type", "scope": "#/properties/applicationType", "options": {"widget": "select"}}, {"type": "Control", "label": "Class of Vehicle", "scope": "#/properties/vehicleClass", "options": {"widget": "cascading_dropdown", "categories": [{"code": "nontransport", "name": "Non-Transport", "children": [{"code": "nontransport.mcwog", "name": "Motorcycle without Gear (MCWOG)"}, {"code": "nontransport.mcwg", "name": "Motorcycle with Gear (MCWG)"}, {"code": "nontransport.lmv", "name": "Light Motor Vehicle (LMV)"}, {"code": "nontransport.tractor", "name": "Tractor"}, {"code": "nontransport.invalidcarriage", "name": "Invalid Carriage"}]}, {"code": "transport", "name": "Transport", "children": [{"code": "transport.lmvtr", "name": "Light Motor Vehicle - Transport (LMV-TR)"}, {"code": "transport.hgmv", "name": "Heavy Goods Motor Vehicle (HGMV)"}, {"code": "transport.hpmv", "name": "Heavy Passenger Motor Vehicle (HPMV)"}, {"code": "transport.hazardous", "name": "Hazardous Goods Carrier"}, {"code": "transport.trailer", "name": "Trailer"}]}], "levelLabels": ["Vehicle Class Group", "Vehicle Class"]}}, {"type": "Control", "label": "Date of Birth", "scope": "#/properties/dateOfBirth", "options": {"widget": "date"}}, {"type": "Control", "label": "Blood Group", "scope": "#/properties/bloodGroup", "options": {"widget": "select"}}]}]}, {"type": "Category", "label": "Existing Licence", "options": {}, "elements": [{"type": "VerticalLayout", "elements": [{"rule": {"effect": "SHOW", "condition": {"scope": "#/properties/applicationType", "schema": {"const": "PERMANENT"}}}, "type": "Control", "_note": "Shown only for a permanent-licence application — the learner''s licence is its statutory precondition, and the learner''s licence itself is the separate LEARNER_LICENSE certificate type. jsonforms resolves rule.condition.scope against the form data, independently of the JSON Schema''s own required[]; the schema deliberately leaves this optional so a RENEWAL/DUPLICATE/INTERNATIONAL application validates without it.", "label": "Learner''s Licence Number", "scope": "#/properties/learnerLicenceNumber", "options": {"widget": "text"}}, {"rule": {"effect": "SHOW", "condition": {"scope": "#/properties/applicationType", "schema": {"enum": ["RENEWAL", "DUPLICATE", "INTERNATIONAL"]}}}, "type": "Control", "_note": "Shown for every application filed against a licence the applicant already holds.", "label": "Existing Licence Number", "scope": "#/properties/existingLicenceNumber", "options": {"widget": "text"}}, {"rule": {"effect": "SHOW", "condition": {"scope": "#/properties/applicationType", "schema": {"const": "RENEWAL"}}}, "type": "Control", "_note": "Drives LATE_RENEWAL_PENALTY. Computed by the frontend from the expiring licence''s own validUntil, not entered free-hand — the calculator cannot compute a date difference itself.", "label": "Days Since Expiry", "scope": "#/properties/daysSinceExpiry", "options": {"widget": "number", "readOnly": true}}, {"type": "Control", "label": "Has a previous licence ever been suspended or revoked?", "scope": "#/properties/hasPreviousLicenceSuspension", "options": {"widget": "checkbox"}}]}]}, {"type": "Category", "label": "Medical & Training", "options": {}, "elements": [{"type": "VerticalLayout", "elements": [{"type": "Control", "label": "Medical Certificate Number (Form 1A)", "scope": "#/properties/medicalCertificateNumber", "options": {"widget": "text"}}, {"type": "Control", "label": "Driving School Name", "scope": "#/properties/drivingSchoolName", "options": {"widget": "text"}}]}]}, {"type": "Category", "label": "Details Printed on the Licence", "options": {}, "elements": [{"type": "VerticalLayout", "elements": [{"type": "Control", "label": "Identification Marks", "scope": "#/properties/identificationMarks", "options": {"rows": 2, "widget": "textarea"}}, {"type": "Control", "label": "I consent to be recorded as an organ donor", "scope": "#/properties/organDonorConsent", "options": {"widget": "checkbox"}}, {"type": "Control", "label": "Emergency Contact Name", "scope": "#/properties/emergencyContactName", "options": {"widget": "text"}}, {"type": "Control", "label": "Emergency Contact Number", "scope": "#/properties/emergencyContactNumber", "options": {"widget": "text"}}]}]}]}]}', 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788439725598, 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788439725598);
