": "category.existingLicence", "options": {}, "elements": [{"type": "VerticalLayout", "elements": [{"rule": {"effect": "SHOW", "condition": {"scope": "#/properties/applicationType", "schema": {"const": "PERMANENT"}}}, "type": "Control", "_note": "Shown only for a permanent-licence application — the learner''s licence is its statutory precondition, and the learner''s licence itself is the separate LEARNER_LICENSE certificate type. jsonforms resolves rule.condition.scope against the form data, independently of the JSON Schema''s own required[]; the schema deliberately leaves this optional so a RENEWAL/DUPLICATE/INTERNATIONAL application validates without it.", "label": "learnerLicenceNumber", "scope": "#/properties/learnerLicenceNumber", "options": {"widget": "text"}}, {"rule": {"effect": "SHOW", "condition": {"scope": "#/properties/applicationType", "schema": {"enum": ["RENEWAL", "DUPLICATE", "INTERNATIONAL"]}}}, "type": "Control", "_note": "Shown for every application filed against a licence the applicant already holds.", "label": "existingLicenceNumber", "scope": "#/properties/existingLicenceNumber", "options": {"widget": "text"}}, {"rule": {"effect": "SHOW", "condition": {"scope": "#/properties/applicationType", "schema": {"const": "RENEWAL"}}}, "type": "Control", "_note": "Drives LATE_RENEWAL_PENALTY. Computed by the frontend from the expiring licence''s own validUntil, not entered free-hand — the calculator cannot compute a date difference itself.", "label": "daysSinceExpiry", "scope": "#/properties/daysSinceExpiry", "options": {"widget": "number", "readOnly": true}}, {"type": "Control", "label": "hasPreviousLicenceSuspension", "scope": "#/properties/hasPreviousLicenceSuspension", "options": {"widget": "checkbox"}}]}]}, {"type": "Category", "label": "category.medicalAndTraining", "options": {}, "elements": [{"type": "VerticalLayout", "elements": [{"type": "Control", "label": "medicalCertificateNumber", "scope": "#/properties/medicalCertificateNumber", "options": {"widget": "text"}}, {"type": "Control", "label": "drivingSchoolName", "scope": "#/properties/drivingSchoolName", "options": {"widget": "text"}}]}]}, {"type": "Category", "label": "category.licenceFaceDetails", "options": {}, "elements": [{"type": "VerticalLayout", "elements": [{"type": "Control", "label": "identificationMarks", "scope": "#/properties/identificationMarks", "options": {"rows": 2, "widget": "textarea"}}, {"type": "Control", "label": "organDonorConsent", "scope": "#/properties/organDonorConsent", "options": {"widget": "checkbox"}}, {"type": "Control", "label": "emergencyContactName", "scope": "#/properties/emergencyContactName", "options": {"widget": "text"}}, {"type": "Control", "label": "emergencyContactNumber", "scope": "#/properties/emergencyContactNumber", "options": {"widget": "text"}}]}]}]}]}', 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788277726838, 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788283180798);
