INSERT INTO "BASETENANT".ui_config (id, module_code, entity_code, channel, schema_id, config_body, created_by, created_time, modified_by, modified_time) VALUES ('7b934cc5-3863-4a27-905f-29339eb95024', 'certificate', 'LEARNER_LICENSE_V2.form.61e6d73a-eb58-4265-9dae-457ea9bdeffa', 'web', 'c7027863-2bf7-4a5b-9d71-ce240353d364', '{"type": "Categorization", "elements": [{"type": "Category", "label": "Learner''s Licence Details", "options": {"stepId": "step-2-learner-details"}, "elements": [{"type": "Category", "label": "Licence Details", "options": {}, "elements": [{"type": "VerticalLayout", "elements": [{"type": "Control", "label": "Application Type", "scope": "#/properties/applicationType", "options": {"widget": "select"}}, {"type": "Control", "label": "Class of Vehicle", "scope": "#/properties/vehicleClass", "options": {"widget": "cascading_dropdown", "categories": [{"code": "nontransport", "name": "Non-Transport", "children": [{"code": "nontransport.mcwog", "name": "Motorcycle without Gear (MCWOG)"}, {"code": "nontransport.mcwg", "name": "Motorcycle with Gear (MCWG)"}, {"code": "nontransport.lmv", "name": "Light Motor Vehicle (LMV)"}, {"code": "nontransport.tractor", "name": "Tractor"}, {"code": "nontransport.invalidcarriage", "name": "Invalid Carriage"}]}, {"code": "transport", "name": "Transport", "children": [{"code": "transport.lmvtr", "name": "Light Motor Vehicle - Transport (LMV-TR)"}, {"code": "transport.hgmv", "name": "Heavy Goods Motor Vehicle (HGMV)"}, {"code": "transport.hpmv", "name": "Heavy Passenger Motor Vehicle (HPMV)"}, {"code": "transport.hazardous", "name": "Hazardous Goods Carrier"}, {"code": "transport.trailer", "name": "Trailer"}]}], "levelLabels": ["Vehicle Class Group", "Vehicle Class"]}}, {"type": "Control", "label": "Date of Birth", "scope": "#/properties/dateOfBirth", "options": {"widget": "date"}}, {"type": "Control", "label": "Blood Group", "scope": "#/properties/bloodGroup", "options": {"widget": "select"}}]}]}, {"type": "Category", "label": "Existing Learner''s Licence", "options": {}, "elements": [{"type": "VerticalLayout", "elements": [{"rule": {"effect": "HIDE", "condition": {"scope": "#/properties/applicationType", "schema": {"const": "FRESH"}}}, "type": "Control", "_note": "Shown for the two application types filed against a learner''s licence the applicant already holds, and required for them by the `else` branch of the schema''s first allOf block — visibility and requiredness have to agree, because the wizard''s sub-screen Next gating does not exempt rule-hidden controls from validation. Written as HIDE-on-FRESH rather than the more obvious SHOW-on-enum[ADDITIONAL_CLASS,DUPLICATE] for a reason that is not cosmetic: @jsonforms/core evaluates either form correctly while the citizen is filling the form, but isElementVisible (packages/shared/src/utils/jsonforms-rule.ts) reads only `const` off condition.schema and compares it with ===, so an `enum` condition resolves to ''no value matches'' and the row silently disappears from everything that util drives — the Confirm step''s summary and buildDynamicDetailSections, i.e. the employee''s application-detail view. The officer would have been unable to see the licence number on precisely the applications that require it. HIDE + const is the complement of the same set and evaluates identically in both engines.", "label": "Existing Learner''s Licence Number", "scope": "#/properties/existingLearnerLicenceNumber", "options": {"widget": "text"}}]}]}, {"type": "Category", "label": "Guardian Consent (applicants under 18)", "options": {}, "elements": [{"type": "VerticalLayout", "elements": [{"type": "Control", "_note": "Always shown rather than gated on age: jsonforms rules resolve against form data with the same equals/enum grammar the calculator has, and ''dateOfBirth is less than 18 years before today'' is not expressible as a condition. An applicant over 18 leaves both fields alone.", "label": "A parent or guardian has consented to this application", "scope": "#/properties/guardianConsentProvided", "options": {"widget": "checkbox"}}, {"rule": {"effect": "SHOW", "condition": {"scope": "#/properties/guardianConsentProvided", "schema": {"const": true}}}, "type": "Control", "label": "Name of Parent or Guardian", "scope": "#/properties/guardianName", "options": {"widget": "text"}}]}]}, {"type": "Category", "label": "Medical Fitness", "options": {}, "elements": [{"type": "VerticalLayout", "elements": [{"type": "Control", "label": "Medical Certificate Number (Form 1A)", "scope": "#/properties/medicalCertificateNumber", "options": {"widget": "text"}}]}]}, {"type": "Category", "label": "Details Printed on the Licence", "options": {}, "elements": [{"type": "VerticalLayout", "elements": [{"type": "Control", "label": "Identification Marks", "scope": "#/properties/identificationMarks", "options": {"rows": 2, "widget": "textarea"}}, {"type": "Control", "label": "Emergency Contact Name", "scope": "#/properties/emergencyContactName", "options": {"widget": "text"}}, {"type": "Control", "label": "Emergency Contact Number", "scope": "#/properties/emergencyContactNumber", "options": {"widget": "text"}}]}]}]}]}', 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788298571641, 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788298571641);
