INSERT INTO "BASETENANT".ui_config (id, module_code, entity_code, channel, schema_id, config_body, created_by, created_time, modified_by, modified_time) VALUES ('4fae668b-5e6e-47c9-9694-c9202d1015d9', 'certificate', 'LEARNER_LICENSE.checklist.59ddb7cd-c745-4a97-90c5-247da42e2ea4', 'web', '17d68a70-db19-475b-8feb-1aff09b9688b', '{"type": "Categorization", "elements": [{"type": "Category", "label": "Theory Test", "options": {"stepId": "theory-test"}, "elements": [{"type": "VerticalLayout", "elements": [{"type": "Control", "label": "Test was conducted", "scope": "#/properties/testConducted", "options": {"widget": "checkbox"}}, {"type": "Control", "label": "Identity verified at the test centre", "scope": "#/properties/identityVerifiedAtCentre", "options": {"widget": "radio"}}, {"type": "Control", "label": "Eyesight Test Result", "scope": "#/properties/eyesightTestResult", "options": {"widget": "radio"}}, {"type": "Control", "label": "Test Mode", "scope": "#/properties/testMode", "options": {"widget": "select"}}, {"type": "Control", "label": "Test Centre Code", "scope": "#/properties/testCentreCode", "options": {"widget": "text"}}, {"type": "Control", "_note": "Required, and 0 is a legal value — an ABSENT candidate is recorded as 0 rather than left blank, because the schema requires the field and there is no null.", "label": "Theory Test Score (out of 15)", "scope": "#/properties/theoryTestScore", "options": {"widget": "number"}}, {"type": "Control", "label": "Theory Test Result", "scope": "#/properties/theoryTestResult", "options": {"widget": "radio"}}, {"type": "Control", "label": "Examiner''s Remarks", "scope": "#/properties/examinerRemarks", "options": {"widget": "textarea"}}]}]}]}', 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788439662171, 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788439662171);
INSERT INTO "BASETENANT".ui_config (id, module_code, entity_code, channel, schema_id, config_body, created_by, created_time, modified_by, modified_time) VALUES ('18cf8f56-22a0-4203-b889-740f0387cb2b', 'certificate', 'FOOD_LICENSE.form.3136481e-e525-47e3-862e-f12b9b8967c0', 'web', 'bbf5b4a7-f733-441b-8486-5c1d4cb9d180', '{"type": "Categorization", "elements": [{"type": "Category", "label": "Licence Details", "options": {"stepId": "step-2-licence-details"}, "elements": [{"type": "Category", "label": "Authorisation and Activity", "options": {}, "elements": [{"type": "VerticalLayout", "elements": [{"type": "Control", "label": "Application Type", "scope": "#/properties/applicationType", "options": {"widget": "select"}}, {"type": "Control", "_note": "Constrained server-side: handlesAnimalOrigin true forces APPROVAL, and turnover above the ceiling rules out REGISTRATION. Both are allOf blocks in the schema, so the UI cannot be the only thing enforcing them.", "label": "Authorisation Class", "scope": "#/properties/licenceClass", "options": {"widget": "radio"}}, {"type": "Control", "_note": "Set from the first segment of the cascading selection below. Its own field because ACTIVITY_FEE matches it with equals and the condition grammar has no prefix operator.", "label": "Activity Group", "scope": "#/properties/activityGroup", "options": {"widget": "select"}}, {"type": "Control", "label": "Activity", "scope": "#/properties/activityPath", "options": {"widget": "cascading_dropdown", "categories": [{"code": "manufacturing", "name": "Manufacturing and Processing", "children": [{"code": "manufacturing.processing", "name": "General Food Processing"}, {"code": "manufacturing.dairy", "name": "Dairy Processing"}, {"code": "manufacturing.meat", "name": "Meat, Poultry and Fish Processing"}]}, {"code": "retail", "name": "Retail", "children": [{"code": "retail.shop", "name": "Food Shop"}, {"code": "retail.market", "name": "Market Stall"}]}, {"code": "foodservice", "name": "Food Service", "children": [{"code": "foodservice.restaurant", "name": "Restaurant"}, {"code": "foodservice.catering", "name": "Catering"}, {"code": "foodservice.institutional", "name": "Institutional Kitchen"}]}, {"code": "logistics", "name": "Storage and Transport", "children": [{"code": "logistics.storage", "name": "Storage and Warehousing"}, {"code": "logistics.transport", "name": "Food Transport"}]}, {"code": "trade", "name": "Trade", "children": [{"code": "trade.import", "name": "Import and Export"}, {"code": "trade.wholesale", "name": "Wholesale and Distribution"}]}], "levelLabels": ["Activity Group", "Activity"]}}, {"type": "Control", "_note": "The PER_UNIT multiplier on the licence fee. NOT the field that stamps validUntil — that is the envelope''s requestedValidityDays, which the calculator cannot see.", "label": "Licence Term (Years)", "scope": "#/properties/licenceTermYears", "options": {"max": 5, "min": 1, "widget": "number"}}]}]}, {"type": "Category", "label": "Scale and Risk", "options": {}, "elements": [{"type": "VerticalLayout", "elements": [{"type": "Control", "_note": "Whole currency units. The licence-fee band; integer so adjacent bands need no epsilon.", "label": "Annual Turnover", "scope": "#/properties/annualTurnover", "options": {"min": 0, "step": 1, "widget": "number"}}, {"type": "Control", "_note": "Drives the SLAB inspection fee — a genuinely marginal rate, unlike the banded licence fee.", "label": "Premises Area (sq m)", "scope": "#/properties/premisesAreaSqm", "options": {"min": 0, "widget": "number"}}, {"type": "Control", "label": "Handles Product of Animal Origin", "scope": "#/properties/handlesAnimalOrigin", "options": {"widget": "checkbox"}}, {"type": "Control", "label": "Product Categories", "scope": "#/properties/productCategories", "options": {"widget": "multiselect"}}]}]}, {"type": "Category", "label": "Food Safety Compliance", "options": {}, "elements": [{"type": "VerticalLayout", "elements": [{"rule": {"effect": "SHOW", "condition": {"scope": "#/properties/licenceClass", "schema": {"enum": ["STANDARD", "APPROVAL"]}}}, "type": "Control", "_note": "Required for APPROVAL. Its mere presence also earns the HACCP rebate, so it is shown for STANDARD too.", "label": "HACCP Plan Reference", "scope": "#/properties/haccpPlanRef", "options": {"widget": "text", "placeholder": "HACCP-XXXX"}}]}]}, {"type": "Category", "label": "Previous Licence", "options": {}, "elements": [{"type": "VerticalLayout", "elements": [{"rule": {"effect": "SHOW", "condition": {"scope": "#/properties/applicationType", "schema": {"enum": ["RENEWAL", "VARIATION", "DUPLICATE"]}}}, "type": "Control", "_note": "Required for everything except NEW, and FORBIDDEN for NEW — the schema''s if/then/else enforces both directions.", "label": "Previous Licence Number", "scope": "#/properties/previousLicenceNumber", "options": {"widget": "text"}}, {"rule": {"effect": "SHOW", "condition": {"scope": "#/properties/applicationType", "schema": {"const": "RENEWAL"}}}, "type": "Control", "_note": "Frontend-computed from the expiring licence''s validUntil; the engine cannot do date arithmetic. Bands the penalty and the interest rules.", "label": "Days Since Expiry", "scope": "#/properties/daysSinceExpiry", "options": {"widget": "number", "readOnly": true}}]}]}, {"type": "Category", "label": "Premises and Outlets", "options": {}, "elements": [{"type": "VerticalLayout", "elements": [{"type": "Control", "_note": "Optional, except for logistics. Each element is priced separately by the SUBENTITY rule and summed by the AGGREGATION rule; an absent array yields no line items and a derived staff total of 0.", "label": "Outlets", "scope": "#/properties/outlets", "options": {"detail": {"highRisk": {"widget": "checkbox"}, "openedOn": {"widget": "date"}, "outletCode": {"widget": "text"}, "staffCount": {"widget": "number"}}, "widget": "array"}}]}]}]}]}', 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788439834271, 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788439834271);
INSERT INTO "BASETENANT".ui_config (id, module_code, entity_code, channel, schema_id, config_body, created_by, created_time, modified_by, modified_time) VALUES ('0528cafc-4357-4719-912c-3b3c19b684b3', 'certificate', 'FOOD_LICENSE.checklist.e504a163-a165-4ab6-a479-60a5913be4cc', 'web', 'bdf132ff-81cd-49d8-afee-c24222713862', '{"type": "Categorization", "elements": [{"type": "Category", "label": "Food Safety Inspection", "options": {"stepId": "food-safety-inspection"}, "elements": [{"type": "VerticalLayout", "elements": [{"type": "Control", "label": "Inspection Passed", "scope": "#/properties/inspectionPassed", "options": {"widget": "checkbox"}}, {"type": "Control", "label": "Date of Inspection", "scope": "#/properties/inspectionDate", "options": {"widget": "date"}}, {"type": "Control", "label": "Risk Rating", "scope": "#/properties/riskRating", "options": {"widget": "radio"}}, {"type": "Control", "label": "Hygiene Score (0-100)", "scope": "#/properties/hygieneScore", "options": {"max": 100, "min": 0, "step": 5, "widget": "number"}}, {"type": "Control", "label": "Non-Conformities Found", "scope": "#/properties/nonConformities", "options": {"widget": "multiselect"}}, {"type": "Control", "label": "Evidence Photographs", "scope": "#/properties/evidencePhotos", "options": {"accept": ["image/*", "application/pdf"], "widget": "file", "multiple": true}}, {"type": "Control", "label": "Inspector''s Notes", "scope": "#/properties/inspectorNotes", "options": {"rows": 4, "widget": "textarea"}}, {"rule": {"effect": "SHOW", "condition": {"scope": "#/properties/riskRating", "schema": {"const": "HIGH"}}}, "type": "Control", "_note": "Required by the checklist schema''s own if/then when riskRating is HIGH. The UI rule only hides it; the validator is what enforces it.", "label": "Corrective Action Due By", "scope": "#/properties/correctiveActionDueBy", "options": {"widget": "date"}}]}]}]}', 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788439834574, 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1788439834574);
INSERT INTO "BASETENANT".ui_config (id, module_code, entity_code, channel, schema_id, config_body, created_by, created_time, modified_by, modified_time) VALUES ('d8dd81d3-fa94-44a9-809d-55650e7cb954', 'certificate', 'LEARNER_LICENSE.form.b5a00577-ea80-491f-9666-b2f5e45f5d87', 'web', 'cc26918b-f6cd-4780-bbf7-e43f54d11283', '{"type": "Categorization", "elements": [{"type": "Category", "label": "Learner''s Licence Details", "options": {"stepId": "step-2-learner-details"}, "elements": [{"type": "Category", "label": "Licence Details", "options": {}, "elements": [{"type": "VerticalLayout", "elements": [{"type": "Control", "label": "Application Type", "scope": "#/properties/applicationType", "options": {"widget": "select"}}, {"type": "Control", "label": "Class of Vehicle", "scope": "#/properties/vehicleClass", "options": {"widget": "cascading_dropdown", "categories": [{"code": "nontransport", "name": "Non-Transport", "children": [{"code": "nontransport.mcwog", "name": "Motorcycle without Gear (MCWOG)"}, {"code": "nontransport.mcwg", "name": "Motorcycle with Gear (MCWG)"}, {"code": "nontransport.lmv", "name": "Light Motor Vehicle (LMV)"}, {"code": "nontransport.tractor", "name": "Tractor"}, {"code": "nontransport.invalidcarriage", "name": "Invalid Carriage"}]}, {"code": "transport", "name": "Transport", "children": [{"code": "transport.lmvtr", "name": "Light Motor Vehicle - Transport (LMV-TR)"}, {"code": "transport.hgmv", "name": "Heavy Goods Motor Vehicle (HGMV)"}, {"code": "transport.hpmv", "name": "Heavy Passenger Motor Vehicle (HPMV)"}, {"code": "transport.hazardous", "name": "Hazardous Goods Carrier"}, {"code": "transport.trailer", "name": "Trailer"}]}], "levelLabels": ["Vehicle Class Group", "Vehicle Class"]}}, {"type": "Control", "label": "Date of Birth", "scope": "#/properties/dateOfBirth", "options": {"widget": "date"}}, {"type": "Control", "label": "Blood Group", "scope": "#/properties/bloodGroup", "options": {"widget": "select"}}]}]}, {"type": "Category", "label": "Existing Learner''s Licence", "options": {}, "elements": [{"type": "VerticalLayout", "elements": [{"rule": {"effect": "SHOW", "condition": {"scope": "#/properties/applicationType", "schema": {"not": {"const": "FRESH"}}}}, "type": "Control", "_note": "Shown for the two application types filed against a learner''s licence the applicant already holds, and required for them by allOf[1] of the schema - visibility and requiredness have to agree, because the wizard''s sub-screen Next gating does not exempt rule-hidden controls from validation. SHOW on not/const, rather than HIDE on const or the obvious SHOW on enum[ADDITIONAL_CLASS,DUPLICATE]. History: an enum condition used to break the employee''s application-detail view, because isElementVisible read only const off condition.schema and compared it with ===, so an enum resolved to ''no value matches'' and the row disappeared from the Confirm summary and buildDynamicDetailSections. Fixed in 57b2cc1 - evaluateCondition now runs the real formAjv over condition.schema, so not/enum evaluate correctly. HIDE was the workaround for that and is no longer needed; it is avoided because the admin forms builder only authors SHOW (formsBuilderSchema.ts ruleFromControl), so a HIDE rule makes the field unrepresentable and blocks Save on the whole form. not/const round-trips through the builder''s own notEquals operator. failWhenUndefined is deliberately NOT set: ajv matches undefined against not/const, so the field stays visible before applicationType is answered - exactly as it behaved under HIDE.", "label": "Existing Learner''s Licence Number", "scope": "#/properties/existingLearnerLicenceNumber", "options": {"widget": "text"}}]}]}, {"type": "Category", "label": "Guardian Consent (applicants under 18)", "options": {}, "elements": [{"type": "VerticalLayout", "elements": [{"type": "Control", "_note": "Always shown rather than gated on age: jsonforms rules resolve against form data with the same equals/enum grammar the calculator has, and ''dateOfBirth is less than 18 years before today'' is not expressible as a condition. An applicant over 18 leaves both fields alone.", "label": "A parent or guardian has consented to this application", "scope": "#/properties/guardianConsentProvided", "options": {"widget": "checkbox"}}, {"rule": {"effect": "SHOW", "condition": {"scope": "#/properties/guardianConsentProvided", "schema": {"const": true}}}, "type": "Control", "label": "Name of Parent or Guardian", "scope": "#/properties/guardianName", "options": {"widget": "text"}}]}]}, {"type": "Category", "label": "Medical Fitness", "options": {}, "elements": [{"type": "VerticalLayout", "elements": [{"type": "Control", "label": "Medical Certificate Number (Form 1A)", "scope": "#/properties/medicalCertificateNumber", "options": {"widget": "text"}}]}]}, {"type": "Category", "label": "Details Printed on the Licence", "options": {}, "elements": [{"type": "VerticalLayout", "elements": [{"type": "Control", "label": "Identification Marks", "scope": "#/properties/identificationMarks", "options": {"rows": 2, "widget": "textarea"}}, {"type": "Control", "label": "Emergency Contact Name", "scope": "#/properties/emergencyContactName", "options": {"widget": "text"}}, {"type": "Control", "label": "Emergency Contact Number", "scope": "#/properties/emergencyContactNumber", "options": {"widget": "text"}}]}]}]}]}', 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1790240683783, 'e2df874c-b93e-42d3-82cf-d5452f4af31a', 1790240683783);
